extern "C" uint64_t g_load_complete_n;

extern "C" void* sub_8fc330_impl(State*, uint32_t, void*);
static std::atomic<uint64_t> g_deq_in{0}, g_deq_out{0};
static uint32_t g_deq_obj[6]; static int g_deq_objn = 0;
extern "C" __attribute__((used)) void* bo2_deq(State* s, uint32_t pc, void* mem) {
    const uint32_t obj = s->gpr.rcx.dword;
    g_deq_in.fetch_add(1, std::memory_order_relaxed);
    bool seen = false;
    for (int i = 0; i < g_deq_objn; ++i) if (g_deq_obj[i] == obj) { seen = true; break; }
    if (!seen && g_deq_objn < 6) g_deq_obj[g_deq_objn++] = obj;
    void* r = sub_8fc330_impl(s, pc, mem);
    g_deq_out.fetch_add(1, std::memory_order_relaxed);
    return r;
}
// ── [REGS] — EVERY GUEST THREAD'S REGISTERS, AND WHETHER THEY MOVED ─────────
//
// Written after an entry/exit wrapper on sub_8fc330 read ZERO while [SPIN-HIST]
// put the innermost frame inside it in two consecutive runs. nm says no other
// symbol lies within 0x400 of sub_8fc330_impl, so the backtrace was right and
// the WRAPPER was blind: the function is reached by indirect dispatch, which the
// symbol redirect does not cover. So stop asking the call edge and read the
// coroutine State directly, which no dispatch can hide.
//
// It prints EVERY thread including the healthy ones, and says whether each
// moved since the previous sample. "tid 7 sits at esp=X" means nothing alone;
// "tid 7 sits at esp=X and X is where it was last time" is the finding, and a
// thread that moved is what clears it of suspicion.
//
// For the CAS loop at 0x8fc330 the interesting register is EDI: the function
// opens `mov edi, ecx`, so EDI holds the queue object for the whole loop, and
// that is exactly what BO2_QUEUE_PROBE needs in order to watch the RIGHT queue
// rather than one that merely happens to be idle.
extern "C" void* win32_thread_state(int idx);   // declared void* elsewhere in this file
extern "C" void win32_all_regs_report() {
    static uint32_t prev_esp[24], prev_eip_like[24];
    static bool seen[24];
    // 🎯 AND THE LOCK DEPTH — the number that decides which repair to write.
    // If the wedged coroutine is holding a guest critical section, a "yield only
    // at depth 0" guard can never fire on it and would measure a no-op; the fix
    // would then have to be coroutine-aware guest critical sections. If it holds
    // none, the guard preserves mutual exclusion exactly and the preemption A/B
    // becomes interpretable. Printed beside `running tid=` so the two are never
    // read apart.
    {
        unsigned long long under = 0, tot = 0;
        win32_cs_depth_counts(&under, &tot);
        fprintf(stderr, "[CS-DEPTH] running tid=%d holds %d guest critical section(s); "
                        "%llu of %llu import dispatches (%.1f%%) happened under a lock\n",
                win32_current_tid(), win32_cs_depth_of(win32_current_tid()),
                under, tot, tot ? 100.0 * (double)under / (double)tot : 0.0);
        for (int t = 0; t < 16; t++) {
            const int d = win32_cs_depth_of(t);
            if (d > 0) fprintf(stderr, "[CS-DEPTH]   tid%-2d depth=%d\n", t, d);
        }
        {
            const int rt = win32_current_tid();
            // 🎯 DID PREEMPTION EVEN REACH THIS COROUTINE? Deltas since the last
            // freeze report, not totals — a total cannot answer "what changed at
            // the freeze", which is this repo's own retraction R116.
            {
                unsigned long long tk=0, fi=0, rl=0, rc=0;
                win32_preempt_counts(rt, &tk, &fi, &rl, &rc);
                static unsigned long long p_tk=0, p_fi=0, p_rl=0, p_rc=0;
                fprintf(stderr, "[PREEMPT] tid=%d imports=%llu(+%llu) fired=%llu(+%llu) "
                                "refused-lock=%llu(+%llu) refused-cb=%llu(+%llu)%s\n",
                        rt, tk, tk-p_tk, fi, fi-p_fi, rl, rl-p_rl, rc, rc-p_rc,
                        (tk - p_tk) == 0
                            ? "   <- MAKES NO IMPORTS: an import-counter preemption can never reach it"
                            : ((fi - p_fi) == 0 ? "   <- reached by imports but never preempted" : ""));
                p_tk=tk; p_fi=fi; p_rl=rl; p_rc=rc;
            }
            // Meme question pour la preemption comptee sur les ECRITURES, tenue
            // a part : sans ca, « fired » ne dirait plus lequel des deux
            // mecanismes a tire, et l'experience serait ininterpretable.
            {
                unsigned long long fi=0, rl=0, rc=0, ul=0;
                win32_preempt_w_counts(rt, &fi, &rl, &rc, &ul);
                static unsigned long long q_fi=0, q_rl=0, q_rc=0, q_ul=0;
                fprintf(stderr, "[PREEMPT-W] tid=%d every=%llu fired=%llu(+%llu) "
                                "refused-lock=%llu(+%llu) refused-cb=%llu(+%llu) "
                                "sous-verrou=%llu(+%llu)%s\n",
                        rt, (unsigned long long)g_w32_preempt_every,
                        fi, fi-q_fi, rl, rl-q_rl, rc, rc-q_rc, ul, ul-q_ul,
                        g_w32_preempt_every == 0 ? "   <- desarme"
                        : (fi - q_fi) == 0
                            ? "   <- ARME MAIS N'A PAS TIRE sur cette coroutine"
                            : "");
                q_fi=fi; q_rl=rl; q_rc=rc; q_ul=ul;
            }
            // P645 : qui tient le verrou des sequences `lock`, et combien de cedes
            // ont ete differes a sa sortie.
            bo2_hwa_freeze_line();
            // Le compte EXACT, que le bridage aux puissances de deux ne donne pas.
            fprintf(stderr, "[LOAD-COMPLETE-TOTAL] %llu images serveur (SV_Frame)\n",
                    (unsigned long long)g_load_complete_n);
            fprintf(stderr, "[VM-DEPTH] running tid=%d is %s the GSC VM (depth=%d, max seen=%d)\n",
                    rt, win32_gsc_depth_of(rt) > 0 ? "INSIDE" : "outside",
                    win32_gsc_depth_of(rt), win32_gsc_depth_max_of(rt));
            for (int t = 0; t < 16; t++)
                if (win32_gsc_depth_of(t) > 0)
                    fprintf(stderr, "[VM-DEPTH]   tid%-2d depth=%d (max %d)\n",
                            t, win32_gsc_depth_of(t), win32_gsc_depth_max_of(t));
        }
    }
    fprintf(stderr, "[REGS] every guest thread's registers (running tid=%d):\n", win32_current_tid());
    for (int i = 0; i < 24; ++i) {
        State* st = (State*)win32_thread_state(i);
        if (!st) continue;
        const uint32_t esp = st->gpr.rsp.dword, edi = st->gpr.rdi.dword;
        const uint32_t ecx = st->gpr.rcx.dword, esi = st->gpr.rsi.dword;
        const uint32_t eax = st->gpr.rax.dword, ebx = st->gpr.rbx.dword;
        const bool moved = !seen[i] || esp != prev_esp[i] || eax != prev_eip_like[i];
        fprintf(stderr, "[REGS]   tid%-2d esp=%08x eax=%08x ebx=%08x ecx=%08x esi=%08x edi=%08x  %s\n",
                i, esp, eax, ebx, ecx, esi, edi,
                seen[i] ? (moved ? "moved" : "UNCHANGED since last sample") : "(first sample)");
        prev_esp[i] = esp; prev_eip_like[i] = eax; seen[i] = true;
    }
}

extern "C" void win32_deq_report() {
    const uint64_t in = g_deq_in.load(), out = g_deq_out.load();
    fprintf(stderr, "[DEQ] sub_8fc330 entered %llu time(s), returned %llu -- %s\n",
            (unsigned long long)in, (unsigned long long)out,
            (in > out + 1) ? "STUCK INSIDE the CAS loop (the loop must be patched; a wrapper cannot help)"
                           : "it RETURNS, so the spin belongs to the CALLER");
    for (int i = 0; i < g_deq_objn; ++i)
        fprintf(stderr, "[DEQ]   queue object 0x%08x\n", g_deq_obj[i]);
}

extern "C" void* sub_42f960_impl(State*, uint32_t, void*);
extern "C" __attribute__((used)) void* bo2_snd_check(State* s, uint32_t pc, void* mem) {
    const uint32_t armed = win32_mem_read32(0x2f49404u);
    const uint32_t can   = win32_mem_read32(0x2f49400u);
    static uint64_t n = 0, bad = 0;
    ++n;
    // 🎯 BO2_SND_ARM=<N> — ARM THE STORE WATCH LATE, WHERE IT IS AFFORDABLE.
    //
    // BO2_WATCH_WRITE=2f49400 from the start kills the run at ~10 s (measured
    // twice): arming any watch forces the runtime's byte loops. But the
    // corruption is LATE — the canary survives 23,168 checks and then flips to
    // 19,804 — so the watch only needs to exist for the last stretch. Add the
    // address to the live watch list once the canary has been seen intact N
    // times, and the whole load runs at full speed first.
    {
        static const long arm_at = [] {
            const char* e = bo2_getenv("BO2_SND_ARM");
            return e ? atol(e) : 0L;
        }();
        static bool done = false;
        if (arm_at > 0 && !done && n >= (uint64_t)arm_at && can == 0x23459876u) {
            done = true;
            if (g_wwn < 0) ww_parse();
            if (g_wwn < kWwMax) {
                g_ww[g_wwn++] = 0x2f49400u;
                fprintf(stderr, "\n🎯 [SND-ARM] canary still intact after %llu checks — the store "
                        "watch on [0x2f49400] is armed NOW, so the next write to it is caught "
                        "with its call chain, and the load ran at full speed first.\n\n",
                        (unsigned long long)n);
            } else {
                fprintf(stderr, "[SND-ARM] ⚠️ all %d watch slots are in use; NOT armed\n", kWwMax);
            }
        }
    }
    // ── 🎯 BO2_SPIN_YIELD=1 — LET A GUEST SPINLOCK YIELD ────────────────────
    //
    // 0x4b4870 is a spinlock ACQUIRE, and this function is its retry body:
    //
    //     0x4b4872  lock cmpxchg [edx], ecx   ; try to take it
    //     0x4b4878  je 0x4b48a6               ; taken -> proceed
    //     0x4b4880  call 0x42f960             ; FAILED -> us
    //     0x4b488a  call 0x484620             ; ...then round again
    //
    // Which is also why this canary check ran 23,169 times: that was never a
    // sound-system cadence, it was the SPIN COUNT of a lock.
    //
    // On real hardware another core releases the lock. Here fourteen guest
    // threads share ONE host thread cooperatively, so a spin loop that never
    // yields makes the holder unrunnable BY CONSTRUCTION — the wait can only end
    // if the waiter gives the scheduler a turn. The port already does exactly this
    // for the InterlockedCompareExchange IMPORT (spin_yield_check, "PAUSE-then-
    // yield is what a real spinlock does on a single core anyway"); a raw
    // `lock cmpxchg` in lifted code never reaches that helper, and this is the
    // same fix applied at the only hook the loop offers.
    //
    // Gated on the return address so it fires for THIS loop and nothing else:
    // sub_42f960 has other, legitimate callers and yielding in them would be a
    // behaviour change nobody asked for.
    {
        static const bool spin_yield = bo2_getenv("BO2_SPIN_YIELD") != nullptr;
        if (spin_yield) {
            const uint32_t ret = win32_mem_read32(s->gpr.rsp.dword);
            if (ret == 0x004b4885u) {
                static uint64_t y = 0;
                if (++y <= 3 || (y % 20000) == 0)
                    fprintf(stderr, "[SPIN-YIELD #%llu] spinlock at 0x4b4872 still held — "
                            "yielding so its owner can run\n", (unsigned long long)y);
                win32_coop_yield();
            }
        }
    }
    // ── BO2_SND_HEAL=1 — AN EXPERIMENT, NOT A FIX ───────────────────────────
    //
    // The real defect is upstream: sub_87e2e0 walks a linked chain writing four
    // bytes per link through the bump cursor [inst*0x42a8 + 0x2f3b8c8] with NO
    // bound, and runs off the end into these two dwords. Healing the canary here
    // hides that overrun rather than repairing it — whatever else lies past the
    // buffer is still being smashed.
    //
    // It is worth one run because it answers the only question that decides
    // where to spend the next hours: is this Com_Error the LAST thing holding
    // SV_Frame at its setjmp pad? If the frame advances with the canary healed,
    // the overrun is the final blocker and deserves a real bound. If it does not,
    // we have saved ourselves from fixing the wrong thing.
    if (can != 0x23459876u && bo2_getenv("BO2_SND_HEAL")) {
        static uint64_t healed = 0;
        win32_mem_write32(0x2f49400u, 0x23459876u);
        if (++healed <= 4 || (healed % 1000) == 0)
            fprintf(stderr, "[SND-HEAL #%llu] canary was 0x%08x at check #%llu — restored "
                    "(EXPERIMENT: the sub_87e2e0 overrun is NOT repaired)\n",
                    (unsigned long long)healed, can, (unsigned long long)n);
        return sub_42f960_impl(s, pc, mem);
    }
    const bool will_raise = (armed != 0) && (can != 0x23459876u);
    if (will_raise) ++bad;
    if (will_raise || n <= 4 || (n % 20000) == 0)
        fprintf(stderr, "%s[SND-CHECK #%llu] armed=%u canary=0x%08x%s\n",
                will_raise ? "\n🎯 " : "", (unsigned long long)n, armed, can,
                will_raise ? "   <- RAISES Com_Error and longjmps SV_Frame back to its "
                             "setjmp pad" : "");
    return sub_42f960_impl(s, pc, mem);
}
// 🎯 THE TWO NUMBERS THAT MUST MATCH. With lpThreadId fixed the save opens and
// the error becomes GAME_SAVE_INSUFFICIENT_FREE_DISK — a misleading name: the
// check at 0x52a022 is `cmp edi, esi ; je`, esi from sub_7eda80 (expected size)
// and edi from THIS function (a save-operation dispatcher on arg 3, whose
// default return is the error code 0x1b39 = 6969). Print args and result.
extern "C" void* sub_684c30_impl(State*, uint32_t, void*);
extern "C" __attribute__((used)) void* bo2_save_op(State* s, uint32_t pc, void* mem) {
    static const bool log = bo2_getenv("BO2_FS_OPEN") != nullptr;
    uint32_t a1 = 0, a2 = 0, a3 = 0;
    if (__builtin_expect(log, 0)) {
        a1 = win32_mem_read32(s->gpr.rsp.dword + 4u);
        a2 = win32_mem_read32(s->gpr.rsp.dword + 8u);
        a3 = win32_mem_read32(s->gpr.rsp.dword + 0xcu);
    }
    void* r = sub_684c30_impl(s, pc, mem);
    if (__builtin_expect(log, 0)) {
        static uint64_t n = 0;
        const uint32_t ret = s->gpr.rax.dword;
        if (++n <= 20)
            fprintf(stderr, "[SAVE-OP] op=%u a1=0x%08x a2=0x%08x -> %u%s\n",
                    a3, a1, a2, ret,
                    ret == 0x1b39u ? "   🎯 = 0x1b39, the dispatcher's ERROR default" : "");
    }
    return r;
}
// 🎯 WHICH THREAD ASKS TO SAVE, AND DOES THE DISPATCHER RECOGNISE IT?
//
// sub_4c5e70 is a chain of five thread-identity predicates (0x80df30 reading
// fs:[0x2c], 0x5be020, 0x499ce0, 0x4deaf0, 0x528470=bo2_is_main_thread); each
// match calls sub_838a20 with a different mode, and NO match falls through
// returning 0 — which becomes Com_Error("SaveDevice_PC…"), [0x287bb30]=1, and a
// permanently parked SV_Frame. sub_838a20's own interpose logged nothing, which
// is what proved the fall-through. This names the caller's tid and the verdict.
extern "C" void* sub_4c5e70_impl2(State*, uint32_t, void*);
extern "C" __attribute__((used)) void* bo2_fs_dispatch(State* s, uint32_t pc, void* mem) {
    static const bool log = bo2_getenv("BO2_FS_OPEN") != nullptr;
    char nm[160]; nm[0] = 0;
    if (__builtin_expect(log, 0)) {
        const uint32_t np = win32_mem_read32(s->gpr.rsp.dword + 4u);
        uint32_t k = 0;
        for (; np > 0x1000u && k < sizeof nm - 1; k++) {
            const uint8_t c = win32_mem_read8(np + k);
            if (!c) break;
            nm[k] = (c >= 0x20 && c <= 0x7e) ? (char)c : '.';
        }
        nm[k] = 0;
    }
    const int tid = win32_current_tid();
    // 🎯 THE FIVE KNOWN-THREAD GLOBALS, AND WHAT THIS CALLER'S ID ACTUALLY IS.
    // Each predicate is the same template — cache GetCurrentThreadId() in the
    // per-thread block at [edx+0x60] reached through fs:[0x2c], then compare it
    // to ONE global. Read all five plus the caller's cached id and the answer is
    // either "our GetCurrentThreadId is inconsistent" or "nobody ever recorded
    // this thread", which need different fixes.
    if (__builtin_expect(log, 0)) {
        static bool once = false;
        if (!once) {
            once = true;
            const uint32_t g[5] = {0x2925588u, 0x292558cu, 0x29255b0u, 0x29255b4u, 0x29255b8u};
            const char* nmg[5] = {"0x80df30", "0x4deaf0", "0x528470(main)", "0x5be020", "0x499ce0"};
            char line[400]; size_t q = 0;
            q += (size_t)snprintf(line + q, sizeof line - q,
                                  "[FS-IDENT] the five known-thread ids:");
            for (int i = 0; i < 5; i++)
                q += (size_t)snprintf(line + q, sizeof line - q, "  %s=%u",
                                      nmg[i], win32_mem_read32(g[i]));
            fprintf(stderr, "%s\n", line);
        }
    }
    void* r = sub_4c5e70_impl2(s, pc, mem);
    if (__builtin_expect(log, 0)) {
        static uint64_t n = 0;
        const uint32_t ret = s->gpr.rax.dword;
        if (++n <= 40 || !ret)
            fprintf(stderr, "[FS-DISPATCH] \"%s\" tid=%d GetCurrentThreadId=%u -> %s\n",
                    nm, tid, 0x1000u + (uint32_t)tid,
                    ret ? "a predicate matched (opened)"
                        : "🎯 NO PREDICATE MATCHED — this tid is none of the engine's "
                          "known threads, so the save is refused and SV_Frame parks");
    }
    return r;
}
// 🎯 sub_838a20 — THE OPEN THAT FAILS AND PARKS THE FRAME LOOP.
