extern "C" __attribute__((used)) void* bo2_sl_get(State* s, uint32_t pc, void* mem) {
    {   const uint32_t raw0 = win32_mem_read32(s->gpr.rsp.dword);
        const uint32_t r0 = (raw0 > 0xa40000u) ? (raw0 & 0x00ffffffu) : raw0;
        ++g_sg_n;
        int k = 0; for (; k < g_sg_used; k++) if (g_sg_va[k] == r0) break;
        if (k == g_sg_used && g_sg_used < 64) g_sg_va[g_sg_used++] = r0;
        if (k < 64) ++g_sg_cnt[k];
    }
    // 🎯 THE OTHER INTERNER. bo2_intern (sub_64d340) minted NO id in the band
    // around the missing key 0x11ac, so the key comes from this table instead —
    // this port is known to carry two (GSC instance 0 vs 1). Same one-compare
    // capture, same band, so the cost stays where it was.
    // ⚠️ getenv() ON A HOT PATH. The first version called getenv on EVERY
    // invocation of SL_GetString — one of the hottest functions in the engine —
    // and the level stopped loading, exactly like the two earlier attempts. The
    // gate has to be resolved ONCE. Third time the same species of mistake in one
    // session: a diagnostic that changes whether the run happens is not a
    // diagnostic.
    static const uint32_t wid = [] {
        const char* e = bo2_getenv("BO2_SL_NAME_ID");
        return e ? (uint32_t)strtoul(e, nullptr, 16) & 0xffffu : 0u;
    }();
    if (__builtin_expect(wid != 0u, 0)) {
        const uint32_t p0 = win32_mem_read32(s->gpr.rsp.dword + 4u);
        void* r0 = sub_5cdf90_impl(s, pc, mem);
        const uint32_t id = s->gpr.rax.dword & 0xffffu;
        // BO2_SL_NAME_ID=ffff captures EVERY id, not a band. The read is
        // deduplicated by the map, so each distinct id costs one short string read
        // once — ~10k of them, against the 140k x 80 that cost the level its load
        // twice. The band remains for narrower hunts.
        const bool take = (wid == 0xffffu)
                        || (id >= (wid & 0xff00u) - 0x100u && id <= (wid & 0xff00u) + 0x200u);
        if (take && !g_sl_names_ptr()->count(id)) {
            char nm[80]; int n = 0;
            while (n < 79) { const uint8_t c = win32_mem_read8(p0 + n);
                             if (c < 0x20 || c > 0x7e) break; nm[n++] = (char)c; }
            nm[n] = 0;
            if (n) (*g_sl_names_ptr())[id] = nm;
        }
        return r0;
    }
    static const bool who = bo2_getenv("BO2_ALLOC_WHO") != nullptr;
    if (__builtin_expect(who, 0)) {
        const uint32_t raw = win32_mem_read32(s->gpr.rsp.dword);
        const uint32_t r = (raw > 0xa40000u) ? (raw & 0x00ffffffu) : raw;
        int i = 0;
        for (; i < g_slget_used; i++) if (g_slget_va[i] == r) break;
        if (i == g_slget_used && g_slget_used < 12) g_slget_va[g_slget_used++] = r;
        if (i < 12) ++g_slget_n[i];
    }
    {   static uint64_t n = 0;
        const uint64_t before = g_pop_seen;
        const uint32_t p0 = win32_mem_read32(s->gpr.rsp.dword + 4u);
        void* r = sub_5cdf90_impl(s, pc, mem);
        if ((++n % 500u) == 0u) {
            char* b = g_sls_ring[g_sls_n % 48]; int i = 0;
            for (; i < 39; i++) { const uint8_t c = win32_mem_read8(p0 + (uint32_t)i); if (!c) break; b[i] = (c >= 32 && c < 127) ? (char)c : '.'; }
            b[i] = 0; g_sls_alloc[g_sls_n % 48] = (g_pop_seen != before); g_sls_n++;
        }
        return r;
    }
}
