static uint64_t g_ti_lost;
extern "C" void bo2_threadinstall_report(const char* why) {
    fprintf(stderr, "\n[THREAD-INSTALL] ==== the thread sub_87e2e0 makes current (%s) ====\n",
            why ? why : "");
    fprintf(stderr, "[THREAD-INSTALL] installs=%llu  with a ZERO self=%llu  distinct such "
            "records=%d  dropped=%llu%s\n",
            (unsigned long long)g_ti_n, (unsigned long long)g_ti_zero, g_ti_seen,
            (unsigned long long)g_ti_lost,
            g_ti_n == 0 ? "   <<< NEVER RAN" : "");
    for (int i = 0; i < g_ti_seen; i++)
        fprintf(stderr, "[THREAD-INSTALL]   rec 0x%04x\n", g_ti_idx[i]);
    fprintf(stderr, "[THREAD-INSTALL] ==== end ====\n\n");
}
static void bo2_threadinstall_note(void) {
    const uint32_t t = win32_mem_read32(0x2f44f08u) & 0xffffu;   // instance 0, the server
    if (!t) return;
    const uint32_t base = win32_mem_read32(0x2f3b400u);
    if (!base) return;
    ++g_ti_n;
    const uint32_t self = (uint32_t)win32_mem_read8(base + t * 8u + 2)
                        | ((uint32_t)win32_mem_read8(base + t * 8u + 3) << 8);
    if (self) return;
    ++g_ti_zero;
    int k = 0; for (; k < g_ti_seen; k++) if (g_ti_idx[k] == t) break;
    if (k == g_ti_seen) { if (g_ti_seen < 8) g_ti_idx[g_ti_seen++] = t; else ++g_ti_lost; }
}
