[[gnu::used]] void* __remill_write_memory_f64(void* m, uint32_t a, double v) {
    uint64_t raw; memcpy(&raw, &v, 8);
    if (!w64_try_fast(a, raw)) mem_write64_ext(a, raw);
    return m;
}
// C38 (2026-09-27) — ENTREES LENTES DES LARGEURS 8, 16 ET 64, POUR LE CODE LEVE REPLIE.
// tools/boot.py `_inline_guest_wide` replie la voie rapide de ces entrees dans l'IR : les
// memes predicats (bo2_w32_cold | granule | bo2_w8_cold ou bo2_w64_cold, puis le test de
// page) et les memes compteurs (g_guest_writes += largeur en mots, comme ici). Tout le
// reste — mot froid non resolu (~0 : c'est ici que memfast_resolve arme), sondes 8/16,
// BO2_MEMFAST=0, granule marque, chevauchement de page — tombe sur l'entree complete
// ci-dessus, verbatim. Profil P679 : __remill_write_memory_64 = 2,5 % de tout le CPU,
// appele a 93 % par le depouillement.
[[gnu::used]] void* __remill_write_memory_8_slow(void* m, uint32_t a, uint8_t v) {
    return __remill_write_memory_8(m, a, v);
}
[[gnu::used]] void* __remill_write_memory_16_slow(void* m, uint32_t a, uint16_t v) {
    return __remill_write_memory_16(m, a, v);
}
[[gnu::used]] void* __remill_write_memory_64_slow(void* m, uint32_t a, uint64_t v) {
    return __remill_write_memory_64(m, a, v);
}
[[gnu::used]] void* __remill_write_memory_f64_slow(void* m, uint32_t a, double v) {
    return __remill_write_memory_f64(m, a, v);
}
[[gnu::used]] void* __remill_write_memory_f32_slow(void* m, uint32_t a, float v) {
    uint32_t raw; memcpy(&raw, &v, 4);
    if (!w32_try_fast(a, raw)) win32_mem_write32(a, raw);
    return m;
}
// exporte pour lifted.o et tout objet bati SANS BO2_INLINE_WRITES ; les
// objets batis avec le drapeau replient la voie rapide et n'appellent _slow
// que sur granule marque, mot froid, ou chevauchement de page.
[[gnu::used]] void* __remill_write_memory_f32(void* m, uint32_t a, float v) {
    return __remill_write_memory_f32_slow(m, a, v);
}
// x87 80-bit extended-precision (float80_t) memory access. Surfaces only in the
// deeper (~10k) lift where engine code does `fld/fstp tbyte`. Remill passes the
// 80-bit value BY REFERENCE as a 10-byte buffer (ptr dereferenceable(10)), not by
// value — so read/write are a straight 10-byte copy to/from guest memory. No host
// long double (ARM64's is 64-bit) and no lossy f80<->f64 conversion, which keeps
// the guest's 10-byte tbyte layout byte-exact.
[[gnu::used]] void* __remill_read_memory_f80(void* m, uint32_t a, void* out) {
    uint8_t* dst = (uint8_t*)out;
    for (int i = 0; i < 10; i++) dst[i] = win32_mem_read8(a + i);
    return m;
}
[[gnu::used]] void* __remill_write_memory_f80(void* m, uint32_t a, const void* in) {
    const uint8_t* src = (const uint8_t*)in;
    for (int i = 0; i < 10; i++) win32_mem_write8(a + i, src[i]);
    return m;
}

// --- control flow intrinsics ---
// Forward decl (defined in kernel32_impl.cpp; called via pointer+extern C).
extern "C" bool win32_dispatch_dyn(uint32_t sentinel, State* state_ptr);

// Print a wide (UTF-16LE) guest string if `p` looks like text. Used to surface
// the CRT's fatal-error message text when its MessageBox call is intercepted.
static void crt_dump_wstr(const char* tag, uint32_t p) {
    if (p < 0x1000u || p == 0xffffffffu) return;
    char buf[192]; int n = 0;
    for (int i = 0; i < 180 && n < 190; i++) {
        uint8_t lo = win32_mem_read8(p + i*2), hi = win32_mem_read8(p + i*2 + 1);
        if (lo == 0 && hi == 0) break;
        buf[n++] = (hi == 0 && lo >= 32 && lo < 127) ? (char)lo : '?';
    }
    buf[n] = 0;
    if (n > 0) fprintf(stderr, "[MSGTEXT %s @0x%08x] \"%s\"\n", tag, p, buf);
}

// Steam interface vtable-method dispatch (defined in remaining_dlls_impl.cpp).
// Returns true if `addr` was a Steam sentinel it handled.
extern "C" bool steam_vtbl_dispatch(State& state, uint32_t addr);
// D3D11/DXGI fake-COM vtable dispatch (defined in remaining_dlls_impl.cpp).
extern "C" bool d3d_vtbl_dispatch(State& state, uint32_t addr);
extern "C" bool dsound_vtbl_dispatch(State& state, uint32_t addr);
extern "C" bool xaudio_vtbl_dispatch(State& state, uint32_t addr);

// --- dispatch breadcrumbs + ESP sanity trap ---------------------------------
// Direct lifted->lifted calls are invisible to the shim, but every indirect
// call/jump/missing-block dispatch passes through here. Record the last 128
// dispatch events; if ESP is ever inside the PE image (a corrupted stack),
// dump the trail — the corruption happened between the last sane crumb and
// the trap point.
// tid AND edx: the crumb ring is GLOBAL, so a trail that looks like one
// thread's loop can be two threads interleaved — which is exactly the
// ambiguity left by the wild `jmp edx` -> 0x50b21b48 that ends the Sound
// Decode thread. edx is there because every computed dispatch in the audio
// DSP is `jmp edx`, so recording it shows the value one crumb BEFORE it is
// used, i.e. whether the register was already wrong on the way in.
struct DispatchCrumb { char kind; uint8_t tid; uint32_t target, esp, tos, edx; };
extern uint32_t g_last_ret_pc;   // defined with __remill_function_return below
// ⚠️ RING WIDENED 128 -> 2048 (2026-08-13). At 128 the ring is already
// saturated with GSC VM opcode dispatches by the time the EARLIEST bad-instance
// latch fires, so the origin of inst=1043 sits off the left edge of every dump
// taken this session. 16384 entries is ~256 KB of static storage and the same
// two stores per dispatch; the cost is memory, not time, and the window is what
// the investigation is short of.
static DispatchCrumb g_crumbs[2048];
static unsigned g_crumb_n = 0;

// 🎯 A DEEP, TID-FILTERED CRUMB DUMP.
//
// win32_dump_crumbs(n) walks every thread's entries interleaved, so 24 of them
// on a busy run is a few milliseconds of one thread. The origin of inst=1043 is
// off the left edge of every 24-entry dump taken so far, and the ring is now
// 16384 deep — so dump a long slice of ONE thread and mark the first crumb whose
// [esp] carries the bad value, which is what "when did 0x413 first appear" means
// in crumb terms.
extern "C" void bo2_dump_crumbs_tid(int want_tid, unsigned n, uint32_t needle) {
    unsigned have = g_crumb_n < 2048u ? g_crumb_n : 2048u;
    unsigned start = (have > n) ? (g_crumb_n - n) : (g_crumb_n - have);
    fprintf(stderr, "  [deep-crumbs] tid=%d, last %u dispatches (ring %u deep, %u recorded)\n",
            want_tid, n, 2048u, g_crumb_n);
    int shown = 0, first_needle = -1;
    for (unsigned i = start; i < g_crumb_n; i++) {
        auto& c = g_crumbs[i & 2047];
        if (!c.kind || (want_tid >= 0 && c.tid != (uint8_t)want_tid)) continue;
        const bool hit = (needle && (c.tos == needle || c.edx == needle));
        if (hit && first_needle < 0) first_needle = shown;
        fprintf(stderr, "   %5d tid%-2u %c target=%#010x esp=0x%08x [esp]=0x%08x edx=0x%08x%s\n",
                shown, c.tid, c.kind, c.target, c.esp, c.tos, c.edx,
                hit ? "   <<< carries the value" : "");
        shown++;
    }
    fprintf(stderr, "  [deep-crumbs] %d entries for tid %d; first carrying 0x%x at index %d\n",
            shown, want_tid, needle, first_needle);
}


extern bool g_iat_watch_armed;
// EBP poison-value tracer: tid4's renderer bring-up corrupts EBP to exactly
// 0xffffffe6 (-0x1a) between the render-queue wait loop and FUN_006bce50's
// ShowWindow (then `mov esp, ebp` wrecks ESP). Log every call/jump/return
// boundary where EBP transitions in or out of that value, plus the stack
// bytes around ESP — the first 'R' carrying the poison identifies the
// epilogue whose `pop ebp` installed it.
extern "C" int win32_current_tid();
static void ebp_poison_probe_on(State& s, char kind, uint32_t target);
// C31 (P673) — LE TEST EST DANS L'APPELANT. `static const int ebp_watch = [...]()` emettait a chaque
// appel une lecture-acquisition de la garde du statique, et l'appel lui-meme restait : 0,95 % du
// serveur, 0,69 % de Main (sample p672 181347), pour une sonde eteinte. Un entier global (-1 = pas
// encore lu) et une branche predite, comme g_hwa_lu.mode ; meme environnement, meme decision.
static int g_ebp_watch = -1;
static int ebp_watch_init() {
    const char* e = bo2_getenv("BO2_EBP_WATCH");
    g_ebp_watch = (e && atoi(e)) ? 1 : 0;
    return g_ebp_watch;
}
static inline void ebp_poison_probe(State& s, char kind, uint32_t target) {
    const int w = g_ebp_watch;
    if (__builtin_expect(w == 0, 1)) return;
    if (w < 0 && !ebp_watch_init()) return;
    ebp_poison_probe_on(s, kind, target);
}
[[gnu::noinline]] static void ebp_poison_probe_on(State& s, char kind, uint32_t target) {
    // 🎯 P658/C12 — TOUTE LA SONDE DERRIÈRE BO2_EBP_WATCH, PAS SEULEMENT SA MOITIÉ SCRIPT.
    // Appelée à chaque répartition indirecte ET à chaque `ret` invité, elle payait avant
    // tout test un win32_current_tid (TLS, _tlv_get_addr) et une écriture dans `last`,
    // 32 cases sur UNE ligne écrite par tous les fils : profil 174001 (srv C10), 3,2 %
    // de l'ordonnanceur, 4,2 % du serveur, 8,5-10,7 % des fils de tâches. Son détecteur
    // 0xffffffe6, armé par défaut, tirait 4-14 fois par run, toujours en paires
    // entrée/sortie au `ret` suivant sur un fil sain (-26 en entier ordinaire) : la
    // conclusion écrite plus bas (« ebp carries no signal in this image ») vaut pour lui
    // aussi. BO2_EBP_WATCH=1 rend la sonde entière, les deux détecteurs.
    // (le test BO2_EBP_WATCH est fait par ebp_poison_probe, ci-dessus)
    static uint32_t last[32];
    int tid = win32_current_tid();
    if (tid < 0 || tid > 31) return;
    uint32_t ebp = s.gpr.rbp.dword, old = last[tid];
    last[tid] = ebp;
    // 🎯 GENERALISED: ebp LEAVING EVERY THREAD'S STACK, not one historical value.
    //
    // This probe was hard-wired to 0xffffffe6, the poison from the renderer
    // bring-up, and has therefore been silent through every campaign freeze.
    // Measured 2026-08-15: tid 10 dies with **ebp=0x204db489** — an address in
    // the GSC SCRIPT region, on no stack at all — and `mov esp, ebp` / `leave`
    // in any epilogue turns exactly that into the esp=0x00000008 that follows.
    // Every other net in this runtime reports downstream of that assignment
    // ([RET-WILD-ESP] sees the `ret` after esp is already dead, [CHKSTK] sees a
    // frame request from esp=0x30); this one can see the assignment itself.
    //
    // Cheap first, as always: a value inside the guest's low stack region or any
    // coroutine stack is normal and costs two compares. Only a value outside
    // both pays for the bounds lookup. 0 is excluded — a null ebp is ordinary at
    // a frame base and would drown the report.
    {
        // ⚠️ FIRST VERSION WAS USELESS, AND THE RUN SAID SO IN NINETY SECONDS.
        // "ebp is not on a stack" fired 33 times during boot alone, all benign:
        // `ebp 0x0010fe78 -> 0x0270fc90` and `-> 0x0000002c`. This image is
        // built with frame-pointer omission, so **ebp is an ordinary
        // general-purpose register** holding heap pointers and small integers
        // all the time. A detector for "ebp is not a frame pointer" is a
        // detector for normal code.
        //
        // Narrowed to the one region the fatal value came from: tid 10 died with
        // ebp=0x204db489, and 0x20000000..0x21000000 is where GSC SCRIPTS are
        // loaded (the script at 0x204de8a0 in every [gsc-ring] dump). A script
        // address arriving in ebp is not ordinary register traffic, and it is
        // one `mov esp, ebp` from the esp=0x00000008 that follows.
        //
        // It reports its own narrowness: this cannot catch a fatal ebp from any
        // other region, and that is a deliberate trade against 33 benign hits
        // per boot drowning the one that matters.
        // ❌ AND THE NARROWED VERSION IS ALSO A DETECTOR FOR NORMAL CODE: 15 hits
        // during boot. The reason is in this very file's own comment on the GSC
        // tracer — "during the VM loop esi is the operand-stack pointer and
        // **[ebp+0x44] is the current thread's frame base**". The interpreter
        // KEEPS A SCRIPT-STRUCTURE POINTER IN EBP by design, so a script-region
        // ebp is exactly what a healthy VM looks like.
        //
        // Conclusion, recorded so nobody re-derives it: **ebp carries no signal
        // in this image.** It is a general-purpose register under frame-pointer
        // omission AND a deliberate VM pointer, so neither "off the stack" nor
        // "in the script region" separates the fatal assignment from ordinary
        // traffic. The fatal ebp=0x204db489 was very likely normal VM traffic
        // too, and the real question — where ESP is assigned — has to be asked
        // of esp directly.
        //
        // Kept, behind BO2_EBP_WATCH=1 and off by default, because it is the
        // right tool the day a specific ebp value is already suspected. Left on,
        // it would drown the nets that do carry signal.
        const uint32_t e = ebp;
        const bool script_region = (e >= 0x20000000u && e < 0x21000000u);
        if (g_ebp_watch > 0 && script_region && e != old) {
            static uint32_t nb[64] = {0};
            const int kk = (tid >= 0 && tid < 64) ? tid : 63;
            if (nb[kk]++ < 3u) {
                uint32_t lo = 0, hi = 0;
                win32_thread_stack_range(tid, &lo, &hi);
                fprintf(stderr, "\n🎯 [EBP-SCRIPT-ADDR] tid %d: ebp 0x%08x -> 0x%08x (GSC script region) at a "
                        "%c-dispatch to 0x%08x. Its stack is [0x%08x,0x%08x). esp=0x%08x\n"
                        "   `mov esp, ebp` or `leave` in any epilogue from here destroys "
                        "the stack — this is the ASSIGNMENT, not its consequence.\n",
                        tid, old, e, kind, target, lo, hi, s.gpr.rsp.dword);
            }
        }
    }
    if (old == ebp || (ebp != 0xffffffe6u && old != 0xffffffe6u)) return;
    static int n = 0;
    if (n >= 48) return;
    n++;
    uint32_t esp = s.gpr.rsp.dword;
    fprintf(stderr, "[EBP-POISON] %c target=0x%08x esp=0x%08x ebp 0x%08x->0x%08x "
            "stk[-16..+8]:[%08x %08x %08x %08x | %08x %08x %08x] tid=%d\n",
            kind, target, esp, old, ebp,
            win32_mem_read32(esp-16), win32_mem_read32(esp-12),
            win32_mem_read32(esp-8),  win32_mem_read32(esp-4),
            win32_mem_read32(esp),    win32_mem_read32(esp+4),
            win32_mem_read32(esp+8), tid);
}

// AUDIO PREEMPTION. The scheduler is cooperative, so a guest thread that computes
// for two seconds without touching an import blocks every other thread for two
// seconds — measured: the Sound Mix thread sat RUNNABLE (status T_RUN) and simply
// unpicked for ~4 s at a stretch, which is silence no matter how well the audio
// path itself behaves. Every indirect call/jump/missing-block passes through
// here, and a dispatch boundary is exactly as safe a yield point as an import
// call: the guest thread's whole state is its State plus its own stack.
//
// Deliberately NARROW. It fires only while the audio thread is actually short of
// samples (g_rt_hungry, set by the audio shim), only on threads that are not it,
// and at most once every 256 dispatches — so a build with no sound never reaches
// it (g_rt_tid stays -1) and a healthy frame pays one predictable branch.
extern "C" int g_rt_tid;
extern "C" int g_rt_hungry;
extern "C" void win32_coop_yield();
// 🎯 P648/C2 — CE CEDE N'A DE SENS QUE SUR LE TOURNIQUET. Il existe pour rendre
// le fil ordonnanceur au mixeur quand le peripherique manque d'echantillons. Si
// le mixeur est heberge (son propre fil hote), ou si CE fil l'est, ceder ne lui
// donne rien : sur un fil heberge, `win32_coop_yield` devient `host_backoff`,
// et des cedes espaces de moins d'1 ms ne remettent jamais sa graduation a zero
// -> un `nanosleep` de 200 us toutes les 256 repartitions. Mesure P647 (033442,
// crawl.sample) : le serveur heberge a 22 % de son fil dans host_backoff sous
// crumb_and_check, monde 0,02x pendant la phase de reptation.
extern "C" int bo2_tid_hosted(int tid);
extern "C" int bo2_self_hosted(void);
static void audio_preempt() {
    if (!g_rt_hungry || g_rt_tid < 0) return;
    static thread_local uint32_t n = 0;
    if ((++n & 255u) != 0) return;
    if (win32_current_tid() == g_rt_tid) return;
    if (bo2_tid_hosted(g_rt_tid) || bo2_self_hosted()) {
        static uint64_t ns = 0;          // compte approximatif (non atomique) : un temoin, pas une mesure
        const uint64_t k = ++ns;
        if ((k & (k - 1)) == 0)
            fprintf(stderr, "[AUDIO-PREEMPT #%llu] cede ignore : mixeur tid %d heberge=%d, "
                            "fil courant heberge=%d\n", (unsigned long long)k, g_rt_tid,
                    bo2_tid_hosted(g_rt_tid), bo2_self_hosted());
        return;
    }
    win32_coop_yield();
}

// The guest stack range spawn_thread gave a coroutine (kernel32_impl.cpp).
extern "C" void win32_thread_stack_range(int tid, uint32_t* lo, uint32_t* hi);
// ── 🎯 HOST-SIDE TEARDOWN REPAIR — because NO GUEST HOOK IS ON THE PATH ──────
//
// BO2_TEARDOWN_FORCE=<visits> was written as a hook inside the Scr_KillThread
// reporting path and fired ZERO times on a frozen angola. The reason is the
// project's oldest blind spot: during the spin, Scr_KillThread is reached by a
// DIRECT call from lifted code, so the dispatcher never sees it and no probe or
// repair placed there can ever run. The stack census learned the same lesson an
// hour earlier — it was cadenced by the frame pump and died with every freeze.
//
// So repair from a HOST thread, which nothing in the guest can stall. Poll the
// shutdown registry head; if it has not moved across several samples, the
// teardown is provably stuck and the head's first child is unlinked.
//
// ⚠️ It unlinks ONLY after the head has been seen unchanged repeatedly. A
// previous repair in this file wrote structure links on an inferred precondition
// and turned a freeze into a corruption. Proof of no progress first, then write.
//
// Why unlinking is defensible here: the entry cannot leave on its own because
// sub_87e160's unlink is refcount-gated (0x664550 reads word[table+var*8+2] and
// 0x87e185 skips on nonzero) and the object holds 19 references. At
// Scr_ShutdownSystem time the whole script system is being destroyed, so a
// surviving reference is meaningless by construction.
// ── 🎯 FIND THE SELF-LINKED VARIABLES, from the host, while the guest spins ──
//
// `sample` puts the stalled guest in sub_87ce10 doing nothing but
// __remill_read_memory_16 — walking a 16-bit chain that never ends. The variable
// audit has counted 5,191 "self links" on angola against 195 on a healthy load
// for weeks, and the teardown repair had to special-case a sibling whose `next`
// was itself. Those are the same defect seen three ways.
//
// This scans the variable table for records whose next-sibling IS the record and
// names them, so one can be handed to BO2_MT_NODEWATCH to catch the write that
// created it. Host-clocked, because the guest is spinning and every guest-side
// probe is blind by then.
//
// BO2_SELFLINK_SCAN=<max records to walk> (0 = off).
// ── 🎯 WATCH THE TWO BUILTIN-TABLE POINTERS OVER TIME ────────────────────────
//
// A/0x414dd0 walks the table at [0xbd0ae8], D/0x5a8160 the one at [0xaff338], and
// both read 0x00a98730 — the same table. Community documentation confirms the
// selector's meaning (scriptInstance 0 = GSC, 1 = CSC), and the measurement agrees
// (.gsc always ebx=0, .csc always ebx=1), so the two instances are real and their
// tables ought to differ.
//
// The open question is whether one pointer is set later, or never. Sampling from
// the host thread answers it without touching the guest: if they are equal at
// startup and stay equal, the client table is never installed.
// ── 🎯 BO2_SLCHAIN_SCAN — LA CHAINE DE CHAINES DE SCRIPT QUI NE FINIT JAMAIS ──
//
// w70 et w71 gelent tous les deux a svsTime=29250 — la MEME milliseconde de jeu,
// donc c'est deterministe. tid0 (Main, qui porte le tick serveur) est a 100 %
// dans sub_87c8e0, `last-ret=0x0087c92d`, soit juste apres le `call 0x508690` de
// cette fonction. La pile invitee nomme toute la chaine d'appel :
//   [esp+0x10] -> 0x005cacf8   (sub_5cacc0, la reconstruction de longueur)
//   [esp+0x18] -> 0x00636a6f   (le decrement de compteur de references)
//
// Ce que fait ce trio, decode octet par octet depuis .text :
//
//   [0xbf0f00]   -> table de hachage des chaines de script. Emplacements de 8 o :
//                   [+0] dword = lien (16 bits bas) | drapeaux (0x10000/0x20000)
//                   [+4] dword = index dans la reserve
//   [0x2d43da4]  -> reserve de chaines. Entrees de 24 o :
//                   [+0] word = compteur de references
//                   [+3] byte = LES 8 BITS BAS de la longueur, rien de plus
//                   [+4] ..   = les caracteres, NUL inclus dans la longueur
//
//   sub_87c7e0(len, str) = le hachage :
//       if (len >= 0x100) return ((len >> 2) % 0xbfff) + 1;   // LA LONGUEUR SEULE
//       h = 0; for (c : str) h = h*31 + (int8_t)c;            // octet SIGNE
//       return (h % 0xbfff) + 1;                              // seaux 1..49151
//
//   sub_5cacc0(entry) = la reconstruction de longueur :
//       c = (byte[entry+3] - 1) & 0xff;
//       while (str[c] != 0) c += 0x100;
//       len = c + 1;
//
//   sub_87c8e0(entry, cle, len) = le retrait : hache, puis parcourt le seau pour
//       trouver le PREDECESSEUR de `cle` afin de le delier. La chaine est
//       CIRCULAIRE (elle boucle sur sa tete) et la boucle 0x87c970 n'a **aucune
//       sortie autre que trouver la cle**. Si la cle n'est pas dans ce seau, le
//       thread tourne pour toujours — et l'ordonnanceur invite ne preempte
//       jamais, donc tout le jeu gele avec lui.
//
// ❌ CE QUE J'AI CRU ET QUI EST FAUX. Dans w70, `ebp` valait 0x2304, et comme
// ebp = len + 4 dans cette fonction j'en ai conclu une longueur de 8960 = 35x256,
// donc un scan parti trop loin faute de terminateur. **w71 refute** : meme gel,
// meme pile, mais ebp = 0x0000000c, soit une longueur de 8 — une chaine courte
// parfaitement ordinaire. La longueur n'est donc pas le defaut. Ce qui reste :
// la cle n'est pas dans le seau que son hachage designe.
//
// CE QUE CETTE SONDE FAIT. Depuis le fil hote (qui survit a un invite gele), elle
// refait exactement les deux calculs du jeu pour CHAQUE enregistrement vivant de
// la table, et signale :
//   (a) ceux dont le hachage recalcule ne retombe pas sur le seau ou ils sont
//       ranges — un tel enregistrement est une bombe a retard : le jour ou son
//       compteur tombe a zero, le jeu gele ;
//   (b) ceux dont la cle de reserve apparait dans DEUX seaux a la fois ;
//   (c) les seaux dont la chaine ne reboucle pas sur sa tete.
// Lecture seule. Aucune ecriture, aucune garde : on nomme le defaut.
static uint32_t sl_hash_of(uint32_t len, uint32_t str_va) {
    if (len >= 0x100u) return ((len >> 2) % 0xbfffu) + 1u;
    uint32_t h = 0;
    for (uint32_t i = 0; i < len; i++)
        h = h * 31u + (uint32_t)(int32_t)(int8_t)win32_mem_read8(str_va + i);
    return (h % 0xbfffu) + 1u;
}
// 🎯 L'INVERSION : QUELLE LONGUEUR A SERVI A L'INSERTION ?
//
// POURQUOI ELLE EXISTE. Au gel du 2026-09-18 10:00 on savait tout sauf ca. Le
// desassemblage donne le contrat des deux bouts :
//   - `sub_64d340` (internement, 0x64d351) hache la longueur PLEINE et range
//     `longueur & 0xff` en [enr+3] (prouve : `movzx ecx,bl` compare a
//     `movzx eax,byte[edx+3]`, 0x64d371 / 0x64d39e) ;
//   - `sub_5cacc0` (liberation generique, 82 sites) la DEVINE par scan de NUL.
// Quand les deux different, `sub_87c8e0` parcourt un seau ou la cle n'est pas,
// et sa boucle 0x87c970 n'a aucune autre sortie. Trois nombres sont en jeu —
// longueur d'insertion, [enr+3], longueur devinee — et UN SEUL peut etre faux.
// On mesurait les deux derniers ; le premier manquait.
//
// COMMENT ON LE RECUPERE SANS REGISTRE. Le seau OU l'enregistrement est chaine
// EST une signature de la longueur d'insertion : c'est `sl_hash_of(L, octets)`.
// On essaie donc tous les L et on garde ceux qui retombent sur ce seau-la.
// Cout : le polynome est INCREMENTAL (h = h*31 + b), donc 255 lectures invitees
// pour toute la plage < 256, et de l'arithmetique pure au-dela. Lecture seule.
//
// CE QUE CHAQUE REPONSE VEUT DIRE :
//   - un L < 256 retombe, et `octets[L-1] != 0`  -> l'insertion avait raison, le
//     scan de NUL a deborde : l'enregistrement est un BLOB sans terminateur ;
//   - un L < 256 retombe, et `(L & 0xff) != [enr+3]` -> l'octet de longueur a
//     ete ECRASE depuis l'insertion (le meme dword porte le refcount) ;
//   - AUCUN L ne retombe -> ce ne sont ni la longueur ni le scan, mais les
//     OCTETS qui ont change, ou le chainage. Temoin negatif explicite, imprime.
static void sl_invert_len(uint32_t entry_va, uint32_t seau, char* out, size_t n) {
    if (!out || n == 0) return;
    out[0] = '\0';
    const uint32_t str = entry_va + 4u;
    const uint32_t b3  = win32_mem_read8(entry_va + 3u);
    size_t w = 0;
    int courts = 0, longs = 0;
    uint32_t h = 0;
    w += (size_t)snprintf(out + w, n - w, "< 256 : ");
    for (uint32_t L = 1u; L < 0x100u; L++) {
        const uint8_t dernier = win32_mem_read8(str + L - 1u);
        h = h * 31u + (uint32_t)(int32_t)(int8_t)dernier;
        if (((h % 0xbfffu) + 1u) != seau) continue;
        if (courts >= 4 || w + 80u >= n) break;
        w += (size_t)snprintf(out + w, n - w, "%s%u[oct%u=0x%02x%s, &0xff=0x%02x %s]",
                              courts ? ", " : "", L, L - 1u, dernier,
                              dernier ? "" : " NUL",
                              (unsigned)(L & 0xffu),
                              (L & 0xffu) == b3 ? "== [+3]" : "!= [+3] ⚠️");
        ++courts;
    }
    if (!courts && w + 24u < n) w += (size_t)snprintf(out + w, n - w, "AUCUNE");
    if (w + 24u < n) w += (size_t)snprintf(out + w, n - w, " | >= 256 : ");
    for (uint32_t L = 0x100u; L <= 0x2000u; L++) {
        if ((((L >> 2) % 0xbfffu) + 1u) != seau) continue;
        if ((L & 0xffu) != b3) continue;          // [+3] doit valoir L & 0xff
        if (longs >= 3 || w + 48u >= n) break;
        w += (size_t)snprintf(out + w, n - w, "%s%u", longs ? ", " : "", L);
        ++longs;
    }
    if (!longs && w + 48u < n)
        snprintf(out + w, n - w, "AUCUNE compatible avec [+3]=0x%02x", b3);
    if (!courts && !longs)
        snprintf(out, n, "🎯 AUCUNE longueur de 1 a 8192 ne retombe sur le seau %u — "
                         "ce ne sont donc NI la longueur NI le scan, mais les OCTETS "
                         "de l'enregistrement, ou son chainage (temoin negatif)", seau);
}
// Dans quel seau la cle est-elle REELLEMENT rangee ? 0 = introuvable. Sert au
// rapport de gel, qui connait la cle mais pas son seau.
// La cle est-elle dans CE seau-la ? Une seule marche de chaine, au lieu des
// 49 151 de `sl_bucket_of_key`. Meme lecture du chainage : `word[base+cur*8]`
// porte l'index suivant, `[base+cur*8+4]` la cle, et la chaine reboucle sur sa
// tete. Lecture seule, bornee.
static bool sl_key_in_bucket(uint32_t base, uint32_t b, uint32_t key) {
    if (!base || b == 0u || b > 0xbfffu) return false;
    if ((win32_mem_read32(base + b * 8u) & 0x30000u) != 0x20000u) return false;
    uint32_t cur = b, pas = 0;
    do {
        if (win32_mem_read32(base + cur * 8u + 4u) == key) return true;
        cur = win32_mem_read32(base + cur * 8u) & 0xffffu;
    } while (cur != b && ++pas < 0x20000u);
    return false;
}
static uint32_t sl_bucket_of_key(uint32_t key) {
    const uint32_t base = win32_mem_read32(0x00bf0f00u);
    if (!base) return 0;
    for (uint32_t b = 1u; b <= 0xbfffu; b++) {
        const uint32_t tete = win32_mem_read32(base + b * 8u);
        if ((tete & 0x30000u) != 0x20000u) continue;
        uint32_t cur = b, pas = 0;
        do {
            if (win32_mem_read32(base + cur * 8u + 4u) == key) return b;
            cur = win32_mem_read32(base + cur * 8u) & 0xffffu;
        } while (cur != b && ++pas < 0x20000u);
    }
    return 0;
}
// Renvoie 0 si aucun terminateur dans une fenetre raisonnable — c'est exactement
// le cas ou le jeu, lui, partirait chercher indefiniment.
static uint32_t sl_len_of(uint32_t entry_va, uint32_t* tours) {
    uint32_t c = (uint32_t)((win32_mem_read8(entry_va + 3u) - 1u) & 0xffu);
    *tours = 0;
    while (win32_mem_read8(entry_va + 4u + c) != 0) {
        c += 0x100u;
        if (++*tours > 256u) return 0;
    }
    return c + 1u;
}

// ── 🎯 [VARCHAIN] — LE SEAU DE VARIABLES GSC QUI NE FINIT JAMAIS ─────────────
//
// `sub_479b90` est la recherche de variable GSC. Elle hache
// `(a*0x65 + c) & 0x7fff`, lit la tete du seau dans la table d'INDEX
// `[(inst<<9) + 0x2f3b500]` (mots de 16 bits), puis marche la chaine dans la
// table d'ENREGISTREMENTS `[(inst<<9) + 0x2f3b580]` (16 octets par entree,
// `+4` = index suivant, `+8` = cle) :
//
//     0x479c00: mov ebx, eax              ; precedent
//     0x479c02: movzx eax, cx             ; suivant
//     0x479c05: shl eax, 4                ; *16
//     0x479c08: add eax, edx
//     0x479c0a: cmp [eax+8], edi          ; cle ?
//     0x479c0d: je  0x479c22              ; trouvee -> remontee en tete
//     0x479c0f: movzx ecx, word [eax+4]   ; suivant
//     0x479c13: test cx, cx
//     0x479c16: jne 0x479c00              ; tant que suivant != 0
//
// ⚠️ DEUX SORTIES SEULEMENT : la cle trouvee, ou le suivant nul. Ni borne, ni
// detection de cycle — et pas un seul import dans la boucle, donc pas un seul
// point de cede. Un seau qui reboucle est une boucle infinie DANS DU CODE
// LEVE : tout le jeu gele avec tid0 a 100 % de CPU. C'est exactement ce
// qu'imprime le detecteur de gel (« tid0 spinning in lifted code and never
// yielding »), et c'est la meme forme que la marche de seau de `sub_87c8e0`
// deja documentee dans AGENTS.md.
//
// Ce balayage est en LECTURE SEULE et vit sur le fil de veille HOTE, donc il
// parle meme quand l'invite est fige — le seul moment qui compte. Il nomme :
//   (a) les seaux CYCLIQUES, par lievre et tortue (pas par une borne : une
//       borne dirait « trop long », pas « cyclique ») ;
//   (b) les enregistrements presents dans DEUX seaux — la bombe armee ;
//   (c) l'auto-lien `rec->next == rec`.
// Il porte son temoin NEGATIF : une ligne meme quand tout va bien. Une sonde
// muette est indiscernable d'une sonde qui n'a rien trouve — c'est la panne
// d'instrument la plus chere de ce depot, deja payee par `win32_slchain_scan`.
extern "C" void win32_varchain_scan(void) {
    static std::vector<uint32_t> owner;      // index d'enregistrement -> seau+1
    for (uint32_t inst = 0; inst < 2u; inst++) {
        const uint32_t heads = win32_mem_read32((inst << 9) + 0x02f3b500u);
        const uint32_t recs  = win32_mem_read32((inst << 9) + 0x02f3b580u);
        if (!heads || !recs) {
            static uint64_t n_mut[2] = {0, 0};
            if (++n_mut[inst] == 1 || (n_mut[inst] % 90) == 0)
                fprintf(stderr, "[VARCHAIN] inst=%u ⚠️ RIEN A BALAYER : index=0x%08x "
                                "enregistrements=0x%08x — appel muet #%llu. La sonde "
                                "EST armee ; c'est la base qui manque.\n",
                        inst, heads, recs, (unsigned long long)n_mut[inst]);
            continue;
        }
        owner.assign(0x10000u, 0u);
        uint64_t chains = 0, longest = 0, cycles = 0, dupes = 0, selfs = 0;
        uint32_t cyc_bucket = 0, cyc_head = 0, cyc_at = 0;
        // [VARCHAIN/MAL-CLASSE] — le predicat de P521. Un enregistrement
        // assis dans un seau acyclique peut rester INTROUVABLE depuis celui
        // que son propre hachage designe : c'est exactement ce que la boucle
        // sans sortie de sub_87ce10 cherche indefiniment.
        uint64_t malcl = 0;
        uint32_t mc_p[4] = {0,0,0,0}, mc_ou[4] = {0,0,0,0}, mc_dit[4] = {0,0,0,0};
        for (uint32_t b = 0; b < 0x8000u; b++) {
            const uint32_t idx = win32_mem_read32(heads + b * 2u) & 0xffffu;
            if (!idx) continue;
            ++chains;
            uint32_t slow = idx, fast = idx, meet = 0; bool cyc = false;
            for (;;) {
                fast = win32_mem_read32(recs + fast * 16u + 4u) & 0xffffu;
                if (!fast) break;
                fast = win32_mem_read32(recs + fast * 16u + 4u) & 0xffffu;
                if (!fast) break;
                slow = win32_mem_read32(recs + slow * 16u + 4u) & 0xffffu;
                if (slow == fast) { cyc = true; meet = slow; break; }
            }
            uint64_t len = 0;
            for (uint32_t p = idx; p; ) {
                ++len;
                const uint32_t nxt = win32_mem_read32(recs + p * 16u + 4u) & 0xffffu;
                if (nxt == p) { ++selfs; break; }
                if (owner[p] && owner[p] != b + 1u) ++dupes;
                owner[p] = b + 1u;
                // Le hachage de sub_87ce10, refait a l'identique depuis les champs
                // de l'enregistrement lui-meme (0x87ce7f..0x87cea0).
                const uint32_t er = recs + p * 16u;
                const uint32_t hh = (((win32_mem_read32(er + 8u) & 0xffffu) << 8)
                                   + (win32_mem_read32(er + 0xau) & 0xffffu) * 0x65u
                                   + (uint32_t)win32_mem_read8(er + 7u)) & 0x7fffu;
                if (hh != b) {
                    if (malcl < 4) { mc_p[malcl] = p; mc_ou[malcl] = b; mc_dit[malcl] = hh; }
                    ++malcl;
                }
                if (len > 0x10000u) break;       // chaine cyclique : on borne la MESURE
                p = nxt;
            }
            if (len > longest) longest = len;
            if (cyc && !cycles) { cyc_bucket = b; cyc_head = idx; cyc_at = meet; }
            if (cyc) ++cycles;
        }
        fprintf(stderr, "[VARCHAIN] inst=%u %llu chaine(s), la plus longue %llu, "
                        "%llu cyclique(s), %llu auto-lien(s), %llu doublon(s) de seau%s\n",
                inst, (unsigned long long)chains, (unsigned long long)longest,
                (unsigned long long)cycles, (unsigned long long)selfs,
                (unsigned long long)dupes,
                (cycles || selfs || dupes)
                    ? "   🎯 <<< LA MARCHE DE sub_479b90 NE PEUT PAS FINIR"
                    : "   — rien de cyclique, cette table n'est pas le gel");
        // Le bilan « mal classe » parle TOUJOURS, y compris a zero : sans temoin
        // negatif, une sonde muette et une sonde morte se lisent pareil.
        fprintf(stderr, "[VARCHAIN] inst=%u %llu enregistrement(s) MAL CLASSE(S)%s\n",
                inst, (unsigned long long)malcl,
                malcl ? "   🎯 <<< sub_87ce10 TOURNERA SANS FIN SUR EUX"
                      : "   — chaque enregistrement est dans le seau de son hachage");
        for (uint64_t q = 0; q < malcl && q < 4; q++)
            fprintf(stderr, "[VARCHAIN] inst=%u   mal classe #%llu : enregistrement %u "
                            "(0x%04x) assis dans le seau 0x%04x, son hachage dit 0x%04x "
                            "— cle=0x%08x octet[+7]=0x%02x mot[+8]=0x%04x mot[+0xa]=0x%04x\n",
                    inst, (unsigned long long)q + 1, mc_p[q], mc_p[q], mc_ou[q], mc_dit[q],
                    win32_mem_read32(recs + mc_p[q] * 16u + 8u),
                    (unsigned)win32_mem_read8(recs + mc_p[q] * 16u + 7u),
                    (unsigned)(win32_mem_read32(recs + mc_p[q] * 16u + 8u) & 0xffffu),
                    (unsigned)(win32_mem_read32(recs + mc_p[q] * 16u + 0xau) & 0xffffu));
        if (cycles)
            fprintf(stderr, "[VARCHAIN] inst=%u 🎯 premier cycle : seau 0x%04x, tete "
                            "enregistrement %u, rencontre a l'enregistrement %u "
                            "(cle 0x%08x)\n",
                    inst, cyc_bucket, cyc_head, cyc_at,
                    win32_mem_read32(recs + cyc_at * 16u + 8u));
    }
}

extern "C" void win32_slchain_scan(void) {
    static const bool on = bo2_getenv("BO2_SLCHAIN_SCAN") != nullptr;
    if (!on) return;
    const uint32_t base = win32_mem_read32(0x00bf0f00u);
    const uint32_t pool = win32_mem_read32(0x02d43da4u);
    // ── 🔴 MESURE DU 2026-09-18 : CETTE PORTE ETAIT MUETTE, ET ELLE RETENAIT ──
    //
    // `runs/menu_awake` : `BO2_SLCHAIN_SCAN=1` bien present dans l'environnement
    // du processus, le fil de veille hote a traverse cet appel **77 fois**
    // (compte de [SLFREE-VOL], imprime juste apres) — et le journal contient
    // **ZERO** ligne [SLCHAIN]. Donc on sortait ici, sans un mot.
    //
    // C'est la panne d'instrument la plus couteuse du depot : une sonde qui
    // ne dit rien est indiscernable d'une sonde qui a tout trouve normal. Et
    // celle-ci n'est pas une sonde parmi d'autres — `sl_len_of` reproduit
    // EXACTEMENT la devinette de longueur de `sub_5cacc0` ((byte[+3]-1)&0xff
    // puis +=0x100 tant que non nul), donc « MAL CLASSE » n'est pas un indice
    // voisin du gel : c'est le PREDICAT du gel. Chaque mal classe est une
    // bombe armee, qui explose le jour ou le moteur libere cette chaine-la.
    // Rester muet ici, c'est eteindre le seul predicteur qu'on ait.
    if (!base || !pool) {
        static uint64_t n_mut; static uint32_t der_b, der_p; static bool vu;
        ++n_mut;
        if (!vu || base != der_b || pool != der_p || (n_mut % 90) == 0) {
            fprintf(stderr, "[SLCHAIN] ⚠️ RIEN A BALAYER : [0x00bf0f00]=0x%08x (table) "
                            "[0x02d43da4]=0x%08x (reserve) — %s. Appel muet #%llu. "
                            "La sonde EST armee ; c'est la base qui manque.\n",
                    base, pool,
                    !base && !pool ? "les DEUX sont nulles"
                                   : (!base ? "la TABLE est nulle" : "la RESERVE est nulle"),
                    (unsigned long long)n_mut);
            der_b = base; der_p = pool; vu = true;
        }
        return;
    }
    // Quel seau detient chaque cle de reserve ? 0 = pas encore vue. Statique :
    // le fil hote est seul a l'utiliser et on veut zero allocation au gel.
    static std::vector<uint32_t> proprio;
    if (proprio.empty()) proprio.assign(1u << 20, 0u);
    else std::fill(proprio.begin(), proprio.end(), 0u);
    // 🎯 QUI DETIENT CHAQUE BLOC DE 24 OCTETS ? (P201)
    // Fait etabli hors ligne : sub_60d7e0 ecrit la MEME base 0x2d44280 dans
    // [0x2d43da4] (la reserve SL_*) et dans [0x2d43e00] (les « nodes » de
    // MT_AllocIndex). La reserve de chaines EST le tas du VM GSC, 0x10000 blocs
    // de 24 octets. Donc les flottants trouves dans les enregistrements mal
    // classes ne sont pas une ecriture sauvage de notre runtime : ce sont des
    // donnees de script parfaitement legitimes, posees sur un bloc que
    // l'allocateur a rendu DEUX FOIS.
    // Une chaine de longueur L occupe ceil((4+L)/24) blocs consecutifs a partir
    // de sa cle. Si deux enregistrements vivants reclament le meme bloc, la
    // double distribution est PROUVEE — et elle se calcule sans rien demander a
    // l'invite, a partir de ce que la balayeuse lit deja.
    // bloc[i] = cle+1 du proprietaire, 0 = libre.
    static std::vector<uint32_t> bloc;
    if (bloc.empty()) bloc.assign(0x10000u, 0u);
    else std::fill(bloc.begin(), bloc.end(), 0u);
    static std::vector<uint32_t> suspects;   // les cles des mal classes
    suspects.clear();

    uint32_t vivants = 0, mauvais = 0, sansfin = 0, doubles = 0, sains = 0;
    // Bande des cles mal classees. Mesure du 2026-09-18 : 22352 -> 23256, soit
    // 904 blocs CONTIGUS = 21 696 octets, tous remplis du meme bitmap. Une
    // etendue contigue nomme une allocation en VRAC ; des cles eparpillees
    // nommeraient des liberations individuelles. Les deux hypotheses ne se
    // separent que par cette paire de nombres, et elle ne coute rien.
    uint32_t cle_min = 0xffffffffu, cle_max = 0u;
    uint32_t chaines = 0, plus_longue = 0, non_bouclees = 0;
    uint32_t collisions = 0, dedans = 0;
    for (uint32_t b = 1u; b <= 0xbfffu; b++) {
        const uint32_t tete = win32_mem_read32(base + b * 8u);
        if ((tete & 0x30000u) != 0x20000u) continue;       // seau vide
        ++chaines;
        uint32_t cur = b, pas = 0;
        do {
            ++vivants;
            const uint32_t cle   = win32_mem_read32(base + cur * 8u + 4u);
            const uint32_t entry = pool + cle * 24u;
            uint32_t tours = 0;
            const uint32_t L  = sl_len_of(entry, &tours);
            const uint32_t hb = L ? sl_hash_of(L, entry + 4u) : 0u;
            char txt[49]; uint32_t k = 0;
            for (; k < 48u; k++) {
                const uint8_t ch = win32_mem_read8(entry + 4u + k);
                if (!ch) break;
                txt[k] = (ch >= 32 && ch < 127) ? (char)ch : '.';
            }
            txt[k] = 0;
            if (!L || hb != b) {
                if (!L) ++sansfin;
                if (suspects.size() < 4096u) suspects.push_back(cle);
                if (cle < cle_min) cle_min = cle;
                if (cle > cle_max) cle_max = cle;
                // 2026-09-18 : plafond releve de 12 a 64. La ligne de synthese
                // comptait jusqu'a 68 mal classes alors que l'impression en
                // montrait 12 : on ne voyait qu'un cinquieme de la bande, et la
                // bande est justement ce qu'il faut mesurer (elle est CONTIGUE).
                if (++mauvais <= 64) {
                    // 🎯 LES OCTETS BRUTS, pas seulement le texte jusqu'au premier
                    // NUL. « ........ » ne distingue pas une chaine binaire d'une
                    // entree corrompue ; l'hexa, si. Et l'adresse invitee dit dans
                    // quelle region de la reserve la corruption tombe.
                    char hex[3 * 24 + 1]; uint32_t h = 0;
                    for (uint32_t q = 0; q < 24u; q++)
                        h += (uint32_t)snprintf(hex + h, sizeof hex - h, "%02x ",
                                                win32_mem_read8(entry + q));
                    fprintf(stderr,
                        "[SLCHAIN] ⚠️ MAL CLASSE seau %u emplacement 0x%04x cle=%u "
                        "@0x%08x : longueur=%u (%u tours) -> seau recalcule %u  "
                        "octet[+3]=0x%02x  refs=%u  « %s »\n            hexa %s\n",
                        b, cur, cle, entry, L, tours, hb, win32_mem_read8(entry + 3u),
                        (unsigned)(win32_mem_read32(entry) & 0xffffu), txt, hex);
                    // ── 🎯 2026-09-18 : LES 256 PREMIERS OCTETS, PAS 24 ──────────
                    // Le desassemblage de `sub_87c7e0` (le hachage lui-meme)
                    // donne : `cmp eax,0x100 ; jae` -> au-dela de 255 octets le
                    // seau ne depend QUE de la longueur, `((len>>2)%0xbfff)+1`.
                    // En dessous, c'est la boucle `h*31 + (int8)c` sur le
                    // CONTENU. Les 16 mal classes de runs/mc1 exigeraient donc,
                    // en tant que chaines longues, des longueurs de 3 a 7
                    // MILLIONS d'octets — et deux d'entre eux (cle 22368, 22976)
                    // n'admettent AUCUNE longueur compatible avec leur
                    // `octet[+3]`. Ils n'ont donc pas ete inseres longs.
                    // Reste l'autre branche : inseres COURTS, haches par
                    // contenu, puis leur `octet[+3]` a change. Elle se tranche
                    // en rejouant `h*31` sur les 255 premiers octets — que ce
                    // vidage de 24 octets ne montrait pas. D'ou l'elargissement.
                    // Cout : <= 64 enregistrements par balayage, et le balayage
                    // n'est appele que depuis le detecteur de gel.
                    if (mauvais <= 8) {
                        char big[3 * 256 + 1]; uint32_t g = 0;
                        for (uint32_t q = 0; q < 256u && g + 3 < sizeof big; q++)
                            g += (uint32_t)snprintf(big + g, sizeof big - g, "%02x",
                                                    win32_mem_read8(entry + 4u + q));
                        fprintf(stderr, "            charge256 %s\n", big);
                    }
                    if (mauvais <= 8) {
                        char inv[320];
                        sl_invert_len(entry, b, inv, sizeof inv);
                        fprintf(stderr, "            longueurs qui RETOMBENT sur le seau %u : %s\n",
                                b, inv);
                    }
                    // 🎯 LE CROISEMENT QUI NOMME LE COUPABLE.
                    //
                    // La reserve de 24 octets est PARTAGEE : sub_60d7e0 ecrit la
                    // MEME base 0x2d44280 dans [0x2d43da4] (les chaines SL_*) et
                    // dans [0x2d43e00] (les noeuds de MT_AllocIndex). Un
                    // enregistrement mal classe est donc soupconne d'etre un bloc
                    // RENDU a l'allocateur puis redistribue, alors qu'une TETE de
                    // seau le nomme encore. Mesure du 2026-09-18 : 132 mal classes
                    // sur 132 tombent sur la branche « longueur longue » du
                    // hachage, dont le seau vaut (longueur>>2)+1, et AUCUN des
                    // ~13 000 enregistrements sains n'a une longueur >= 256 — donc
                    // cette branche n'est jamais empruntee legitimement.
                    //
                    // Le registre MT sait, pour chaque bloc, son etat et surtout
                    // le SITE INVITE qui l'a alloue. C'est exactement ce qui
                    // separe « la chaine a ete liberee sans delier son
                    // emplacement » de « l'allocateur a redistribue un bloc
                    // encore nomme ». Cout : deux lectures de tableau.
                    //
                    // ⚠️ TEMOIN NEGATIF OBLIGATOIRE : si le registre n'est pas
                    // pret (aucun BO2_MT_* arme), on le DIT. Sinon kMtFree valant
                    // 0, un registre vide imprimerait « LIBRE » partout et se
                    // lirait comme une preuve.
                    // ⚠️ Lecture SANS g_mtl_mu : on tourne sur le fil hote au
                    // moment ou l'invite est bloque, et un thread invite peut
                    // tenir ce mutex pour toujours. Un etat legerement rance est
                    // preferable a un observateur qui se bloque aussi.
                    if (cle < kMtBlocks) {
                        if (!g_mtl.ready)
                            fprintf(stderr, "            registre MT NON PRET — arme un "
                                            "BO2_MT_* (le silence n'est PAS « bloc libre »)\n");
                        else
                            fprintf(stderr, "            registre MT bloc %u : etat=%s "
                                            "proprio=0x%04x classe=%u taille=%u site=0x%08x\n",
                                    cle,
                                    g_mtl.state[cle] == kMtFree  ? "🎯 LIBRE"
                                  : g_mtl.state[cle] == kMtAlloc ? "alloue"
                                                                 : "nul",
                                    g_mtl.owner[cle], (unsigned)g_mtl.cls[cle],
                                    g_mtl.asz[cle], g_mtl.site[cle]);
                    }
                }
            }
            else {
                // La plage de blocs de cet enregistrement SAIN. Son L est valide
                // par le re-hachage, donc ceil((4+L)/24) est fiable ici — ce qui
                // n'est pas le cas pour un mal classe, dont le L est du bruit.
                const uint32_t n = (4u + L + 23u) / 24u;
                for (uint32_t i = 0; i < n && i < 4096u && cle + i < 0x10000u; i++) {
                    const uint32_t deja = bloc[cle + i];
                    if (deja && deja != cle + 1u) {
                        if (++collisions <= 8)
                            fprintf(stderr,
                                "[SLCHAIN] 🎯 BLOC DISTRIBUE DEUX FOIS : bloc %u "
                                "(@0x%08x) appartient a la cle %u ET a la cle %u "
                                "(longueur %u, %u blocs)  « %s »\n",
                                cle + i, pool + (cle + i) * 24u, deja - 1u, cle, L, n, txt);
                    } else bloc[cle + i] = cle + 1u;
                }
            }
            if (hb == b && L && sains < 3u) {
                // ✅ TEMOIN. Si ma lecture du format etait fausse, ces trois-la
                // seraient illisibles aussi. Qu'ils sortent en clair est la
                // preuve que les « mal classes » le sont vraiment.
                ++sains;
                fprintf(stderr, "[SLCHAIN] ✅ sain seau %u cle=%u longueur=%u « %s »\n",
                        b, cle, L, txt);
            }
            if (cle < proprio.size()) {
                if (proprio[cle] && proprio[cle] != b) {
                    if (++doubles <= 8)
                        fprintf(stderr,
                            "[SLCHAIN] ⚠️ CLE DOUBLE %u : deja vue au seau %u, "
                            "reparait au seau %u  « %s »\n",
                            cle, proprio[cle], b, txt);
                } else proprio[cle] = b;
            }
            if (pas > plus_longue) plus_longue = pas;
            cur = win32_mem_read32(base + cur * 8u) & 0xffffu;
        } while (cur != b && ++pas < 0x20000u);
        if (pas >= 0x20000u && ++non_bouclees <= 4)
            fprintf(stderr, "[SLCHAIN] ⚠️ seau %u : chaine non bouclee apres %u pas\n", b, pas);
    }
    // 🎯 SECONDE PASSE (P201). Il faut que TOUS les sains soient marques avant de
    // poser la question, sinon l'ordre de parcours des seaux decide de la reponse.
    for (uint32_t i = 0; i < suspects.size(); i++) {
        const uint32_t cle = suspects[i];
        if (cle >= 0x10000u) continue;
        const uint32_t prop = bloc[cle];
        if (prop && prop != cle + 1u) {
            if (++dedans <= 12)
                fprintf(stderr,
                    "[SLCHAIN] 🎯 MAL CLASSE cle=%u (@0x%08x) tombe DANS la plage "
                    "de la chaine saine cle=%u : son contenu a ete recouvert par "
                    "une autre allocation.\n",
                    cle, pool + cle * 24u, prop - 1u);
        }
    }
    static uint32_t dernier = 0xffffffffu;
    const uint32_t sig = mauvais * 1000003u + doubles * 101u + non_bouclees
                       + collisions * 7919u + dedans * 31u
    // La bande entre dans la signature : deux recensements de meme COMPTE mais
    // de bande differente sont deux faits differents, et l'anti-repetition les
    // fusionnait en silence.
                       + cle_min * 13u + cle_max * 17u;
    if (sig != dernier) {
        fprintf(stderr, "[SLCHAIN] table@0x%08x reserve@0x%08x — %u chaines, %u vivants, "
                        "%u mal classes (%u sans terminateur), %u cles doubles, "
                        "%u non bouclees, plus longue chaine %u | BLOCS : %u "
                        "collisions entre sains, %u mal classes dans la plage d'un sain"
                        " | BANDE des mal classes : %u -> %u (%u blocs, %u octets)\n",
                base, pool, chaines, vivants, mauvais, sansfin, doubles,
                non_bouclees, plus_longue, collisions, dedans,
                mauvais ? cle_min : 0u, cle_max,
                mauvais ? cle_max - cle_min + 1u : 0u,
                mauvais ? (cle_max - cle_min + 1u) * 24u : 0u);
        dernier = sig;
    }
}

extern "C" void win32_table_watch(void) {
    // 🎯 SAMPLE THE ZONE RECORD TABLE LATE. Dumping it from db_loadxfile's entry
    // read it before the walk had populated anything — every entry was a bare
    // free-list link. The host thread runs long after the level zone is in, which
    // is the only moment the question makes sense.
    {
        static const bool rec = bo2_getenv("BO2_ZONE_RECS") != nullptr;
        static bool once = false;
        if (rec && !once) {
            int live = 0;
            for (uint32_t r = 0; r < 400; r++) {
                const uint32_t e = 0x01178c50u + r * 16u;
                const uint32_t w4 = win32_mem_read32(e + 4);
                if (!w4) continue;
                if (++live <= 16)
                    fprintf(stderr, "[ZONE-REC %3u] type=%u ptr=0x%08x kind=%u flag=%u "
                                    "next=0x%04x\n", r,
                            win32_mem_read32(e) & 0xffu, w4, win32_mem_read8(e + 8),
                            win32_mem_read8(e + 9),
                            (unsigned)(win32_mem_read32(e + 0xa) & 0xffffu));
            }
            if (live) { once = true;
                fprintf(stderr, "[ZONE-REC] %d live records in the table\n", live); }
        }
    }
    static const bool on = bo2_getenv("BO2_TABLE_WATCH") != nullptr;
    if (!on) return;
    static uint32_t last_a = 0xffffffffu, last_d = 0xffffffffu;
    const uint32_t a = win32_mem_read32(0x00bd0ae8u);
    const uint32_t d = win32_mem_read32(0x00aff338u);
    if (a != last_a || d != last_d) {
        fprintf(stderr, "[TABLE-WATCH] [0xbd0ae8]=0x%08x  [0xaff338]=0x%08x  %s\n",
                a, d, a == d ? "⚠️  same table" : "distinct");
        last_a = a; last_d = d;
    }
}

extern "C" void win32_selflink_scan(void) {
    static const long cap = [] {
        const char* e = bo2_getenv("BO2_SELFLINK_SCAN");
        return e ? (atol(e) > 0 ? atol(e) : 24576L) : 0L;
    }();
    if (cap <= 0) return;
    for (uint32_t inst = 0; inst < 2; inst++) {
        const uint32_t t580 = win32_mem_read32(0x2f3b400u + (inst << 9));
        if (!t580) continue;
        // 🎯 EVERY LINK WORD IN THE RECORD, not just +0xc. Cutting the
        // self-linked SIBLING moved angola by ten frames and no further, so the
        // chain the guest actually walks in sub_87ce10 is a different one. A
        // record is 16 bytes and the link words live at +0x8, +0xa and +0xc;
        // scan all three rather than guessing which.
        static const uint32_t kLinkOff[3] = { 0x8u, 0xau, 0xcu };
        for (int L = 0; L < 3; L++) {
        const uint32_t off = kLinkOff[L];
        uint32_t nself = 0, first[8] = {0};
        for (long i = 1; i < cap; i++) {
            const uint32_t nxt = win32_mem_read32(t580 + (uint32_t)i * 16u + off) & 0xffffu;
            if (nxt == (uint32_t)i) {
                if (nself < 8) first[nself] = (uint32_t)i;
                ++nself;
                // 🎯 BO2_SELFLINK_FIX=1 — CUT IT. A record whose next-sibling is
                // itself makes any walker loop forever, and `sample` puts the
                // stalled guest in sub_87ce10 doing nothing but 16-bit link
                // reads. This port's own walkers already carry `if (nxt == idx)
                // break;` guards in three places; the GAME's walker has none,
                // because in a healthy heap the situation cannot arise. So it is
                // our corruption, and the honest repair is to not leave it there.
                //
                // Writing 0 ends the sibling list at this record, which is what
                // the list would have said had the link never been scribbled.
                static const bool fix = bo2_getenv("BO2_SELFLINK_FIX") != nullptr;
                if (fix && off == 0xcu) {          // only the sibling link is safe to cut
                    win32_mem_write8(t580 + (uint32_t)i * 16u + 0xcu, 0);
                    win32_mem_write8(t580 + (uint32_t)i * 16u + 0xdu, 0);
                    static uint64_t ncut = 0;
                    if (++ncut <= 12)
                        fprintf(stderr, "[SELFLINK] inst=%u record 0x%04x pointed at itself — "
                                        "cut to 0 (cut %llu)\n",
                                inst, (uint32_t)i, (unsigned long long)ncut);
                }
            }
        }
        if (nself) {
            char b[256]; size_t n = 0;
            for (uint32_t k = 0; k < nself && k < 8; k++)
                n += snprintf(b + n, sizeof b - n, " 0x%04x", first[k]);
            fprintf(stderr, "[SELFLINK] inst=%u link+0x%x: %u record(s) point at themselves;"
                            " first:%s\n", inst, off, nself, b);
        }
        }
    }
}

extern "C" void win32_teardown_repair(void) {
    // Le discriminant de [GSC-TEARDOWN], en une ligne, avec son temoin
    // negatif : « 0 tour » est une reponse, pas un silence.
    {
        extern uint64_t g_drain_iters;
        static uint64_t prev = 0;
        const uint64_t now = g_drain_iters, d = now - prev; prev = now;
        fprintf(stderr, "[DRAIN-TOURS] %llu tour(s) de la boucle de sub_5efd70 "
                        "depuis le dernier rapport (%llu au total) — %s\n",
                (unsigned long long)d, (unsigned long long)now,
                d ? "elle TOURNE : une tete immobile prouve alors qu'on RATTACHE"
                  : "elle NE TOURNE PAS : une tete immobile n'accuse alors "
                    "personne, et [GSC-TEARDOWN] se trompe de coupable");
    }
    static const long need = [] {
        const char* e = bo2_getenv("BO2_TEARDOWN_REPAIR");
        return e ? (atol(e) > 0 ? atol(e) : 3L) : 0L;
    }();
    if (need <= 0) return;
    static uint32_t last_head[2] = {0, 0};
    static long     same[2]      = {0, 0};
    for (uint32_t inst = 0; inst < 2; inst++) {
        const uint32_t head = win32_mem_read32(0x2f3b818u + inst * 0x54u);
        if (!head) { last_head[inst] = 0; same[inst] = 0; continue; }
        if (head != last_head[inst]) { last_head[inst] = head; same[inst] = 0; continue; }
        if (++same[inst] < need) continue;
        same[inst] = 0;
        const uint32_t idxt = win32_mem_read32(0x2f3b480u + (inst << 9));
        const uint32_t t580 = win32_mem_read32(0x2f3b400u + (inst << 9));
        if (!idxt || !t580) continue;
        // 🎯 DRAIN THE WHOLE LIST IN ONE VISIT, not one child per visit.
        // The first version unlinked a single child per trigger. At 3 host
        // samples of 8 s that is 24 s per entry, and inst 0 carries ~25 of them —
        // ten minutes, while [RUNAWAY] aborts after 3M frameless imports. The
        // repair was correct and simply too slow to matter. Measured: it reached
        // repair 4 of ~25 before the run was killed.
        //
        // Bounded, and it never trusts the links it is walking: a self-link or a
        // cycle ends the pass instead of spinning it.
        {
            uint32_t seen_first = 0;
            for (int k = 0; k < 4096; k++) {
                const uint32_t f = (uint32_t)(win32_mem_read32(idxt + head * 4u) & 0xffffu);
                if (!f) break;
                if (f == seen_first) {          // the head stopped changing: a cycle
                    win32_mem_write8(idxt + head * 4u, 0);
                    win32_mem_write8(idxt + head * 4u + 1, 0);
                    fprintf(stderr, "[TEARDOWN-REPAIR] inst=%u head 0x%04x: child 0x%04x "
                                    "repeats — the sibling chain is CYCLIC, clearing the head\n",
                            inst, head, f);
                    break;
                }
                seen_first = f;
                uint32_t ns = (uint32_t)(win32_mem_read32(t580 + f * 16u + 0xcu) & 0xffffu);
                if (ns == f) ns = 0;            // self-linked: drop, never re-point
                win32_mem_write8(idxt + head * 4u,     (uint8_t)(ns & 0xff));
                win32_mem_write8(idxt + head * 4u + 1, (uint8_t)(ns >> 8));
            }
        }
        const uint32_t first = (uint32_t)(win32_mem_read32(idxt + head * 4u) & 0xffffu);
        if (!first) {
            static uint64_t ndone = 0;
            if (++ndone <= 10)
                fprintf(stderr, "[TEARDOWN-REPAIR] inst=%u head 0x%04x fully drained in one "
                                "pass (drain %llu)\n", inst, head, (unsigned long long)ndone);
            continue;
        }
        uint32_t nextsib = (uint32_t)(win32_mem_read32(t580 + first * 16u + 0xcu) & 0xffffu);
        // 🎯 A SELF-LINKED SIBLING IS WHY THE LIST NEVER ENDS. Measured on the
        // fifth repair of an angola run:
        //     unlinked first child 0x0017, next 0x0017
        // the node's "next sibling" IS the node. Writing that back leaves the
        // head pointing at the same child forever, so the repair would loop as
        // surely as the teardown did. This is the same corruption the variable
        // audit counts as "self links" (angola: 5,191 of them against 195 during
        // a healthy load). Drop the child instead of re-pointing at it.
        if (nextsib == first) {
            static uint64_t nself = 0;
            if (++nself <= 10)
                fprintf(stderr, "[TEARDOWN-REPAIR] child 0x%04x is SELF-LINKED "
                                "(next == itself) — dropping it instead of re-pointing "
                                "(self %llu)\n", first, (unsigned long long)nself);
            nextsib = 0;
        }
        win32_mem_write8(idxt + head * 4u,     (uint8_t)(nextsib & 0xff));
        win32_mem_write8(idxt + head * 4u + 1, (uint8_t)(nextsib >> 8));
        static uint64_t nrep = 0;
        if (++nrep <= 20 || (nrep % 50) == 0)
            fprintf(stderr, "[TEARDOWN-REPAIR] inst=%u head 0x%04x unchanged across %ld host "
                            "samples — unlinked first child 0x%04x, next 0x%04x (repair %llu)\n",
                    inst, head, need, first, nextsib, (unsigned long long)nrep);
    }
}

extern std::atomic<bool> g_bo2_in_level_zone;
// -1 : pas encore lu ; 0 : eteint ; 1 : arme. Un entier global et une branche predite (pas de static de bloc).
static int g_crumbs_on = -1;
[[gnu::noinline, gnu::cold]] static bool crumbs_resolve() {
#if defined(__ANDROID__)
    g_crumbs_on = bo2_env_on("BO2_CRUMBS") ? 1 : 0;
#else
    g_crumbs_on = bo2_env_on("BO2_CRUMBS", true) ? 1 : 0;
#endif
    fprintf(stderr, "[CRUMBS] anneau des repartitions %s (BO2_CRUMBS)\n", g_crumbs_on ? "ARME" : "eteint");
    return g_crumbs_on > 0;
}
// Android : une voie courte devant crumb_and_check, toujours en ligne. Dans une partie ordinaire aucune de ses
// sondes n'est armee (anneau eteint, BO2_WALK_LOG / BO2_PRED_WATCH / BO2_EBP_WATCH absents, RING2 au repos) : il ne
// reste que audio_preempt et les tests d'esp. L'appel complet et ses gardes de statiques coutaient encore 2,8 % du
// serveur et ~1 % du fil ordonnanceur (S26). g_crumb_court : -1 pas resolu, 0 entree complete, 1 voie courte.
static void crumb_and_check_full(State& s, char kind, uint32_t target);
static int g_crumb_court = -1;
[[gnu::always_inline]] static inline void crumb_and_check(State& s, char kind, uint32_t target) {
#if defined(__ANDROID__)
    const uint32_t esp = s.gpr.rsp.dword;
    if (__builtin_expect(g_crumb_court > 0 && !g_r2_armed && esp - 0x00010000u < 0xfff00000u - 0x00010000u &&
                             esp - 0x00400000u >= 0x00a40000u - 0x00400000u && target != 0x00839f70u &&
                             target != 0x00657a50u && target != 0x0095eb50u && target != 0x00964030u &&
                             target != 0x00964046u, 1)) {
        audio_preempt();
        return;
    }
#endif
    crumb_and_check_full(s, kind, target);
}
static void crumb_and_check_full(State& s, char kind, uint32_t target) {
#if defined(__ANDROID__)
    if (__builtin_expect(g_crumb_court < 0, 0)) {
        const bool sondes = (g_crumbs_on < 0 ? crumbs_resolve() : g_crumbs_on > 0) || bo2_getenv("BO2_WALK_LOG") ||
                            bo2_getenv("BO2_PRED_WATCH") || (g_ebp_watch < 0 ? ebp_watch_init() : g_ebp_watch) != 0;
        g_crumb_court = sondes ? 0 : 1;
        fprintf(stderr, "[CRUMBS] voie courte des repartitions : %s\n", g_crumb_court ? "ARMEE" : "non (sondes armees)");
    }
#endif
    // 🎯 BO2_PRED_WATCH=1 — READ THE COUNTDOWN MAIN NEVER ESCAPES.
    //
    // The angola freeze is main spinning in the job-wait at 0x8fb170, whose exit
    // test is `call edi` -> 0x839f70, a predicate that decrements a counter and
    // returns TRUE only when the OLD value was EXACTLY 0. Measured: 102,915,399
    // imports with zero frames, so it never fires. The one thing not yet known is
    // the counter's ADDRESS and VALUE, and the predicate is reached INDIRECTLY —
    // so it already passes through here and needs no interpose.
    //
    // Read-only: the argument is at [esp+4] at entry (stdcall, one arg). Capped
    // and it ANNOUNCES its cap; prints the first few and then only on a change of
    // sign, because the value walking negative is the whole hypothesis.
    if (__builtin_expect(target == 0x839f70u, 0)) {
        static const int on = bo2_getenv("BO2_PRED_WATCH")
                            ? atoi(bo2_getenv("BO2_PRED_WATCH")) : 0;
        if (on) {
            static uint64_t hits = 0, shown = 0;
            const uint32_t argp = win32_mem_read32(s.gpr.rsp.dword + 4);
            const int32_t  val  = (int32_t)win32_mem_read32(argp);
            // ⚠️ MEASURED, and it killed my own reading: the counter runs
            // 1 -> 0 -> the predicate returns TRUE and the wait ENDS. It is a
            // ONE-SHOT spin budget, freshly initialised in a stack local for
            // every wait (the address moves: 0x10fcb4, 0x10fcac, 0x10ed10...).
            // So the exact-zero test is fine and this wait is NOT where main is
            // stuck — main completes ~115,000 of these in the frozen span. The
            // first version of this probe printed "CROSSED ZERO; can never fire
            // again" on that entirely normal transition.
            static int32_t last = 0x7fffffff;
            const bool turned = (last > 0 && val < 0);   // genuinely underflowed
            hits++;
            if (shown < 12 || turned || (hits % 200000) == 0) {
                shown++;
                fprintf(stderr, "[PRED] #%llu tid=%d counter@0x%08x = %d%s\n",
                        (unsigned long long)hits, win32_current_tid(), argp, val,
                        turned ? "   <-- NEGATIVE: underflowed past the exact-zero "
                                 "test (this one IS anomalous)" : "");
            }
            last = val;

            // 🎯 NAME THE OUTER LOOP. The job-wait itself is fine — the counter
            // runs 1 -> 0 and the wait ENDS, ~115,000 times in the frozen span.
            // So the question is who keeps CALLING it. sub_8fb9d0 is the job
            // system's public wait and is reached by a direct call, which the
            // crumb ring cannot see; and main's stack differs between runs, so a
            // fixed offset would be a guess.
            //
            // Scan main's stack for a word that is a REAL return address by
            // R77's test — the five bytes before its target must be a `call
            // rel32` — and whose call targets the job wait. That is exact: no
            // offset arithmetic, and a stale stack word cannot pass it.
            if (shown <= 12) {
                const uint32_t sp = s.gpr.rsp.dword;
                for (uint32_t a = sp; a < sp + 0x400; a += 4) {
                    const uint32_t w = win32_mem_read32(a);
                    if (w < 0x401000u || w >= 0xa00000u) continue;
                    if (win32_mem_read8(w - 5) != 0xE8) continue;
                    uint32_t rel = win32_mem_read32(w - 4);
                    const uint32_t tgt = w + rel;              // wraps by design
                    if (tgt != 0x8fb9d0u && tgt != 0x8fb170u) continue;
                    static std::unordered_map<uint32_t,int> seen;
                    if (seen[w]++ == 0)
                        fprintf(stderr, "[PRED-CALLER] the job wait 0x%08x was "
                                        "entered from 0x%08x (tid %d)\n",
                                tgt, w, win32_current_tid());
                    break;
                }
            }
        }
    }
    // 🎯 EVERY ASSET THE ZONE WALK ACTUALLY PROCESSES. The per-asset handler is
    // reached by `call eax` at 0x779642 — an INDIRECT call, so it lands here and
    // esi still holds the 16-byte record. Detect the site by its return address
    // and log the record's type. Comparing the level zone's types against the
    // frontend's says immediately whether scriptparsetree records are present and
    // skipped, or absent from the walk entirely.
    {
        static const long lim = [] {
            const char* e = bo2_getenv("BO2_WALK_LOG");
            return e ? (atol(e) > 0 ? atol(e) : 20000L) : 0L;
        }();
        // ⚠️ THE unordered_map TALLY THAT FOUND 0x7780b2 IS GONE. It did its job
        // (naming the campaign zone's dispatch site) and then cost a run: a hash
        // insert on every single dispatch is far too much for this path, and the
        // process died early with it armed. A probe that changes the thing it
        // measures has to be removed once it has answered.
        // ⚠️ 0x7780b2 IS NOT AN ASSET-RECORD SITE — the hook that assumed it was
        // is removed. It reported the SAME record forty times with an asset
        // pointer of 0x6c30bc15, which is not a guest address at all: `esi` there
        // does not hold a 16-byte record, and the earlier "48=19" was a type byte
        // read out of unrelated memory. The site is real (5,434 dispatches during
        // the campaign zone, paired with 0x66b929, while the frontend's 0x779644
        // is silent) — but what it carries is still unknown, and reading it with
        // the other path's structure produced pure noise.
        //
        // Transposing a struct layout from one call site to another without
        // checking it is the same mistake as trusting the file's disassembly:
        // plausible, cheap to verify, and wrong.
        if (lim && win32_mem_read32(s.gpr.rsp.dword) == 0x00779644u) {
            const uint32_t rec = s.gpr.rsi.dword;
            const uint32_t ty = win32_mem_read32(rec) & 0xffu;
            static uint64_t bytype[64] = {0};
            static long n = 0;
            if (ty < 64) bytype[ty]++;
            if (++n % 2000 == 0 || n == 50) {
                char b[300]; size_t o = 0;
                for (int t = 0; t < 64; t++)
                    if (bytype[t]) o += (size_t)snprintf(b + o, sizeof b - o, " %d=%llu",
                                                         t, (unsigned long long)bytype[t]);
                fprintf(stderr, "[WALK] %ld assets handled; by type:%s\n", n, b);
            }
        }
    }
    // 🎯 CATCH AN ABSURD _chkstk RESERVATION AT THE MOMENT IT IS MADE.
    // 0x95eb50 is MSVC's _chkstk; eax is the byte count it will walk esp down
    // by. The recurring [WATCHDOG stall] shows eax=0xe9fe3efa — 3.9 GB — which
    // wraps esp to 0xfffffff8 (-8) and kills the thread. The stack census
    // proves the stacks themselves are healthy (all under 60%), so the defect
    // is the SIZE, computed somewhere from corrupted data. Name the call site:
    // [esp] at entry is the return address, i.e. exactly who asked.
    // 🎯 WHO RE-ADDS REGISTRY ENTRIES WHILE THE TEARDOWN IS DRAINING THEM?
    // angola's registryDepth oscillates 152 -> 24 -> 152 -> 24 forever, so the
    // teardown removes 128 entries and something puts them back. --xref on the
    // head 0x2f3b818 finds exactly three writers:
    //   0x47013e  the per-instance INITIALISER (allocates every table)
    //   0x47751c  inside Scr_ShutdownSystem — the drain
    //   0x5073b0  mov [esi+0x2f3b818], eax   right after `call 0x657a50`
    // so 0x657a50 mints a node and 0x5073b0 links it as the new head. Count the
    // mint and name its caller: that is the adder, by construction.
    if (target == 0x00657a50u) {
        static uint64_t nadd = 0;
        ++nadd;
        if (nadd <= 6 || (nadd % 2000) == 0)
            fprintf(stderr, "[REG-ADD] node mint #%llu ret=0x%08x esp=0x%08x\n",
                    (unsigned long long)nadd,
                    win32_mem_read32(s.gpr.rsp.dword), s.gpr.rsp.dword);
    }
    if (target == 0x0095eb50u || target == 0x00964030u || target == 0x00964046u) {
        const uint32_t want = s.gpr.rax.dword;
        if (want > (4u << 20)) {                       // > 4 MB is never legitimate
            static uint32_t nbig = 0;
            if (++nbig <= 12)
                fprintf(stderr, "[CHKSTK-ABSURD] #%u reserve=0x%08x (%.1f MB) "
                                "esp=0x%08x ret=0x%08x — this wraps esp\n",
                        nbig, want, want / 1048576.0, s.gpr.rsp.dword,
                        win32_mem_read32(s.gpr.rsp.dword));
        }
    }

    // P658/C12 : écrit une fois. Un `strb` inconditionnel à chaque répartition
    // réclamait la ligne en exclusif sur chaque cœur hébergé, valeur inchangée.
    if (__builtin_expect(!g_iat_watch_armed, 0)) g_iat_watch_armed = true;
    ebp_poison_probe(s, kind, target);
    audio_preempt();
    // Android : l'anneau de miettes (un identifiant de fil, une lecture de la pile invitee et une ligne partagee
    // par tous les fils, a chaque repartition indirecte) ne sert qu'aux rapports de plantage ; il pesait 1 % du
    // fil ordonnanceur et 5,6 % du serveur sur le S26. BO2_CRUMBS=1 le remet ; ailleurs il reste arme.
    if (__builtin_expect(g_crumbs_on != 0, 0) && (g_crumbs_on > 0 || crumbs_resolve())) {
        g_crumbs[g_crumb_n & 2047] = {kind, (uint8_t)win32_current_tid(), target,
                                     s.gpr.rsp.dword,
                                     win32_mem_read32(s.gpr.rsp.dword),
                                     s.gpr.rdx.dword};
        g_crumb_n++;
    }
    // RING2 dispatch trail (armed during the patch.ff load)
    if (g_r2_armed) { g_jr[g_jrn & 32767u] = target; g_jrn++; }
    uint32_t esp = s.gpr.rsp.dword;
    // 🎯 THE FIRST DISPATCH AT WHICH ESP IS NO LONGER ON ITS OWN STACK.
    //
    // [ESP-TRAP2] below only fires when esp lands INSIDE THE PE IMAGE, and tid 10
    // dies with esp = 0xffffffec / 0x00000008 / 0x00000000 — nowhere near it, so
    // that trap has never once seen this. [STACK-ESCAPE] does test the right
    // thing but fires from the IMPORT DISPATCHER, and the thread that needs it
    // calls no imports; [ESP-WILD] tests it from the host clock, which is minutes
    // late. This is the same test on the one path a wedged guest still crosses —
    // every indirect call, jump and missing-block dispatch — so it names the
    // FIRST one, with the crumb trail that led there.
    //
    // ⚠️ Reports once per thread and does NOT abort. Aborting here would destroy
    // the very run whose later behaviour is the question, and this fires on a
    // thread that is already unrecoverable — the value is the address, not the
    // stop.
    // ⚠️ COST FIRST. The first version called win32_thread_stack_range on EVERY
    // dispatch — a cross-TU call with a bounds-checked vector index on the
    // hottest path in the runtime — and the load slowed by ~25x (imports per HUD
    // sample fell from 246,682 to 9,162 at the same phase). GUIDE rule: an
    // instrument that perturbs the schedule measures a DIFFERENT program.
    // So filter with two compares that cost nothing, and only then pay for the
    // lookup. Every wild esp actually observed on tid 10 is 0x00000000,
    // 0x00000008, 0xfffffff8 or 0xffffffec, while the main thread's normal esp
    // is ~0x0010ecfc and guest coroutine stacks live above 0x40000000 — so this
    // window is far from any legitimate value.
    // ⚠️ AND IT REPORTS ITS OWN LIMIT: an esp that goes wild WITHOUT landing in
    // this window is not caught. That is a deliberate trade, written down rather
    // than left for someone to read the silence as "esp was fine".
    if (esp < 0x00010000u || esp >= 0xfff00000u) {
        uint32_t lo = 0, hi = 0;
        const int tid = win32_current_tid();
        win32_thread_stack_range(tid, &lo, &hi);
        if (lo && hi && (esp < lo || esp >= hi)) {
            static uint8_t said[64] = {0};
            const int k = (tid >= 0 && tid < 64) ? tid : 63;
            if (said[k]++ == 0) {
                fprintf(stderr, "\n🎯 [ESP-FIRST-WILD] tid %d: esp=0x%08x left its stack "
                        "[0x%08x,0x%08x) at a %c-dispatch to %#010x\n"
                        "   eax=%08x ebx=%08x ecx=%08x edx=%08x esi=%08x edi=%08x ebp=%08x\n"
                        "   the 24 dispatches before this one:\n",
                        tid, esp, lo, hi, kind, target,
                        s.gpr.rax.dword, s.gpr.rbx.dword, s.gpr.rcx.dword, s.gpr.rdx.dword,
                        s.gpr.rsi.dword, s.gpr.rdi.dword, s.gpr.rbp.dword);
                for (unsigned i = (g_crumb_n > 24u ? g_crumb_n - 24u : 0u); i < g_crumb_n; i++) {
                    auto& c = g_crumbs[i & 2047];
                    if (c.kind && c.tid == (uint8_t)tid)
                        fprintf(stderr, "   [crumb] %c target=%#010x esp=0x%08x [esp]=0x%08x\n",
                                c.kind, c.target, c.esp, c.tos);
                }
            }
        }
    }
    if (esp >= 0x00400000 && esp < 0x00a40000) {
        fprintf(stderr,
                "[ESP-TRAP2] %c-dispatch target=%#010x esp=0x%08x "
                "eax=0x%08x ebx=0x%08x ecx=0x%08x edx=0x%08x esi=0x%08x edi=0x%08x ebp=0x%08x\n",
                kind, target, esp, s.gpr.rax.dword, s.gpr.rbx.dword,
                s.gpr.rcx.dword, s.gpr.rdx.dword, s.gpr.rsi.dword,
                s.gpr.rdi.dword, s.gpr.rbp.dword);
        // ⚠️ Show the MOST RECENT entries. With the ring at 128 `g_crumb_n + i`
        // happened to be the oldest-first walk of a full ring; at 16384 it would
        // print 128 stale entries from thousands of dispatches ago.
        for (unsigned i = (g_crumb_n > 256u ? g_crumb_n - 256u : 0u); i < g_crumb_n; i++) {
            auto& c = g_crumbs[i & 2047];
            if (c.kind)
                fprintf(stderr, "  [crumb] tid%-2u %c target=%#010x esp=0x%08x "
                        "[esp]=0x%08x edx=0x%08x\n",
                        c.tid, c.kind, c.target, c.esp, c.tos, c.edx);
        }
        abort();
    }
}

// --- GSC script-VM operand-stack tracer -------------------------------------
// The VM's opcode dispatch is `jmp [ecx*4 + 0x883060]`, a computed jump, so every
// opcode handler is entered through __remill_jump — the shim sees all of them,
// with live registers. During the VM loop esi is the operand-stack pointer
// (8-byte entries) and [ebp+0x44] is the current thread's frame base, so the
// stack depth is exactly (esi - [ebp+0x44]) / 8.
//
// FUN_0087e1d0 (save a suspended thread's stack, called by `wait`) sizes its copy
// from that difference with an ARITHMETIC shift, so a negative depth becomes a
// ~4-billion-iteration loop. Report the first opcode that drives the depth below
// zero, with the handlers that ran before it — that names the opcode whose
// push/pop balance is wrong.
#define GSC_FETCH 0x0087f878u
#define GSC_TABLE 0x00883060u
#define GSC_NOPC  124
int g_gsc_on = [] { const char* e = bo2_getenv("BO2_GSC_TRACE"); return e ? atoi(e) : 0; }();
static std::unordered_map<uint32_t, int> g_gsc_opc;   // handler VA -> opcode index
static struct { uint16_t op; int32_t depth; uint32_t esi, ip, tos_ty, tos_dat; } g_gsc_ring[512];

// Accessor so code ABOVE this point can read the tracer's newest entry — the ring
// and g_gsc_n are defined here, and the raise-site probe lives near the top.
void win32_gsc_prev_operand(uint32_t* ip, uint32_t* op) {
    if (g_gsc_n < 2u) { if (ip) *ip = 0; return; }
    const auto& e = g_gsc_ring[(g_gsc_n - 2u) & 511u];
    if (ip) *ip = e.ip; if (op) *op = e.op;
}
void win32_gsc_dump_tail(int n) {
    const unsigned have = (g_gsc_n < (unsigned)n) ? g_gsc_n : (unsigned)n;
    fprintf(stderr, "[RAISE-AT]   the %u opcodes before it (oldest first):\n", have);
    for (unsigned k = g_gsc_n - have; k != g_gsc_n; ++k) {
        const auto& e = g_gsc_ring[k & 511u];
        fprintf(stderr, "[RAISE-AT]     op=0x%02x ip=0x%08x depth=%d tos.ty=0x%x tos.dat=0x%08x\n",
                e.op, e.ip, e.depth, e.tos_ty, e.tos_dat);
    }
}
// The ring records the VM's operand-stack pointer too, and nothing read it. The
// raise site at 0x8829d5 does `mov eax,[esi]` — the TYPE of the operand it is
// about to reject — so esi is where the dead object sits, and exposing it is the
// difference between "an object was freed" and "object 0x____ was freed".
uint32_t win32_gsc_last_esi(void) { return g_gsc_ring[(g_gsc_n - 1u) & 511u].esi; }
void win32_gsc_last_op(uint32_t* ip, uint32_t* op, int32_t* depth,
                       uint32_t* ty, uint32_t* dat) {
    const auto& e = g_gsc_ring[(g_gsc_n - 1u) & 511u];
    if (ip) *ip = e.ip; if (op) *op = e.op; if (depth) *depth = e.depth;
    if (ty) *ty = e.tos_ty; if (dat) *dat = e.tos_dat;
}

// ── [GSC-LOOP] — WHICH BYTECODE THE VM IS GOING ROUND ───────────────────────
//
// Measured: gscRun is FLAT while gscOp climbs by ~1.1 MILLION per cadence period.
// So no new script is being invoked and one invocation is looping — the engine is
// busy, not blocked, which is why every thread reads "unchanged" and no error is
// ever raised.
//
// The opcode tracer already rings (op, ip) pairs, ip being the VM's own
// instruction pointer from EBX. A loop body is a small set of ips repeated, so a
// frequency count over the ring names it directly; a script that were merely slow
// would show 512 distinct ips instead.
uint64_t g_obj_hist[64] = {0};
uint32_t g_seed_src_rec = 0;
std::vector<std::pair<std::string, uint64_t>> g_err_cat;
extern "C" void win32_err_catalogue_report() {
    // ⚠️ THREE OUTCOMES, THREE DIFFERENT LINES. Returning silently made "the
    // catalogue was not armed", "it was armed and the engine raised nothing" and
    // "this function was never called" the same silence — the exact ambiguity
    // GUIDE §8 rule 1 exists to forbid, and it cost a run today: an angola run
    // that reached [SETORIGIN] and presented 2,000 frames reported
    // "error catalogue 0 entries" simply because the harness killed it before
    // anything called this.
    if (!bo2_env_on("BO2_ERR_CATALOGUE")) {
        fprintf(stderr, "[ERR-CAT] not armed (set BO2_ERR_CATALOGUE=1) — this run "
                        "says NOTHING about which errors the engine raised\n");
        return;
    }
    if (g_err_cat.empty()) {
        fprintf(stderr, "[ERR-CAT] armed, and EMPTY: the engine raised no distinct "
                        "message-builder error in this run\n");
        return;
    }
    fprintf(stderr, "\n[ERR-CAT] %zu distinct engine error(s), in first-seen order:\n",
            g_err_cat.size());
    size_t i = 0;
    for (const auto& kv : g_err_cat)
        fprintf(stderr, "[ERR-CAT] %2zu. x%-6llu %s\n", ++i,
                (unsigned long long)kv.second, kv.first.c_str());
    fprintf(stderr, "[ERR-CAT] (message-builder errors only; silent loops and "
            "host-side stalls are not in this list)\n\n");
}

extern "C" void win32_obj_hist_report() {
    struct P { uint32_t id; uint64_t n; };
    std::vector<P> v;
    for (uint32_t i = 0; i < 64u; ++i) if (g_obj_hist[i]) v.push_back({i, g_obj_hist[i]});
    std::sort(v.begin(), v.end(), [](const P& a, const P& b) { return a.n > b.n; });
    fprintf(stderr, "[OBJ-HIST] resolver traffic by object id (top 10 of %zu):\n", v.size());
    for (size_t i = 0; i < v.size() && i < 10u; ++i)
        fprintf(stderr, "[OBJ-HIST]   obj=0x%04x  %llu lookup(s)%s\n", v[i].id,
                (unsigned long long)v[i].n,
                v[i].id == 0x2fu ? "   <== the one the freezing loop reads"
              : v[i].id == 0x03u ? "   <== the one the field was written on" : "");
}

extern "C" void win32_gsc_loop_report() {
    // 🎯 THE SCRIPT-ERROR SLOT AT THE FREEZE. sub_4e6870 records a message into
    // [inst*0x54 + 0x2f3b808] and SKIPS if one is already there; the VM core reads
    // that slot in 10+ places. So either it is set and nobody acted, or it is
    // clear and the recording is being lost. The buffer at 0x2f48f68 carries the
    // formatted text, which names the TYPE that is not a valid array index.
    // ⚠️ GATED, AND THE GATE IS NOT OPTIONAL. Ungated, this block cost the level
    // its load FOUR runs in a row — proven by stashing it and watching angola load
    // immediately. win32_gsc_loop_report also runs during the FRONTEND's
    // frozen-present detection, where these reads land on an uninitialised pool.
    // Fifth time today that a diagnostic changed whether the run happens; the
    // lesson is not "be careful" but "gate every new read by default".
    static const bool scr_err_on = bo2_getenv("BO2_SCR_ERR") != nullptr;
    for (uint32_t inst_ = 0; scr_err_on && inst_ < 2u; ++inst_) {
        const uint32_t slot = win32_mem_read32(inst_ * 0x54u + 0x2f3b808u);
        char msg[160]; int mn = 0;
        if (slot) {
            while (mn < 159) { const uint8_t c = win32_mem_read8(0x2f48f68u + (uint32_t)mn);
                               if (c < 0x20 || c > 0x7e) break; msg[mn++] = (char)c; }
        }
        msg[mn] = 0;
        fprintf(stderr, "[SCR-ERR] inst=%u slot=0x%08x%s%s\n", inst_, slot,
                slot ? "  message=" : "  (no error recorded — the raise is being lost)",
                slot ? msg : "");
    }
    extern int g_gsc_on;
    if (!g_gsc_on) { fprintf(stderr, "[GSC-LOOP] tracer off (set BO2_GSC_TRACE=1)\n"); return; }
    struct Hit { uint32_t ip; uint32_t op; uint32_t n; };
    std::vector<Hit> h;
    for (unsigned k = 0; k < 512u; ++k) {
        const auto& e = g_gsc_ring[k];
        if (!e.ip) continue;
        bool found = false;
        for (auto& x : h) if (x.ip == e.ip) { ++x.n; found = true; break; }
        if (!found) h.push_back({e.ip, e.op, 1u});
    }
    std::sort(h.begin(), h.end(), [](const Hit& a, const Hit& b) { return a.n > b.n; });
    fprintf(stderr, "[GSC-LOOP] %zu distinct bytecode address(es) in the last 512 opcodes%s\n",
            h.size(), h.size() < 64u ? "  <== a tight loop" : " — spread out, not one loop");
    for (size_t i = 0; i < h.size() && i < 12u; ++i)
        fprintf(stderr, "[GSC-LOOP]   ip=0x%08x op=0x%02x  x%u\n", h[i].ip, h[i].op, h[i].n);
    // 🎯 THE OPERAND STACK, in ring order. Host backtraces have named three
    // different places for this freeze (the allocator, the CRT formatter, the
    // message builder) because the sampler catches the same GSC loop doing
    // different work. The VM's own operand stack does not move around: the value
    // the loop keeps testing is what never becomes true, and the ring already
    // carries (type, data) for every opcode. Last 24 in execution order.
    {
        fprintf(stderr, "[GSC-LOOP] last 24 opcodes with the operand stack top:\n");
        const unsigned n0 = (g_gsc_n > 24u) ? g_gsc_n - 24u : 0u;
        for (unsigned k = n0; k != g_gsc_n; ++k) {
            const auto& e = g_gsc_ring[k & 511u];
            fprintf(stderr, "[GSC-LOOP]   op=0x%02x ip=0x%08x depth=%d tos.ty=0x%x tos.dat=0x%08x\n",
                    e.op, e.ip, e.depth, e.tos_ty, e.tos_dat);
        }
    }
    // 🎯 THE AUTHORITATIVE ANSWER: WHICH ALLOCATION OWNS THE LOOPING BYTECODE.
    //
    // String proximity is not evidence of ownership — the run that named
    // "animscripts/bigdog/bigdog_utility.gsc" and the one that named
    // "maps/_cheat.gsc" disagreed because script buffers are packed and the
    // nearest path below is a neighbour as often as an owner. A buffer BOUNDARY
    // is authoritative, so ask the heap who owns the ip and bound the name search
    // to that block. If the block turns out to be huge the line says so, which is
    // still an honest answer rather than a confident wrong one.
    if (!h.empty()) {
        uint32_t base = 0, sz = 0; int fr = 0, ru = 0;
        win32_heap_owner(h[0].ip, &base, &sz, &fr, &ru);
        if (base) {
            fprintf(stderr, "[GSC-LOOP] the ip lies in alloc 0x%08x+0x%x (freed=%d reused=%d), "
                    "%u bytes into it\n", base, sz, fr, ru, h[0].ip - base);
            char nm[128]; nm[0] = 0;
            const uint32_t end = (h[0].ip < base + sz) ? h[0].ip : base + sz;
            for (uint32_t a = base; a + 4u < end && !nm[0]; ++a) {
                if (win32_mem_read8(a) != (uint8_t)'.' || win32_mem_read8(a+1) != (uint8_t)'g' ||
                    win32_mem_read8(a+2) != (uint8_t)'s' || win32_mem_read8(a+3) != (uint8_t)'c') continue;
                uint32_t st = a;
                while (st > a - 96u && st > base) {
                    const uint8_t c = win32_mem_read8(st - 1u);
                    if (c < 0x20 || c > 0x7e) break;
                    --st;
                }
                int n = 0;
                for (uint32_t q = st; q <= a + 3u && n < 127; ++q) nm[n++] = (char)win32_mem_read8(q);
                nm[n] = 0;
            }
            if (nm[0])
                fprintf(stderr, "🎯 [GSC-LOOP] first script path inside that block: \"%s\"\n", nm);
            else
                fprintf(stderr, "[GSC-LOOP] no script path inside that block — the buffer does not "
                        "carry one, so the ip cannot be named this way\n");
        } else {
            fprintf(stderr, "[GSC-LOOP] the heap does not own ip 0x%08x — it is not in a tracked "
                    "allocation, so ownership cannot settle the name\n", h[0].ip);
        }
    }
    // 🎯 NAME THE SCRIPT. A compiled GSC buffer carries its own source path, so
    // scanning BACKWARD from the looping ip for a "...gsc" string identifies the
    // file without needing the script registry's layout. Bounded to 512 KB and to
    // printable ASCII, and it reports what it did NOT find as clearly as what it
    // did — a silent miss would read like "no script", which is never true.
    if (!h.empty()) {
        const uint32_t ip = h[0].ip;
        char best[128]; best[0] = 0;
        uint32_t best_at = 0;
        for (uint32_t back = 0; back < 512u * 1024u && !best[0]; ++back) {
            const uint32_t a = ip - back;
            if (win32_mem_read8(a) != (uint8_t)'.' ||
                win32_mem_read8(a + 1) != (uint8_t)'g' ||
                win32_mem_read8(a + 2) != (uint8_t)'s' ||
                win32_mem_read8(a + 3) != (uint8_t)'c') continue;
            uint32_t st = a;
            while (st > a - 96u) {
                const uint8_t c = win32_mem_read8(st - 1u);
                if (c < 0x20 || c > 0x7e) break;
                --st;
            }
            int n = 0;
            for (uint32_t q = st; q <= a + 3u && n < 127; ++q) best[n++] = (char)win32_mem_read8(q);
            best[n] = 0; best_at = st;
        }
        // ⚠️ AND THE NEAREST NAME ABOVE, because "nearest .gsc below" is only the
        // right answer if script buffers are packed with the name first. If
        // another path sits closer ABOVE the loop, the attribution is ambiguous
        // and must be said so rather than reported as fact.
        char above[128]; above[0] = 0; uint32_t above_at = 0;
        for (uint32_t fwd = 1; fwd < 512u * 1024u && !above[0]; ++fwd) {
            const uint32_t a = ip + fwd;
            if (win32_mem_read8(a) != (uint8_t)'.' ||
                win32_mem_read8(a + 1) != (uint8_t)'g' ||
                win32_mem_read8(a + 2) != (uint8_t)'s' ||
                win32_mem_read8(a + 3) != (uint8_t)'c') continue;
            uint32_t st = a;
            while (st > a - 96u) {
                const uint8_t c = win32_mem_read8(st - 1u);
                if (c < 0x20 || c > 0x7e) break;
                --st;
            }
            int n = 0;
            for (uint32_t q = st; q <= a + 3u && n < 127; ++q) above[n++] = (char)win32_mem_read8(q);
            above[n] = 0; above_at = st;
        }
        if (above[0])
            fprintf(stderr, "[GSC-LOOP] nearest path ABOVE the loop: \"%s\" (+%u bytes)\n",
                    above, above_at - ip);
        // 🎯 THE CHECK THAT MAKES THE ATTRIBUTION DECISIVE RATHER THAN PLAUSIBLE.
        // "Nearest .gsc below" is only the owning script if NO other path lies
        // between that name and the loop. Count them: one is enough to make the
        // answer wrong, and the gap here is tens of kilobytes, which is ample room
        // for a neighbouring script to sit in.
        if (best[0]) {
            // ⚠️ START PAST THE MATCHED NAME'S OWN ".gsc". The first version began
            // at best_at+4 — the START of the name string — so it counted the very
            // ".gsc" it had just matched and always reported "1 other path", which
            // then declared every attribution unsafe. A check that cries wolf on
            // every input is worse than no check: it made me retract a name that
            // may well have been right.
            uint32_t between = 0;
            const uint32_t name_end = best_at + (uint32_t)strlen(best);
            for (uint32_t a = name_end; a + 4u < ip; ++a) {
                if (win32_mem_read8(a) == (uint8_t)'.' &&
                    win32_mem_read8(a + 1) == (uint8_t)'g' &&
                    win32_mem_read8(a + 2) == (uint8_t)'s' &&
                    win32_mem_read8(a + 3) == (uint8_t)'c') { ++between; a += 3u; }
            }
            fprintf(stderr, "[GSC-LOOP] %u other \".gsc\" path(s) lie between that name and the "
                    "loop%s\n", between,
                    between ? "  ⚠️ so the name below is NOT the owning script" :
                              "  => the attribution is sound");
        }
        if (best[0])
            fprintf(stderr, "🎯 [GSC-LOOP] the looping bytecode belongs to \"%s\" "
                    "(name at 0x%08x, %u bytes below the loop)%s\n", best, best_at, ip - best_at,
                    (above[0] && (above_at - ip) < (ip - best_at))
                        ? "  ⚠️ but a different path sits CLOSER above — attribution unsafe" : "");
        else
            fprintf(stderr, "[GSC-LOOP] no \".gsc\" path found within 512 KB below 0x%08x — "
                    "the buffer does not carry its source name there\n", ip);
    }
}

// local[0] and local[1] as seen at the last WAIT — see the capture site below.
static uint32_t g_gsc_wait_local_ty[2] = {0xffffffffu, 0xffffffffu};
static uint32_t g_gsc_wait_local_dat[2] = {0, 0};
uint64_t g_gsc_wait_seen = 0;
static uint32_t g_gsc_wait_base = 0;
unsigned g_gsc_n = 0;
uint32_t g_gsc_last_esp = 0, g_gsc_last_chain[8]; int g_gsc_last_chain_n = 0;
static int g_gsc_reported = 0;
extern "C" void win32_dump_crumbs(int);

static void gsc_note(State& s, uint32_t target) {
    if (g_gsc_opc.empty()) {                       // build the table from guest memory once
        for (int i = 0; i < GSC_NOPC; i++) {
            uint32_t h = win32_mem_read32(GSC_TABLE + i * 4);
            if (!g_gsc_opc.count(h)) g_gsc_opc[h] = i;
        }
    }
    auto it = g_gsc_opc.find(target);
    if (it == g_gsc_opc.end()) return;
    static int s_first = 0;
    if (!s_first++)
        fprintf(stderr, "[GSC] tracer armed: first opcode 0x%02x handler %#010x esi=0x%08x ebp=0x%08x\n",
                it->second, target, s.gpr.rsi.dword, s.gpr.rbp.dword);
    uint32_t esi = s.gpr.rsi.dword, ebp = s.gpr.rbp.dword;
    uint32_t base = win32_mem_read32(ebp + 0x44);
    int32_t depth = (int32_t)(esi - base) >> 3;
    // 🎯 LATCH THE FIRST UNDERFLOW, THE INSTANT IT HAPPENS.
    //
    // depth < 0 means esi is BELOW [ebp+0x44] — the frame's own operand-stack
    // base — i.e. the VM has popped a value that was never pushed. That is the
    // root defect (2026-08-13, maps/_animatedmodels.gsc); everything the MT
    // guards work around is downstream of esi walking under the base.
    //
    // ⚠️ WHY A LATCH AND NOT A BIGGER RING. The ring holds 512 entries and the
    // dump prints 48, so by the time anything DOWNSTREAM notices (an out-of-pool
    // MT_Free, hundreds of opcodes later) the moment it broke is long gone —
    // the first dump's oldest entry was already at depth 0. Widening the ring
    // only moves that horizon; catching the transition does not depend on it.
    //
    // The PREVIOUS opcode is what actually popped, so print both: this one is
    // merely the first to be dispatched with the stack already short.
    if (__builtin_expect(depth < 0, 0)) {
        static int s_uf = 0;
        if (s_uf++ < 12) {
            const auto& prev = g_gsc_ring[(g_gsc_n - 1u) & 511u];
            fprintf(stderr, "[GSC-UNDERFLOW #%d] depth=%d esi=0x%08x base=0x%08x tid=%d\n"
                            "[GSC-UNDERFLOW]   dispatching op=0x%02x at ip=0x%08x\n"
                            "[GSC-UNDERFLOW]   the PREVIOUS op was 0x%02x at ip=0x%08x "
                            "(depth was %d) — that is the one that popped\n",
                    s_uf, depth, esi, base, win32_current_tid(),
                    it->second, s.gpr.rbx.dword,
                    g_gsc_n ? prev.op : 0u, g_gsc_n ? prev.ip : 0u,
                    g_gsc_n ? prev.depth : 0);
            // 🎯 NAME THE BUILTIN. Opcode 0x29 is a native builtin call: its
            // handler (0x880417) does `inc ebx / add ebx,3 / and ebx,~3 /
            // mov ecx,[ebx] / call ecx`, i.e. the function pointer is the dword
            // at ((ip+1)+3)&~3 — verified against the observed layout (op at
            // 0x204d0b6d -> pointer at 0x204d0b70 -> next op at 0x204d0b75).
            // A builtin that consumes its args and returns WITHOUT pushing its
            // result is exactly the one-slot deficit this latch catches, so the
            // callee's VA is the whole question. Also say whether it is lifted:
            // a stub would abort loudly, but an interposed or mis-lifted one
            // returns quietly, and those look identical from the stack alone.
            // ⚠️ SCAN BACK — the immediately previous op is 0x36 (the pop that
            // went negative); the CALL that left the stack short is further up.
            // The first version of this tested prev.op == 0x29 and printed
            // nothing at all through 37 underflows: the condition was never
            // true, and a probe that stays silent because its trigger is wrong
            // is the exact failure this file keeps a rules section about.
            for (unsigned b = 1; b <= 10u && b <= g_gsc_n; b++) {
                const auto& e = g_gsc_ring[(g_gsc_n - b) & 511u];
                if (e.op != 0x29u) continue;
                const uint32_t pv = ((e.ip + 1u) + 3u) & ~3u;
                const uint32_t fn = win32_mem_read32(pv);
                // The handler reads the ARG COUNT from the byte at [ebx] (the
                // byte right after the opcode) and, after the call, pops
                // whatever is LEFT in [0x2f3b8e4]. setdvar is a 2-arg VOID
                // builtin, yet 0x29 went from depth 3 to depth 0 — three
                // operands consumed, one too many. So print the count the
                // bytecode actually carries, and the two state words, instead
                // of reasoning about them.
                // ⚠️ argc is at [ip], NOT [ip+1]: the handler does `movzx edx,[ebx]`
                // BEFORE `inc ebx`. And the per-thread block is indexed by EDI —
                // the GSC thread index the handler uses (`mov eax,edi; imul
                // eax,0x42a8`) — not by our coroutine tid. Getting either wrong
                // prints confident nonsense: the first version read argc=34 for a
                // 2-arg builtin and 0 for both state words.
                const uint32_t argc = win32_mem_read8(e.ip);
                const uint32_t blk  = s.gpr.rdi.dword * 0x42a8u;
                fprintf(stderr, "[GSC-UNDERFLOW]   last BUILTIN CALL was %u op(s) back: "
                                "op 0x29 at ip=0x%08x (depth %d) -> fnptr@0x%08x = 0x%08x (%s)\n"
                                "[GSC-UNDERFLOW]   bytecode argc=%u | [0x2f3b8e4]=%u (args left) "
                                "[0x2f3b8d8]=0x%08x [0x2f3b8d4]=0x%08x\n",
                        b, e.ip, e.depth, pv, fn,
                        win32_lifted_has(fn) ? "lifted" : "NOT LIFTED",
                        argc,
                        win32_mem_read32(blk + 0x2f3b8e4u),
                        win32_mem_read32(blk + 0x2f3b8d8u),
                        win32_mem_read32(blk + 0x2f3b8d4u));
                break;
            }
            if (s_uf == 1) win32_gsc_dump_ring();   // once, with ip -> script resolution
        }
    }
    // Snapshot the operand currently on top of stack (8-byte VariableValue at esi-8
    // after the previous opcode pushed): its type at +0, data at +4. This is what
    // the NEXT opcode consumes, so logging it per-opcode shows which opcode left a
    // bad (e.g. type-0) value where the consumer expected an array/string.
    uint32_t tos = (esi >= base + 8) ? esi - 8 : 0;
    uint32_t tty = tos ? (win32_mem_read32(tos) & 0x7f) : 0xffffffff;
    uint32_t tdat = tos ? win32_mem_read32(tos + 4) : 0;
    unsigned i = g_gsc_n++ & 511u;
    g_gsc_ring[i] = {(uint16_t)it->second, depth, esi, s.gpr.rbx.dword, tty, tdat};
    // 🎯 [WHO-INSTALLS] — WHICH OPCODE MAKES A SELF-LESS THREAD CURRENT.
    //
    // [ebp+0x68] is [0x2f44f08 + inst*20], the running thread's record, and six
    // sites write it: 0x87e37c, 0x880d62, 0x88198c, 0x8819df, 0x88302d,
    // 0x8835f1. The first is sub_87e2e0 and [THREAD-INSTALL] has ruled it out —
    // 273 installs, ZERO with a null self, in a run with the full storm. The
    // other five are all inside the VM function, which means they are opcode
    // handlers, and this tracer already runs on the opcode path.
    //
    // So watch the global here: the opcode recorded when it changes to a record
    // whose self is zero is the handler that installed it. No mid-function hook,
    // no new lift, and it costs two guest reads on a path that is only armed
    // under BO2_GSC_TRACE.
    {
        // 🎯 [CUR-LIFE] — HOW LONG DOES A SELF-LESS THREAD STAY CURRENT?
        //
        // Two records were installed with a null self (0x022e and 0x08b3) and
        // only one produced the storm, so "self is null" is NOT a sufficient
        // condition and must not be treated as the defect. The difference has to
        // be how long each one runs. The flag is cached at the switch, so this
        // costs one increment per opcode and no extra guest read.
        static bool cur_selfless = false; static uint32_t cur_rec = 0;
        if (cur_selfless) {
            int k = 0; for (; k < g_cl_seen; k++) if (g_cl_rec[k] == cur_rec) { ++g_cl_ops[k]; break; }
            if (k == g_cl_seen && g_cl_seen < 8) { g_cl_rec[g_cl_seen] = (uint16_t)cur_rec;
                                                  g_cl_ops[g_cl_seen++] = 1; }
        }
        static uint32_t prev_cur = 0xffffffffu;
        const uint32_t cur = win32_mem_read32(0x2f44f08u) & 0xffffu;
        if (cur != prev_cur) {
            if (prev_cur != 0xffffffffu && cur) {
                const uint32_t vb = win32_mem_read32(0x2f3b400u);
                if (vb) {
                    const uint32_t self = (uint32_t)win32_mem_read8(vb + cur * 8u + 2)
                                        | ((uint32_t)win32_mem_read8(vb + cur * 8u + 3) << 8);
                    ++g_wi_switch;
                    cur_selfless = (self == 0u); cur_rec = cur;
                    if (!self) {
                        ++g_wi_zero;
                        // ⚠️ OFF BY ONE, FIXED. The sample is taken just after the
                        // ring records the opcode ABOUT TO RUN, so a change since
                        // the previous sample happened during the PREVIOUS opcode.
                        // The first version blamed `it->second` — the opcode that
                        // merely ran next — and reported 0x17 on that basis. The
                        // installer is the ring entry before this one.
                        const uint16_t o = g_gsc_ring[(g_gsc_n - 2u) & 511u].op;
                        g_wi_after[g_wi_seen < 12 ? g_wi_seen : 11] = (uint16_t)it->second;
                        int k = 0; for (; k < g_wi_seen; k++) if (g_wi_op[k] == o) { ++g_wi_n[k]; break; }
                        if (k == g_wi_seen && g_wi_seen < 12) { g_wi_op[g_wi_seen] = o;
                                                               g_wi_rec[g_wi_seen] = (uint16_t)cur;
                                                               g_wi_n[g_wi_seen++] = 1; }
                        else if (k == g_wi_seen) ++g_wi_lost;
                    }
                }
            }
            prev_cur = cur;
        }
    }
    // NAME THE FLAG. The campaign's whole blocker is `while (local0) { wait 0.01 }`
    // in clientscripts/_callbacks.csc, and local0 never goes false. Op 0x19's
    // handler shows exactly where locals live:
    //     mov ecx, edi ; imul ecx, 0x42a8 ; mov eax,[ecx + 0x2f3b8c8]
    //     sub eax, idx*4 ; mov eax,[eax]
    // so grab local[0] and local[1] whenever the WAIT opcode (0x2b) runs. Their
    // TYPE alone settles what the flag is — an entity, a bool, an int, undefined —
    // and that is the difference between "waiting for a player" and "waiting for a
    // load flag", which need different fixes.
    if (it->second == 0x2bu) {
        const uint32_t lb = win32_mem_read32(s.gpr.rdi.dword * 0x42a8u + 0x2f3b8c8u);
        if (lb) {
            // op 0x19 does `mov eax,[localBase - idx*4]` then PUSHES eax — so the
            // slot holds an ID/handle, not a (type,data) pair. Reading a type at
            // that address gave 0 for both slots, which cannot be right for a flag
            // the loop keeps testing TRUE. Record the raw slot words and the base.
            g_gsc_wait_base = lb;
            for (int L = 0; L < 2; L++)
                g_gsc_wait_local_dat[L] = win32_mem_read32(lb - (uint32_t)L * 4u);
            g_gsc_wait_seen++;
        }
    }
    // WHO IS RUNNING THE VM. The interpreter stops permanently at the frontend
    // unload, so the call chain of the LAST opcode names the caller that was
    // driving it and never came back. Cheap: eight stack scans on each opcode,
    // overwritten every time, so what survives is the final one.
    // (The sv_frame -> 0x621e90 -> 0x438fc0 path mapped from the disassembly was
    // measured NEVER CALLED — gate=0/0, submits=0 — including during the
    // frontend where the VM demonstrably runs 163,107 opcodes. So the caller has
    // to be found, not derived.)
    {
        g_gsc_last_esp = s.gpr.rsp.dword;
        int k = 0;
        for (uint32_t ad = s.gpr.rsp.dword; ad < s.gpr.rsp.dword + 0x400u && k < 8; ad += 4) {
            uint32_t rv = win32_mem_read32(ad);
            if (rv >= 0x401000u && rv < 0xa31000u) g_gsc_last_chain[k++] = rv;
        }
        g_gsc_last_chain_n = k;
    }
    if (it->second == 0x2b) {   // `wait`: the opcode that saves the thread stack
        static int s_w = 0;
        fprintf(stderr, "[GSC-WAIT] #%d esi=0x%08x ebp=0x%08x base=[ebp+0x44]=0x%08x "
                "depth=%d predicted_count=%d  type=[esi]=%u val=0x%08x\n",
                s_w++, esi, ebp, base, depth, (int32_t)((esi - 8) - base) >> 3,
                win32_mem_read32(esi), win32_mem_read32(esi + 4));
    }
    if (depth < 0 && !g_gsc_reported++) {
        fprintf(stderr, "\n[GSC-UNDERFLOW] opcode 0x%02x (handler %#010x) entered with depth=%d "
                "esi=0x%08x base=0x%08x ebp=0x%08x bytecodeIP=0x%08x\n",
                it->second, target, depth, esi, base, ebp, s.gpr.rbx.dword);
        win32_dump_crumbs(64);   // what ran between the last sane opcode and this
        unsigned have = g_gsc_n < 512u ? g_gsc_n : 512u;
        fprintf(stderr, "  preceding opcodes (oldest first): op depth esi bytecodeIP\n");
        for (unsigned k = have < 40u ? 0 : have - 40u; k < have; k++) {
            auto& r = g_gsc_ring[(g_gsc_n - have + k) & 511u];
            fprintf(stderr, "    0x%02x  depth=%-6d esi=0x%08x ip=0x%08x tos_ty=%u tos_dat=0x%08x\n",
                    r.op, r.depth, r.esi, r.ip, r.tos_ty, r.tos_dat);
        }
    }
}

// Last dispatch events, newest last. A hang in PURE lifted code makes no import
// calls and no shim dispatches at all, so the watchdog's register dump has no
// context to place it — but the crumb trail still names the last call/jump/return
// boundary the guest crossed, which brackets the loop it is stuck in.
extern "C" void win32_dump_crumbs(int want) {
    unsigned have = g_crumb_n < 2048u ? g_crumb_n : 2048u;
    unsigned n = ((unsigned)want < have) ? (unsigned)want : have;
    fprintf(stderr, "  [crumbs] last %u dispatch events (oldest first):\n", n);
    for (unsigned i = have - n; i < have; i++) {
        auto& c = g_crumbs[(g_crumb_n - have + i) & 2047];
        if (c.kind)
            fprintf(stderr, "    tid%-2u %c target=%#010x esp=0x%08x [esp]=0x%08x "
                    "edx=0x%08x\n",
                    c.tid, c.kind, c.target, c.esp, c.tos, c.edx);
    }
    fprintf(stderr, "  [crumbs] last guest return address = %#010x\n", g_last_ret_pc);
    // ⚠️ TALLIES, BECAUSE THE SERVER PROBES ARE CAPPED. bo2_sv_execclientmsg and
    // bo2_sv_packetevent print only their first 20 calls and then one in 500, so
    // their SILENCE after the menus close proves nothing at all — reading it as
    // "the command never reached the server" would be the capped-view trap for
    // the umpteenth time in this project. The counters are globals now, and this
    // watchdog runs on a host thread, so it can read them while the guest is
    // wedged. A tally that has not moved since the menus closed is evidence; an
    // absence of log lines is not.
    {
        extern uint32_t g_sv_execmsg_n, g_sv_pktev_n, g_sv_pktev_inband;
        fprintf(stderr, "  [sv-tally] execclientmsg=%u packetevent=%u (in-band=%u)\n",
                g_sv_execmsg_n, g_sv_pktev_n, g_sv_pktev_inband);
    }
    // THE COMMAND BUFFERS, VERBATIM. sub_8062a0 is Cbuf_Execute: it takes a
    // buffer index, locks #51, points a descriptor at 0x27f9cbc + i*12
    // ({text, ?, length}), and scans the text a character at a time honouring
    // quotes, ';', '\n' and '\r' — then loops while the length is non-zero.
    // The map-load stall sits in exactly that function (`sample` names
    // sub_8062a0 and nothing else), so the one thing worth knowing is WHAT TEXT
    // is in there. The descriptors are at a fixed address, and this watchdog
    // runs on a host thread, so it can read them while the guest is wedged —
    // which the guest-side probes cannot.
    // ⚠️ THERE IS EXACTLY ONE COMMAND BUFFER. This loop used to run i = 0..3 and
    // print four of them, and the extra three were pure fiction — they reported
    // "[cbuf 1] len=11257432" and "[cbuf 2] len=9634704", two absurd numbers
    // that read as a corrupted 11 MB command buffer and cost an investigation.
    //
    // 0x27f9cc8 onwards is NOT a second descriptor. A write-watchpoint on
    // 0x27f9cd0 caught the writer, sub_41b800 at 0x41bdea, and the code around
    // it is unambiguous:
    //     0x41bdea  mov [0x27f9cd0], 0xabc658      <- a string pointer
    //     0x41bdf4  mov [0x27f9cdc], 0x930390      <- a function pointer
    //     0x41bdfe  mov [0x27f9ccc], esi           <- a `next` link
    //     0x41be04  mov [0x27ea1dc], 0x27f9ccc     <- list head
    // — a linked list of registration records that happens to sit immediately
    // after the one real descriptor. 0xabc658 was being printed as a LENGTH.
    //
    // The middle field of the real descriptor is the CAPACITY: Cbuf_AddText
    // (0x54bd10) computes the same address and refuses when
    // `length + strlen(new) > [desc+4]`. Printing it makes a bad length obvious
    // instead of merely large.
    for (uint32_t i = 0; i < 1; i++) {
        const uint32_t d   = 0x27f9cbcu + i * 12u;
        const uint32_t txt = win32_mem_read32(d);
        const uint32_t cap = win32_mem_read32(d + 4);
        const uint32_t len = win32_mem_read32(d + 8);
        if (!len) continue;
        if (len > cap)
            fprintf(stderr, "  [cbuf %u] ⚠️  len=%u EXCEEDS capacity=%u (text=0x%08x)\n",
                    i, len, cap, txt);
        char buf[241];
        uint32_t n = 0;
        for (; n < sizeof buf - 1 && n < len; n++) {
            const uint8_t c = win32_mem_read8(txt + n);
            buf[n] = (c >= 0x20 && c <= 0x7e) ? (char)c : (c == 10 ? '|' : '.');
        }
        buf[n] = 0;
        fprintf(stderr, "  [cbuf %u] len=%u cap=%u text=\"%s\"%s\n",
                i, len, cap, buf, len > n ? " …" : "");
    }
    if (g_gsc_on && g_gsc_n) {
        unsigned have = g_gsc_n < 512u ? g_gsc_n : 512u, show = have < 48u ? have : 48u;
        fprintf(stderr, "  [gsc] last %u opcodes (op depth esi bytecodeIP), %u total:\n", show, g_gsc_n);
        // 🎯 NAME THE SCRIPT, not just the address. A ring of bare bytecode IPs
        // cannot answer "which script is running when angola freezes", which is
        // the whole question — and the resolver has existed all along
        // (win32_gsc_script_of, used by the write watch). Resolving here turns
        // 48 hex numbers into 48 answers.
        {
            extern bool win32_gsc_script_of(uint32_t, char*, size_t, uint32_t*);
            char last[128] = {0};
            unsigned distinct = 0;
            for (unsigned k = have - show; k < have; k++) {
                auto& r = g_gsc_ring[(g_gsc_n - have + k) & 511u];
                char nm[128] = {0}; uint32_t base = 0;
                const bool got = win32_gsc_script_of(r.ip, nm, sizeof nm, &base);
                fprintf(stderr, "    0x%02x depth=%-6d esi=0x%08x ip=0x%08x tos_ty=%u "
                                "tos_dat=0x%08x  %s",
                        r.op, r.depth, r.esi, r.ip, r.tos_ty, r.tos_dat,
                        got ? nm : "(script unknown)");
                if (got && base) fprintf(stderr, "+0x%x", r.ip - base);
                fprintf(stderr, "\n");
                if (got && strcmp(nm, last) != 0) { snprintf(last, sizeof last, "%s", nm); ++distinct; }
            }
            fprintf(stderr, "  [gsc] %u script transition(s) across those %u opcodes — %s\n",
                    distinct, show,
                    distinct <= 1 ? "🎯 ONE script owns the whole window: that is the one to chase"
                                  : "several scripts interleave here");
        }
    }
}

// --- Gate-A diagnostic: walk the asset DB and tally REGISTERED assets by type.
// Reverse-engineered from DB_FindXAssetEntry (0x778730) / DB_LinkXAssetEntry
// (0x7787a0): db_hashTable = 0x1047ad0 (0x7530=30000 WORD buckets, keyed by
// hash%30000); each nonzero bucket word is an index into the entry pool at
// 0x1178c50 (stride 0x10): entry[+0]=type (dword), [+4]=header ptr, [+0xa]=next
// bucket-chain index (word, 0=end). Purely read-only. This answers the Gate-A
// question directly: does the frontend zone walk ever register type 17 (gfx_map/
// GfxWorld = maps/frontend.d3dbsp) — i.e. is the menu-open GSC waiting on an asset
// that genuinely never enters the DB, vs one that registers but stalls elsewhere.
// An asset's name lives at a PER-TYPE offset inside its header, so a DB walk must
// not assume [header+0]. DB_GetXAssetName (FUN_0040ed70) tail-jumps through the
// getter table at 0xbd3d88[type]: the generic getter (0x777910) reads [header+0],
// but IMAGES (type 8, getter 0x7778f0) keep the name at [header+0x48].
// Reading offset 0 for an image yields "" — which is exactly why every image,
// including $white/$black/$blank/$gray/$identitynormalmap, was reported
// *** MISSING *** by these diagnostics for several sessions. They are in fact all
// registered (confirmed at the registrar via BO2_ADDASSET_LOG=8). Broken
// diagnostic, not a broken engine.
static uint32_t db_asset_name_ptr(uint32_t type, uint32_t hdr) {
    if (hdr <= 0x1000u) return 0;
    uint32_t getter = win32_mem_read32(0xbd3d88u + (type & 0x7fu) * 4u);
    uint32_t noff   = (getter == 0x7778f0u) ? 0x48u : 0u;
    return win32_mem_read32(hdr + noff);
}
static void db_asset_name(uint32_t type, uint32_t hdr, char* out, int cap) {
    uint32_t np = db_asset_name_ptr(type, hdr);
    int n = 0;
    if (np) while (n < cap - 1) { uint8_t c = win32_mem_read8(np + n); if (c < 0x20 || c > 0x7e) break; out[n++] = (char)c; }
    out[n] = 0;
}

void bo2_watch_img(const char* when);   // defined below (C++ linkage)

// BO2_IMAGE_DUMP=1 — walk every registered IMAGE asset (type 8) and report the
// state of its GfxImage. 1738 are registered and only five ever reach
// CreateTexture2D, so the question is what distinguishes them: the header's first
// dword is the D3D texture pointer (0 = no texture), and the bytes after the
// dimensions carry the map type / streaming flags. Counting them by "has texture"
// says whether the other 1733 are deferred (expected) or simply broken.
extern "C" void bo2_dump_images(const char* why) {
    const uint32_t HASH = 0x1047ad0u, POOL = 0x1178c50u, NBUCK = 0x7530u;
    auto rd16 = [](uint32_t a) -> uint32_t {
        return (uint32_t)win32_mem_read8(a) | ((uint32_t)win32_mem_read8(a + 1) << 8);
    };
    long n = 0, with_tex = 0, without = 0, shown = 0;
    fprintf(stderr, "[IMG-DUMP] %s\n", why);
    for (uint32_t b = 0; b < NBUCK; b++) {
        uint32_t idx = rd16(HASH + b * 2);
        int guard = 0;
        while (idx != 0 && guard++ < 200000) {
            uint32_t e = POOL + idx * 0x10u;
            uint32_t type = win32_mem_read32(e);
            uint32_t hdr  = win32_mem_read32(e + 4);
            if (type == 8u && hdr) {
                n++;
                uint32_t tex = win32_mem_read32(hdr + 0);
                if (tex) with_tex++; else without++;
                // Named images we have the FASTFILE bytes for, so runtime memory
                // can be compared against what the zone actually delivered.
                {
                    char nm2[80]; db_asset_name(type, hdr, nm2, sizeof nm2);
                    if (!strcmp(nm2, "lui_arrow") || !strcmp(nm2, "menu_mp_pip_blue") ||
                        !strcmp(nm2, "iw2_blood_reveal")) {
                        fprintf(stderr, "[IMG-CMP] %-24s runtime:", nm2);
                        for (int q = 0; q < 20; q++)
                            fprintf(stderr, " +%02x=%08x", q * 4,
                                    win32_mem_read32(hdr + (uint32_t)q * 4));
                        fprintf(stderr, "\n");
                    }
                }
                if (shown < 12) {
                    char nm[80]; db_asset_name(type, hdr, nm, sizeof nm);
                    // FUN_00704210 refuses to touch the ipak unless ALL THREE of
                    // these are non-zero, and it is the only thing standing between
                    // "image deferred" and "read its pixels":
                    //   [+0x3c] byte flag, [+0x34] top 4 bits = ipak index and low
                    //   28 bits = offset, [+0x30] size. Dump the whole streaming
                    //   descriptor, not just the head of the struct.
                    fprintf(stderr, "[IMG-DUMP]   %-40s hdr=%08x", nm, hdr);
                    for (int q = 0; q < 10; q++)
                        fprintf(stderr, " +%02x=%08x", q * 4,
                                win32_mem_read32(hdr + (uint32_t)q * 4));
                    fprintf(stderr, " | +30=%08x +34=%08x +38=%08x +3c=%08x\n",
                            win32_mem_read32(hdr + 0x30), win32_mem_read32(hdr + 0x34),
                            win32_mem_read32(hdr + 0x38), win32_mem_read32(hdr + 0x3c));
                    shown++;
                }
            }
            idx = rd16(e + 0xa);
        }
    }
    fprintf(stderr, "[IMG-DUMP] %ld images: %ld WITH a texture, %ld without\n",
            n, with_tex, without);
    // How many images carry a USABLE ipak descriptor? That count is the ceiling on
    // how many could ever stream, no matter what the rest of the pipeline does.
    {
        long ok = 0, nodesc = 0;
        for (uint32_t b2 = 0; b2 < NBUCK; b2++) {
            uint32_t idx = rd16(HASH + b2 * 2);
            int guard = 0;
            while (idx != 0 && guard++ < 200000) {
                uint32_t e = POOL + idx * 0x10u;
                if (win32_mem_read32(e) == 8u) {
                    uint32_t h = win32_mem_read32(e + 4);
                    if (h) {
                        uint32_t f3c = win32_mem_read8(h + 0x3c);
                        uint32_t f34 = win32_mem_read32(h + 0x34);
                        uint32_t f30 = win32_mem_read32(h + 0x30);
                        if (f3c && (f34 & 0x0fffffffu) && f30) ok++; else nodesc++;
                    }
                }
                idx = rd16(e + 0xa);
            }
        }
        fprintf(stderr, "[IMG-DUMP] ipak descriptor present on %ld images, MISSING on %ld\n",
                ok, nodesc);
    }
}
// ── 🎯 [CLAMP-VERDICT] — WHICH STARVED ASSETS ACTUALLY ARRIVED? ─────────────
//
// bo2_db_find removes the engine's infinite wait for every asset type outside
// the map and script families. That is right for assets which never arrive and
// WRONG for assets that were merely late — and a wrong one is invisible: the
// engine just answers "unknown <thing>" a moment before the asset lands. That is
// exactly how weapons (type 25) hid for 13 runs, until `emp_grenade_sp` was
// caught being delivered 195 log lines after the lookup that failed.
//
// So ask the question exhaustively instead of one asset at a time: every name we
// clamped is remembered, and this walks the live asset database to see which of
// them are RESIDENT now. A clamped asset that is resident was never missing — it
// was late, and its type belongs in BO2_ASSET_WAIT_TYPES.
//
// ⚠️ It prints both verdicts. "Absent" is the healthy case for a genuinely
// missing asset, and a probe that only listed the hits could not tell "the clamp
// was right" from "the walk found nothing".
std::vector<std::pair<uint32_t,std::string>> g_clamped_assets;
extern "C" void win32_clamp_verdict(const char* why) {
    if (g_clamped_assets.empty()) {
        fprintf(stderr, "[CLAMP-VERDICT] (%s) no clamps recorded — nothing to judge\n", why);
        return;
    }
    const uint32_t HASH = 0x1047ad0u, POOL = 0x1178c50u, NBUCK = 0x7530u;
    auto rd16 = [](uint32_t a) -> uint32_t {
        return (uint32_t)win32_mem_read8(a) | ((uint32_t)win32_mem_read8(a + 1) << 8);
    };
    // Build the resident set once: (type, name) for every entry in the pool.
    std::set<std::string> resident;
    long walked = 0;
    for (uint32_t b = 0; b < NBUCK; b++) {
        uint32_t idx = rd16(HASH + b * 2); int guard = 0;
        while (idx != 0 && guard++ < 200000) {
            const uint32_t e = POOL + idx * 0x10u;
            const uint32_t type = win32_mem_read32(e);
            const uint32_t hdr  = win32_mem_read32(e + 4);
            const uint32_t namep = hdr ? win32_mem_read32(hdr) : 0;
            if (namep > 0x1000u) {
                char nm[80]; int n = 0;
                while (n < 79) { uint8_t c = win32_mem_read8(namep + n);
                                 if (c < 0x20 || c > 0x7e) break; nm[n++] = (char)c; }
                nm[n] = 0;
                if (n) { char key[96]; snprintf(key, sizeof key, "%u:%s", type, nm);
                         resident.insert(key); }
            }
            ++walked;
            idx = rd16(e + 0xa);
        }
    }
    int late = 0, genuinely_absent = 0;
    std::map<uint32_t,int> late_by_type;
    fprintf(stderr, "\n[CLAMP-VERDICT] (%s) %zu clamped name(s) against %ld resident entries:\n",
            why, g_clamped_assets.size(), walked);
    for (auto& pr : g_clamped_assets) {
        char key[96]; snprintf(key, sizeof key, "%u:%s", pr.first, pr.second.c_str());
        if (resident.count(key)) {
            ++late; ++late_by_type[pr.first];
            if (late <= 40)
                fprintf(stderr, "[CLAMP-VERDICT]   🎯 LATE, NOT MISSING: type=%u \"%s\" is "
                                "RESIDENT now — its wait should not have been clamped\n",
                        pr.first, pr.second.c_str());
        } else ++genuinely_absent;
    }
    fprintf(stderr, "[CLAMP-VERDICT] %d were merely LATE, %d are genuinely absent.\n",
            late, genuinely_absent);
    if (!late_by_type.empty()) {
        fprintf(stderr, "[CLAMP-VERDICT] types to add to BO2_ASSET_WAIT_TYPES:");
        for (auto& kv : late_by_type) fprintf(stderr, " %u(x%d)", kv.first, kv.second);
        fprintf(stderr, "\n");
    }
    fprintf(stderr, "\n");
}

extern "C" void bo2_dump_asset_db(const char* why) {
    static int s_calls = 0;
    if (s_calls++ >= 3) return;              // bound the output
    bo2_watch_img(why);                      // watched-image presence at this moment
    const uint32_t HASH = 0x1047ad0u, POOL = 0x1178c50u, NBUCK = 0x7530u;
    auto rd16 = [](uint32_t a) -> uint32_t {
        return (uint32_t)win32_mem_read8(a) | ((uint32_t)win32_mem_read8(a + 1) << 8);
    };
    long counts[128]; for (int i = 0; i < 128; i++) counts[i] = 0;
    long total = 0, gfx = 0;
    for (uint32_t b = 0; b < NBUCK; b++) {
        uint32_t idx = rd16(HASH + b * 2);
        int guard = 0;
        while (idx != 0 && guard++ < 200000) {
            uint32_t e = POOL + idx * 0x10u;
            uint32_t type = win32_mem_read32(e);
            counts[type < 128u ? type : 127] += 1;
            total++;
            if (type == 17u) {               // gfx_map / GfxWorld
                gfx++;
                uint32_t hdr = win32_mem_read32(e + 4);
                uint32_t namep = win32_mem_read32(hdr);      // GfxWorld.name at +0 (best-effort)
                char nm[80]; int n = 0;
                while (n < 79) { uint8_t c = win32_mem_read8(namep + n); if (c < 0x20 || c > 0x7e) break; nm[n++] = (char)c; }
                nm[n] = 0;
                fprintf(stderr, "  [ASSET-DB gfx_map] idx=%u hdr=0x%08x name=\"%s\"\n", idx, hdr, nm);
            }
            idx = rd16(e + 0xa);
        }
    }
    fprintf(stderr, "[ASSET-DB %s] total registered=%ld  gfx_map(17)=%ld\n", why, total, gfx);
    {   // WHAT WAS EVER OFFERED to DB_AddXAsset, by type, since boot. Compare
        // against the resident counts above: a type with adds but no residents
        // was registered and evicted or rejected; a type with NO adds was never
        // presented, and the fault is upstream in the zone's asset walk.
        extern uint64_t g_addasset_by_type[64], g_addasset_total;
        fprintf(stderr, "[ADD-TALLY] DB_AddXAsset calls=%llu; by type:",
                (unsigned long long)g_addasset_total);
        for (int t = 0; t < 64; t++)
            if (g_addasset_by_type[t])
                fprintf(stderr, " %d=%llu", t, (unsigned long long)g_addasset_by_type[t]);
        fprintf(stderr, "\n");
    }
    for (int t = 0; t < 128; t++) {
        if (!counts[t]) continue;
        uint32_t np = win32_mem_read32(0xbd3c88u + (uint32_t)t * 4);   // g_assetNames[t]
        char tn[40]; int n = 0;
        while (n < 39) { uint8_t c = win32_mem_read8(np + n); if (c < 0x20 || c > 0x7e) break; tn[n++] = (char)c; }
        tn[n] = 0;
        fprintf(stderr, "    type %3d %-18s : %ld\n", t, tn, counts[t]);
    }
    // Targeted: for each asset tid0's frontend init DBWAITs on, is it registered?
    // Most T6 asset structs start with `const char* name`, so entry[+4]=header,
    // header[+0]=name works across xmodel/material/image/fx/rawfile/etc. Walk the
    // whole pool and match. A suspect that never matches = the real stall asset.
    // The campaign map's own assets come FIRST: the dump is now fired from the
    // campaign's `.gsc` wait, and the whole question at that moment is whether the
    // LEVEL SCRIPT is in the database. The gfx_map line already proves the .d3dbsp
    // is, so the level geometry is resident and only the script is unaccounted for.
    //
    // ⚠️ THE LEVEL NAME IS A VARIABLE, NOT `afghanistan`. This list was hardcoded to
    // afghanistan and that cost a whole session: afghanistan.ff is a SHARED map zone
    // (afghanistan + so_rts_afghanistan use the same geometry) and carries only 4
    // scriptparsetrees, all traversal animscripts — maps/afghanistan.gsc lives in the
    // companion zone so_cmp_afghanistan.ff (the game's own asset tally shows it);
    // angola.ff, a normal self-contained campaign zone, carries its own 61. A
    // hardcoded probe reporting "*** MISSING ***" for a level nobody is loading is
    // exactly the kind of true-but-irrelevant answer that reads as a bug.
    static char lvl[64];
    if (!lvl[0]) {
        const char* e = bo2_getenv("BO2_FORCE_MAP_NOW");
        if (!e || !*e) e = bo2_getenv("BO2_LEVEL");
        snprintf(lvl, sizeof lvl, "%s", (e && *e) ? e : "afghanistan");
    }
    static char sbuf[6][96];
    static const char* suspects[] = {
        sbuf[0], sbuf[1], sbuf[2], sbuf[3], sbuf[4], sbuf[5],
        "maps/_load.gsc",
        // 🎯 [LAST-INF-WAIT tid=0] type=48 "maps/_mortar.gsc" on the angola
        // freeze: the MAIN thread's last infinite DB_FindXAssetHeader wait names
        // this script, and angola.ff demonstrably contains it (decoded offline).
        // "last" is not "current", so ASK the registry directly rather than
        // inferring a live stall from a historical wait. Its .csc twin and two
        // more of angola's own scripts are here as controls: if _mortar is
        // missing and angola_utility is present, the failure is per-asset, not
        // per-zone.
        "maps/_mortar.gsc", "clientscripts/_mortar.csc",
        "maps/angola_utility.gsc", "maps/angola_anim.gsc",
        "maps/frontend.d3dbsp", "maps/frontend.gsc", "maps/createart/frontend_art.gsc",
        "maps/voice/voice_frontend.gsc", "car_sp", "inigun_enemy_pilot",
        "scar_rangefinder_gl", "scavenger_item_sp", "concussion_grenade_mp.shock",
        "$white", "$black", "$blank", "$gray", "$identitynormalmap", "streaming_temp_image_0",
    };
    snprintf(sbuf[0], sizeof sbuf[0], "maps/%s.gsc", lvl);
    snprintf(sbuf[1], sizeof sbuf[1], "maps/%s.d3dbsp", lvl);
    snprintf(sbuf[2], sizeof sbuf[2], "maps/createart/%s_art.gsc", lvl);
    snprintf(sbuf[3], sizeof sbuf[3], "maps/%s_fx.gsc", lvl);
    snprintf(sbuf[4], sizeof sbuf[4], "clientscripts/%s.csc", lvl);
    snprintf(sbuf[5], sizeof sbuf[5], "maps/voice/voice_%s.gsc", lvl);
    const int NS = (int)(sizeof(suspects) / sizeof(suspects[0]));
    int found_type[NS]; for (int i = 0; i < NS; i++) found_type[i] = -1;
    for (uint32_t b = 0; b < NBUCK; b++) {
        uint32_t idx = rd16(HASH + b * 2);
        int guard = 0;
        while (idx != 0 && guard++ < 200000) {
            uint32_t e = POOL + idx * 0x10u;
            uint32_t type = win32_mem_read32(e);
            char nm[96]; db_asset_name(type, win32_mem_read32(e + 4), nm, sizeof nm);
            for (int i = 0; i < NS; i++)
                if (found_type[i] < 0) { const char* s = suspects[i]; int k = 0; while (s[k] && nm[k] == s[k]) k++; if (!s[k] && !nm[k]) found_type[i] = (int)type; }
            idx = rd16(e + 0xa);
        }
    }
    for (int i = 0; i < NS; i++)
        fprintf(stderr, "    [SUSPECT] %-34s : %s\n", suspects[i],
                found_type[i] >= 0 ? "REGISTERED" : "*** MISSING ***");
    // 🎯 WHICH scriptparsetrees DID register? 287 are in the table while all five
    // of the level's are missing, so this is not a wholesale skip of script assets
    // — it is specific to the level zone. Listing the registered names says at
    // once whether ANY level-specific script made it in.
    {
        int shown = 0, total48 = 0;
        for (uint32_t b = 0; b < NBUCK; b++) {
            uint32_t idx = rd16(HASH + b * 2);
            int guard = 0;
            while (idx != 0 && guard++ < 200000) {
                uint32_t e = POOL + idx * 0x10u;
                if (win32_mem_read32(e) == 48u) {
                    ++total48;
                    if (shown < 20) {
                        char nm2[96];
                        db_asset_name(48u, win32_mem_read32(e + 4), nm2, sizeof nm2);
                        if (strstr(nm2, "maps/") || strstr(nm2, "clientscripts/")) {
                            fprintf(stderr, "    [SPT] %s\n", nm2);
                            ++shown;
                        }
                    }
                }
                idx = rd16(e + 0xa);
            }
        }
        fprintf(stderr, "    [SPT] %d scriptparsetree assets registered in total\n", total48);
    }
    // Per-thread last INFINITE DB_FindXAssetHeader wait — a thread stuck here has
    // its blocker named (the wait's real body never returned).
    extern char g_db_last_inf[16][64]; extern uint32_t g_db_last_inf_type[16];
    for (int t = 0; t < 16; t++)
        if (g_db_last_inf[t][0])
            fprintf(stderr, "    [LAST-INF-WAIT tid=%d] type=%u \"%s\"\n", t, g_db_last_inf_type[t], g_db_last_inf[t]);
    // BO2_DUMP_DEFAULTED=1 — find every asset that is really a DEFAULTED STUB.
    // DB_FindXAssetHeader's give-up path registers g_defaultAssetName[type] (@0xbd47a8)
    // under the requested name, so such an entry's HEADER POINTER is literally the same
    // object as its type's default asset. That makes defaulted stubs detectable
    // generically: pass 1 records each type's default header, pass 2 flags every entry
    // sharing it. This is the full blast radius of the bo2_db_find timeout clamp — the
    // bug that produced the 7 bogus scriptparsetree stubs (fixed for type 48, but every
    // still-clamped type can be silently poisoned the same way).
    if (bo2_getenv("BO2_DUMP_DEFAULTED")) {
        uint32_t defhdr[128]; char defname[128][64];
        for (int t = 0; t < 128; t++) { defhdr[t] = 0; defname[t][0] = 0; }
        for (int t = 0; t < 128; t++) {
            uint32_t np = win32_mem_read32(0xbd47a8u + (uint32_t)t * 4);
            if (!np) continue;
            int n = 0;
            while (n < 63) { uint8_t c = win32_mem_read8(np + n); if (c < 0x20 || c > 0x7e) break; defname[t][n++] = (char)c; }
            defname[t][n] = 0;
        }
        // pass 1: locate each type's default asset entry and remember its header
        for (uint32_t b = 0; b < NBUCK; b++) {
            uint32_t idx = rd16(HASH + b * 2); int guard = 0;
            while (idx != 0 && guard++ < 200000) {
                uint32_t e = POOL + idx * 0x10u;
                uint32_t t = win32_mem_read32(e);
                if (t < 128u && defname[t][0]) {
                    uint32_t hdr = win32_mem_read32(e + 4);
                    char nm[96]; db_asset_name(t, hdr, nm, sizeof nm);
                    if (!std::strcmp(nm, defname[t])) defhdr[t] = hdr;
                }
                idx = rd16(e + 0xa);
            }
        }
        // pass 2: the give-up allocates a NEW header carrying the REQUESTED name but the
        // DEFAULT's payload (verified on scriptparsetree: war_room_util got its own
        // hdr 0x01339b78 with common_scripts/default's len=87 + buffer). So fingerprint
        // the payload — an entry whose hdr[+4]/hdr[+8] match the default's, while its
        // name differs, is a defaulted stub.
        long stubs = 0; long percount[128]; for (int i = 0; i < 128; i++) percount[i] = 0;
        for (uint32_t b = 0; b < NBUCK; b++) {
            uint32_t idx = rd16(HASH + b * 2); int guard = 0;
            while (idx != 0 && guard++ < 200000) {
                uint32_t e = POOL + idx * 0x10u;
                uint32_t t = win32_mem_read32(e);
                uint32_t hdr = win32_mem_read32(e + 4);
                if (t < 128u && defhdr[t] && hdr) {
                    uint32_t a1 = win32_mem_read32(defhdr[t] + 4), a2 = win32_mem_read32(defhdr[t] + 8);
                    if ((a1 || a2) && win32_mem_read32(hdr + 4) == a1 && win32_mem_read32(hdr + 8) == a2) {
                        char nm[96]; db_asset_name(t, hdr, nm, sizeof nm);
                        if (std::strcmp(nm, defname[t])) {     // the default itself is legit
                            percount[t]++; stubs++;
                            if (stubs <= 120)
                                fprintf(stderr, "    [DEFAULTED type %u] \"%s\" -> default \"%s\" (hdr=0x%08x)\n",
                                        t, nm, defname[t], hdr);
                        }
                    }
                }
                idx = rd16(e + 0xa);
            }
        }
        fprintf(stderr, "[DEFAULTED-SCAN] %ld entries point at their type's default asset\n", stubs);
        for (int t = 0; t < 128; t++)
            if (percount[t] > 1)
                fprintf(stderr, "    type %3d default=\"%s\" : %ld entries share it\n", t, defname[t], percount[t]);
    }
    // BO2_DUMP_TYPE=<n>[:substr] — list all registered names of asset type <n>
    // (optionally filtered). Used to see if a frontend/holo scriptparsetree (type 48)
    // that should define holo_table_feature_prop is even loaded.
    if (const char* dt = bo2_getenv("BO2_DUMP_TYPE")) {
        int want = atoi(dt); const char* filt = strchr(dt, ':'); filt = filt ? filt + 1 : "";
        int shown = 0;
        for (uint32_t b = 0; b < NBUCK && shown < 300; b++) {
            uint32_t idx = rd16(HASH + b * 2); int guard = 0;
            while (idx != 0 && guard++ < 200000) {
                uint32_t e = POOL + idx * 0x10u;
                if ((int)win32_mem_read32(e) == want) {
                    uint32_t hdr = win32_mem_read32(e + 4);
                    char nm[96]; db_asset_name((uint32_t)want, hdr, nm, sizeof nm);
                    if (!*filt || std::strstr(nm, filt)) {
                        // scriptparsetree (type 48) is { const char* name; int len; byte* buffer; }
                        // (0xc stride). Print the BUFFER ptr + the name embedded INSIDE the
                        // buffer (buffer + word[buffer+0x30]) — if the embedded name differs
                        // from the asset name, this asset's buffer pointer is mis-fixed-up
                        // (aliased to another script), which is what breaks GSC import linking.
                        if (want == 48) {
                            uint32_t len = win32_mem_read32(hdr + 4), buf = win32_mem_read32(hdr + 8);
                            char bn[96]; bn[0] = 0; uint32_t magic = 0;
                            if (buf > 0x1000u) {
                                magic = win32_mem_read32(buf);
                                uint32_t noff = (uint32_t)win32_mem_read8(buf + 0x30) |
                                                ((uint32_t)win32_mem_read8(buf + 0x31) << 8);
                                int k = 0; uint32_t bp = buf + noff;
                                while (k < 95) { uint8_t c = win32_mem_read8(bp + k); if (c < 0x20 || c > 0x7e) break; bn[k++] = (char)c; }
                                bn[k] = 0;
                            }
                            fprintf(stderr, "    [TYPE 48] \"%s\" hdr=0x%08x len=%u buf=0x%08x magic=0x%08x embedded=\"%s\"%s\n",
                                    nm, hdr, len, buf, magic, bn,
                                    std::strncmp(nm, bn, std::strlen(bn) ? std::strlen(bn) : 1) ? "  <== MISMATCH" : "");
                            // Same-name assets from different zones are kept in a
                            // PRIORITY-SORTED VARIANT CHAIN at word[entry+0xc] (built by
                            // FUN_00778a70's replace path, ordered by FUN_0065f250(zone)).
                            // DB_FindXAssetHeader only ever returns the HEAD — so if the
                            // real definition lost the priority comparison it is still
                            // registered here, just behind the stub. Walk it.
                            uint32_t vi = rd16(e + 0xc); int vg = 0;
                            while (vi != 0 && vg++ < 32) {
                                uint32_t ve = POOL + vi * 0x10u;
                                uint32_t vh = win32_mem_read32(ve + 4);
                                uint32_t vlen = win32_mem_read32(vh + 4), vbuf = win32_mem_read32(vh + 8);
                                char vn[96]; int q = 0; uint32_t vnp = win32_mem_read32(vh);
                                while (q < 95) { uint8_t c = win32_mem_read8(vnp + q); if (c < 0x20 || c > 0x7e) break; vn[q++] = (char)c; }
                                vn[q] = 0;
                                char vb[96]; vb[0] = 0;
                                if (vbuf > 0x1000u) {
                                    uint32_t vo = (uint32_t)win32_mem_read8(vbuf + 0x30) |
                                                  ((uint32_t)win32_mem_read8(vbuf + 0x31) << 8);
                                    int k2 = 0; uint32_t bp2 = vbuf + vo;
                                    while (k2 < 95) { uint8_t c = win32_mem_read8(bp2 + k2); if (c < 0x20 || c > 0x7e) break; vb[k2++] = (char)c; }
                                    vb[k2] = 0;
                                }
                                fprintf(stderr, "        [variant %d] zone=%u \"%s\" hdr=0x%08x len=%u buf=0x%08x embedded=\"%s\"\n",
                                        vg, (uint32_t)win32_mem_read8(ve + 8), vn, vh, vlen, vbuf, vb);
                                vi = rd16(ve + 0xc);
                            }
                        } else {
                            fprintf(stderr, "    [TYPE %d] \"%s\"\n", want, nm);
                        }
                        shown++;
                    }
                }
                idx = rd16(e + 0xa);
            }
        }
        fprintf(stderr, "    [TYPE %d] shown %d (filter=\"%s\")\n", want, shown, filt);
    }
}

// --- native crash handler ---------------------------------------------------
// A guest fault (bad g_mem write) OR a host stack overflow surfaces as SIGSEGV/
// SIGBUS. Without a handler the process just dies with no [CRASH] marker, so the
// crumb/GSC rings — which hold the exact dispatch cycle that led here — were
// invisible. Install a handler on an ALTERNATE signal stack (mandatory: a
// stack-overflow SIGSEGV cannot run the handler on the exhausted main stack),
// dump the rings + fault address, then _exit. si_addr near a thread stack top
// (0x16xxxxxxx on arm64 macOS) = host stack overflow (runaway host recursion);
// a low/guest-shaped address = a bad guest memory access.
extern "C" void win32_gsc_dump_ring();
extern "C" int win32_current_tid();
static void bo2_crash_handler(int sig, siginfo_t* si, void* ctx) {
    void* fault = si ? si->si_addr : nullptr;
    // approximate this frame's SP to classify overflow vs wild pointer
    void* sp; __asm__ volatile("mov %0, sp" : "=r"(sp));
    fprintf(stderr,
            "\n[CRASH] signal=%d (%s) fault_addr=%p handler_sp=%p tid=%d\n"
            "  (fault_addr in 0x16xxxxxxxx range ⇒ HOST STACK OVERFLOW / runaway host recursion;\n"
            "   low or guest-shaped ⇒ bad guest memory access)\n",
            sig, sig == SIGSEGV ? "SIGSEGV" : sig == SIGBUS ? "SIGBUS" : "?",
            fault, sp, win32_current_tid());
    // 🎯 La traduction hote -> invite est faite ICI, par le code qui CONNAIT la
    // base, au lieu d'etre refaite a la main a chaque lecture de journal. Elle
    // dit aussi si l'adresse invitee est alignee : sur ARM64 un acces atomique
    // non aligne donne SIGBUS la ou x86 l'accepte, donc c'est une hypothese
    // qu'il faut pouvoir ecarter ou retenir SANS deviner. (Deux echantillons
    // 4-alignes non-8-alignes ne prouvent rien : c'est 25 % par hasard.)
    if (bo2_g_base) {
        const uint64_t gbase = (uint64_t)bo2_g_base;
        const uint64_t f = (uint64_t)fault;
        if (f >= gbase && f < gbase + (1ull << 32) + (1ull << 16)) {
            const uint32_t g = (uint32_t)(f - gbase);
            fprintf(stderr,
                    "  -> DANS LA CARTE INVITEE : invite=0x%08x "
                    "(aligne4=%s aligne8=%s) base=%p\n",
                    g, (g & 3u) ? "non" : "oui", (g & 7u) ? "non" : "oui",
                    (void*)gbase);
        } else {
            fprintf(stderr, "  -> HORS de la carte invitee (base=%p)\n",
                    (void*)gbase);
        }
    }
    // Registres a la faute (Z-NATIF-18d). pc == fault_addr : c'est un SAUT vers une adresse folle (pointeur de fonction
    // ou adresse de retour ecrases) et la pile d'appels ci-dessous ne nomme que lr ; sinon pc est l'instruction fautive.
    if (ucontext_t* uc = (ucontext_t*)ctx; BO2_UC_HAS_MCONTEXT(uc)) {
        void* ou[2] = { (void*)BO2_UC_PC(uc), (void*)BO2_UC_LR(uc) };
        fprintf(stderr, "  [regs] pc=%p lr=%p sp=%#llx fp=%#llx\n", ou[0], ou[1],
                (unsigned long long)BO2_UC_SP(uc), (unsigned long long)BO2_UC_FP(uc));
        for (int i = 0; i < 28; i += 4)
            fprintf(stderr, "  [regs] x%-2d=%#018llx x%-2d=%#018llx x%-2d=%#018llx x%-2d=%#018llx\n",
                    i, (unsigned long long)BO2_UC_X(uc, i), i + 1, (unsigned long long)BO2_UC_X(uc, i + 1),
                    i + 2, (unsigned long long)BO2_UC_X(uc, i + 2), i + 3, (unsigned long long)BO2_UC_X(uc, i + 3));
        fflush(stderr);
        backtrace_symbols_fd(ou, 2, 2);
    }
    // 🎯 THE HOST BACKTRACE. Without it a [CRASH] names the guest VA that was
    // running and nothing about WHICH SHIM FUNCTION dereferenced the bad pointer —
    // and a fault_addr like 0x17c is by definition a HOST null-struct deref, so
    // the guest crumbs cannot name it at all. `backtrace` + `backtrace_symbols_fd`
    // are the async-signal-safe pair (backtrace_symbols, which mallocs, is not);
    // fd 2 is stderr, which is where every other dump goes.
    {
        void* bt[64];
        const int n = backtrace(bt, 64);
        fprintf(stderr, "  [host backtrace] %d frames:\n", n);
        fflush(stderr);
        backtrace_symbols_fd(bt, n, 2);
    }
    win32_dump_crumbs(128);
    win32_gsc_dump_ring();
    fflush(stderr);
    _exit(139);
}
// SIGUSR2 -> dump the GSC opcode ring ON DEMAND. The existing dumps fire only on
// a STALL ([GSC-STOPPED]) or a crash, and the campaign's opcode count climbs
// steadily — so neither ever fires and the one instrument that can say WHERE a
// running script spends its time was unreachable. A script looping in a `wait`
// shows as a short cycle of repeating bytecode IPs; a script making progress
// shows as IPs that keep moving.
extern "C" void bo2_vm_dump_callers();
static void bo2_gsc_ring_signal(int) { win32_gsc_dump_ring(); bo2_vm_dump_callers(); }

// SIGHUP -> the DEADLOCK PICTURE, on demand: every thread's stack, the event
// table, and the asset database, at the instant you ask for it.
//
// WHY A THIRD SIGNAL. The two dumps that can name a mutual wait —
// win32_dump_events() and win32_dump_all_threads() — existed but were reachable
// only from [RUNAWAY] and [HARDCAP], and both of those key on "no new frame" /
// "too many imports". The stall that matters now presents frames the whole time
// (32,724 draws while angola.ff sat at 6 of 8,744 chunks), so neither ever fires
// and the instruments stay unreachable exactly when they are needed. A stall you
// can see in the harness log but cannot interrogate costs a whole run per guess.
//
//     kill -HUP <pid>     # while it is stuck
//
// It does NOT abort: the process keeps running, so several dumps can be taken a
// few seconds apart and compared — a wait that is genuinely dead looks identical
// across them, a slow one does not. That comparison is the point; a single
// snapshot cannot tell "blocked forever" from "blocked right now".
extern "C" void win32_dump_events();
extern "C" void win32_dump_all_threads();
volatile sig_atomic_t g_deadlock_req = 0;
// The handler does ONE async-signal-safe thing: raise a flag. The dump itself runs
// from the import probe (win32_note_import), i.e. on the scheduler thread between
// guest imports, where the thread table and the asset DB are not mid-mutation.
static void bo2_deadlock_signal(int) { g_deadlock_req = 1; }
void bo2_deadlock_dump() {
    fprintf(stderr, "\n=== [DEADLOCK-DUMP] requested by SIGHUP ===\n");
    // THE PARK/RESUME RENDEZVOUS that strands tid 2 on the angola load.
    //   0x40bdd0  SetEvent(0x1000e) ; SetEvent(0x1000f) ; WFSO(0x10010, INFINITE)
    //             then ResetEvent on both — i.e. "flag that I am parked, block".
    //   0x80d320  if ([0x29239a0] == 0) { [esi+0x30]=[esi+0x34]=esi;
    //                                     [0x29239a0]=esi; SetEvent(0x10010);
    //                                     [0x29239a8]++ }
    //             else jump 0x80d341 and DO NOT release.
    // So the release is GUARDED, and whether that guard is the reason tid 2 never
    // wakes is one dword. Print it rather than reason about it: [0x29239a0] is the
    // guard, [0x29239a8] counts releases actually issued, and both are cheap.
    // Callers of the releaser are 0x576c07 and 0x5883f3; 0x484e10 is
    // `WaitForSingleObject([0x1000f], 1) -> bool`, i.e. someone POLLS the parked
    // flag rather than waiting on it, which is why SetEvent on 0x1000e/0x1000f
    // reports woke=0 and that woke=0 is NOT itself the bug.
    fprintf(stderr, "[DEADLOCK-DUMP] park/resume: guard[0x29239a0]=0x%08x "
                    "releases[0x29239a8]=%u  [0x29239a4]=0x%08x\n",
            win32_mem_read32(0x29239a0u), win32_mem_read32(0x29239a8u),
            win32_mem_read32(0x29239a4u));
    win32_dump_events();
    win32_dump_all_threads();
    extern void bo2_dump_asset_db(const char*);
    bo2_dump_asset_db("sighup");
}

extern "C" void win32_install_crash_handler() {
    { struct sigaction sa; memset(&sa, 0, sizeof sa);
      sa.sa_handler = bo2_gsc_ring_signal; sigemptyset(&sa.sa_mask);
      sigaction(SIGUSR2, &sa, nullptr); }
    { struct sigaction sa; memset(&sa, 0, sizeof sa);
      sa.sa_handler = bo2_deadlock_signal; sigemptyset(&sa.sa_mask);
      sigaction(SIGHUP, &sa, nullptr); }
    // sigaltstack is PER-THREAD — a stack-overflow SIGSEGV runs the handler on
    // this stack, so it must be set on whichever host thread actually runs guest
    // code (the big-stack scheduler thread), not just the process main thread.
    // thread_local gives each host thread its own altstack; call once per thread.
#if defined(__GLIBC__)   // glibc 2.34+: SIGSTKSZ is sysconf(_SC_SIGSTKSZ), not a constant
    static thread_local char altstack[4 * 65536];
#else
    static thread_local char altstack[SIGSTKSZ * 4];
#endif
    static thread_local bool alt_done = false;
    if (!alt_done) {
        alt_done = true;
        stack_t ss{}; ss.ss_sp = altstack; ss.ss_size = sizeof(altstack); ss.ss_flags = 0;
        sigaltstack(&ss, nullptr);
    }
    // sigaction is process-wide — arm it exactly once.
    static bool sa_done = false;
    if (!sa_done) {
        sa_done = true;
        struct sigaction sa{};
        sa.sa_sigaction = bo2_crash_handler;
        sa.sa_flags = SA_SIGINFO | SA_ONSTACK;
        sigemptyset(&sa.sa_mask);
        sigaction(SIGSEGV, &sa, nullptr);
        sigaction(SIGBUS, &sa, nullptr);
        fprintf(stderr, "[CRASH] handler armed (altstack %zu KB, per-thread)\n", sizeof(altstack) / 1024);
    }
}

// One-time: force the frontend GUMP content zone to load. The scene script
// maps/frontend_sf_a.gsc is in frontend.ff (loaded) but its CONTENT zone
// frontend_gump_sf_a.ff (holo_table_feature_prop's definer + the SP models
// car_sp/inigun_enemy_pilot/… + textures) is never requested: it loads via the
// restore_gump_name dvar (ptr @0x1177e44) which the frame loop reads each frame
// and, if non-empty, executes "loadGump <name>". On a fresh boot with no campaign
// save the dvar is "" → no gump. Set the dvar's string value ([dvar+0x18], per
// Dvar_GetString 0x60fe70) directly so the game's own loader opens the zone.
// Gated: default ON; BO2_GUMP="" disables; BO2_GUMP=<name> overrides the name.
// BO2_GUMP_CALL=<name> — call the engine's own DB_LoadGump directly.
// FUN_00467760(const char* gumpName, int async): rejects NULL/empty, then logs
// "DB_LoadGump %s %s" with "sync"/"async" (0xa8a8ac / 0xabc9d0). Setting the
// restore_gump_name dvar was measured NOT to trigger a load at any frame (1 or
// 250) — the gump is savegame-driven ("G_LoadMainState send loadgump cmd %s",
// "G_LoadMainState no gump has been saved"), so on a fresh boot with no campaign
// save nothing ever asks for it. Calling the loader is the way to find out
// whether the frontend's 3D backdrop is simply a zone we never load.
extern "C" bool win32_run_lifted(State*, uint32_t);
static void bo2_gump_call_once(State& st) {
    static bool done = false;
    // P653 : lu une fois. Ce crochet tourne a chaque bo2_remill_call_inner.
    static const char* const gn = bo2_getenv("BO2_GUMP_CALL");
    if (done || !gn || !*gn) return;
    extern uint32_t g_present_frames;
    static uint32_t at = [] { const char* e = bo2_getenv("BO2_GUMP_FRAME");
                              return e ? (uint32_t)strtoul(e, nullptr, 0) : 400u; }();
    if (g_present_frames < at) return;
    done = true;
    const uint32_t scratch = 0x30001000u;
    int i = 0; for (; gn[i]; i++) win32_mem_write8(scratch + (uint32_t)i, (uint8_t)gn[i]);
    win32_mem_write8(scratch + (uint32_t)i, 0);
    uint32_t save_esp = st.gpr.rsp.dword, save_eax = st.gpr.rax.dword;
    uint32_t sp = save_esp;
    // BO2_GUMP_ASYNC=1 posts the request instead of blocking. Measured: the SYNC
    // call NEVER RETURNS — the guest thread sits inside DB_LoadGump waiting for a
    // zone the streaming path never delivers, and the game drops to a 3-draw
    // loading screen for the rest of the run. So sync is not a viable shortcut.
    sp -= 4; win32_mem_write32(sp, bo2_getenv("BO2_GUMP_ASYNC") ? 1u : 0u);
    sp -= 4; win32_mem_write32(sp, scratch);      // gump name
    sp -= 4; win32_mem_write32(sp, 0xDEAD0001u);  // return sentinel
    st.gpr.rsp.dword = sp;
    fprintf(stderr, "[GUMP-CALL] DB_LoadGump(\"%s\", %s) at frame %u\n", gn,
            bo2_getenv("BO2_GUMP_ASYNC") ? "async" : "sync", g_present_frames);
    bool ok = win32_run_lifted(&st, 0x467760u);
    st.gpr.rsp.dword = save_esp; st.gpr.rax.dword = save_eax;
    fprintf(stderr, "[GUMP-CALL] returned ok=%d\n", (int)ok);
}

static void bo2_force_gump_once() {
    static bool done = false;
    if (done) return;
    // Wait until the base frontend has initialized (frames presenting) so the zone
    // system is ready — setting it during early base-zone load spins the parser.
    extern uint32_t g_present_frames;
    static uint32_t s_at = [] { const char* e = bo2_getenv("BO2_GUMP_FRAME"); return e ? (uint32_t)strtoul(e, nullptr, 0) : 250u; }();
    if (g_present_frames < s_at) return;
    uint32_t dvar = win32_mem_read32(0x1177e44);
    if (dvar < 0x1000u || dvar >= 0xF0000000u) return;   // dvar not registered yet
    const char* gn = bo2_getenv("BO2_GUMP");   // OFF unless explicitly set (timing unsolved)
    if (!gn || !*gn) { done = true; return; }
    done = true;
    const uint32_t scratch = 0x30000000u;
    int i = 0; for (; gn[i]; i++) win32_mem_write8(scratch + i, (uint8_t)gn[i]);
    win32_mem_write8(scratch + i, 0);
    win32_mem_write32(dvar + 0x18, scratch);
    fprintf(stderr, "[GUMP] set restore_gump_name=\"%s\" at frame %u (dvar=0x%08x)\n", gn, g_present_frames, dvar);
}


