static const size_t kWatchedVaN = sizeof kWatchedVa / sizeof kWatchedVa[0];
static uint16_t g_wva_slot[1024];            // index+1 dans kWatchedVa, 0 = vide
// Familles rares tracees SANS plafond global (plafond par entree, 40) : sans
// ca les 400 lignes partagees sont mangees par setgoalvolume/animscripted et
// la sequence d'arme s'arrete au milieu du run.
static uint8_t  g_wva_trace[1024];
static uint16_t g_wva_tn[1024];
static uint64_t g_wva_hits[kWatchedVaN];
static const struct WatchedVaInit {
    WatchedVaInit() {
        static const char* kFam[] = { "weapon", "viewmodel", "lowready",
                                      "path", "speed", "vehicle" };
        for (uint16_t i = 0; i < (uint16_t)kWatchedVaN; ++i) {
            const uint32_t sl = (kWatchedVa[i].va >> 4) & 1023u;
            g_wva_slot[sl] = (uint16_t)(i + 1);
            for (const char* f : kFam)
                if (strstr(kWatchedVa[i].name, f)) { g_wva_trace[sl] = 1; break; }
        }
    }
} g_wva_init;
static void win32_watched_va_report(void) {
    char line[1400]; int n = 0; line[0] = 0;
    for (size_t i = 0; i < kWatchedVaN; ++i)
        cat(line, (int)sizeof line, n, " %s=%llu", kWatchedVa[i].name,
            (unsigned long long)g_wva_hits[i]);
    fprintf(stderr, "[BUILTIN]%s\n", line);
}

uint64_t g_thunk_calls = 0;
extern "C" void win32_coop_yield();
static int g_call_log_count = 0;   // [CFN] : les 200 premiers appels indirects (C52 les laisse a l'entree complete)
static void* bo2_remill_call_inner(State& state, uint32_t addr, void* mem) {
    crumb_and_check(state, 'C', addr);
    {
        const uint16_t w = g_wva_slot[(addr >> 4) & 1023u];
        if (__builtin_expect(w != 0, 0) && kWatchedVa[w - 1].va == addr) {
            ++g_wva_hits[w - 1];
            // 🎯 LA SEQUENCE, PAS SEULEMENT LE TOTAL.
            // Les compteurs de w47 disent que ces builtins ne tirent qu'une
            // vingtaine de fois dans tout un run : une trace complete coute
            // donc une trentaine de lignes, et elle donne ce que le total ne
            // donne pas — l'ORDRE, l'ENTITE visee, et l'etat du champ d'armes
            // juste avant l'appel. C'est ce qui separe « le script range
            // l'arme puis la ressort » de « il la range et ne la ressort
            // jamais », qui est ce que la correlation du recensement 21
            // laisse penser (hideviewmodel 0->2 et disableweaponfire 0->2
            // dans le meme pas ou [client+0x10] passe a zero).
            // Le premier argument d'un builtin de methode est le numero
            // d'entite : `mov eax,[esp+4] ; movzx eax,ax ; imul eax,0x370`
            // dans enableweapons (0x7b284e) comme dans hideviewmodel.
            static uint32_t n_tr = 0;
            const uint32_t sl_tr = (addr >> 4) & 1023u;
            const bool rare = g_wva_trace[sl_tr] && g_wva_tn[sl_tr] < 40u;
            if (rare) ++g_wva_tn[sl_tr];
            if (n_tr++ < 400u || rare) {
                const uint32_t a0 = win32_mem_read32(state.gpr.rsp.dword + 4u);
                const uint32_t cl = win32_mem_read32(0x01e033d0u);
                fprintf(stderr, "[BI-TRACE #%u] %-22s ent=%u  [client+0x10]=0x%08x"
                                "  (avant l'appel)\n",
                        n_tr, kWatchedVa[w - 1].name, a0 & 0xffffu,
                        cl ? win32_mem_read32(cl + 0x10u) : 0u);
                // La pile INVITEE au premier rangement d'arme : c'est elle qui
                // nomme la chaine d'appel du script qui decide de la cacher.
                static bool told = false;
                if (!told && (addr == 0x7b0a20u || addr == 0x7b2910u)) {
                    told = true;
                    bo2_gstack_current("le script range l'arme du joueur");
                }
            }
        }
    }
    // 🎯 WHICH BRANCH DOES THE FAULTING BUILTIN TAKE? 0x007cf770 is the builtin
    // opcode 0x29 calls at the first operand-stack underflow. It has two exits:
    //   0x5f7af0  the RESULT path — this is what updates [0x2f3b8d8], i.e. the push
    //   0x4e6870  the ERROR path  — formats a message and returns, pushing nothing
    // A builtin that takes the error path leaves the stack one slot short, which
    // is exactly the deficit measured. Counting the three is enough to say which,
    // and costs three compares on a path that already does a crumb.
    if (__builtin_expect(addr == 0x7cf770u || addr == 0x5f7af0u || addr == 0x4e6870u, 0)) {
        static uint64_t n_bi, n_res, n_err;
        if (addr == 0x7cf770u) n_bi++;
        else if (addr == 0x5f7af0u) n_res++;
        else n_err++;
        static uint64_t last;
        if (n_bi && n_bi != last) {                    // one line per builtin call
            last = n_bi;
            fprintf(stderr, "[BI-7cf770] call #%llu  (result-path 0x5f7af0 so far=%llu, "
                            "error-path 0x4e6870 so far=%llu) tid=%d\n",
                    (unsigned long long)n_bi, (unsigned long long)n_res,
                    (unsigned long long)n_err, win32_current_tid());
        }
    }
    bo2_gump_call_once(state);
    // ── `call $+5`: A PC-RELATIVE THUNK, NOT A CALL ─────────────────────────
    // `call <next instruction>` exists only to push the current address so the
    // following `pop reg` can read it — MSVC's position-independent idiom, and
    // the audio DSP uses it in all four of its computed-jump setups:
    //     lea edx,[eax*9+0x12b] ; call $+5 ; pop eax ; add edx,eax ; jmp edx
    // Dispatching it as a real call executes the body TWICE: once as the
    // "callee" (which pops the return address and runs on to the function's
    // ret) and once more when this intrinsic returns to the caller's
    // fallthrough — with a stack that the callee has already unwound. That is
    // exactly what kills the sound-decode thread: `jmp edx` with edx holding a
    // guest heap address (0x4a4221f1, 0x4a418d31, 0x50b0eda8 across runs).
    // The target IS the pushed return address, which no genuine call can be, so
    // the test is exact: push already done by the lifted code, nothing to
    // dispatch, just carry on.
    if (addr == win32_mem_read32(state.gpr.rsp.dword)) {
        g_thunk_calls++;
        return mem;
    }
    bo2_force_gump_once();
    // Fastfile slot-IO completion callback (0x777b70): log its args before it
    // clears the slot's pending flag — the ring tracer needs the ordering.
    if (addr == 0x777b70u && ring2_trace_on()) {
        uint32_t esp = state.gpr.rsp.dword;
        fprintf(stderr, "[RING2-CB] status=%u bytes=0x%x slot=%u tid=%d\n",
                win32_mem_read32(esp + 8), win32_mem_read32(esp + 0xc),
                win32_mem_read32(esp + 0x10), win32_current_tid());
    }
    // Steam interface method? (fake vtable sentinel 0xE7iissss)
    if ((addr >> 24) == 0xE7u && steam_vtbl_dispatch(state, addr)) return mem;   // 0xE7xxxxxx seulement
    // D3D11/DXGI COM method? (fake vtable sentinel 0xE6iissss)
    if ((addr >> 24) == 0xE6u && d3d_vtbl_dispatch(state, addr)) return mem;     // 0xE6xxxxxx seulement
    // DirectSound method? (fake vtable sentinel 0xE5iissss, BO2_DSOUND=1)
    // XAudio2 first: it shares the 0xE5 sentinel space and owns iface >= 5.
    if (xaudio_vtbl_dispatch(state, addr)) return mem;
    if (dsound_vtbl_dispatch(state, addr)) return mem;
    // check if it's an IAT sentinel (we wrote iat_va as the sentinel)
    if (iat_peut_etre(addr)) {   // C32
        auto it = g_import_dispatch.find(addr);
        if (it != g_import_dispatch.end()) {
            win32_dispatch_import(state, addr);
            return mem;
        }
    }
    // check if it's a dynamically-resolved function (GetProcAddress sentinel)
    if (win32_dispatch_dyn(addr, &state)) return mem;
    // [LUA-ALLOC] — every call to the frontend Lua state's own allocator, with
    // the requested size and what it returned. l_alloc(ud, ptr, osize, nsize):
    // args at [esp+4..0x10]; nsize==0 is a free. Only armed once the console has
    // learned the pointer, so a normal run prints nothing. Reports FAILURES
    // unconditionally and successes as a running total — "LUI: Out of memory"
    // is this returning 0, and the number that matters is which size it refused.
    // The one-shot reader (see g_bo2_lua_reader_buf). 0x622730 is the engine's
    // streamed-file reader and 0x5f48c0 the ZIO fill that wraps it; both are
    // (L, ud, size_t* out) and both are reached INDIRECTLY, so this dispatcher
    // is the right place. Serve the whole buffer once, EOF after — and only
    // while our own load is in flight, so nothing else in the game is touched.
    {
        extern uint32_t g_bo2_lua_reader_buf, g_bo2_lua_reader_len;
        extern bool g_bo2_lua_loading, g_bo2_lua_reader_done;
        if (g_bo2_lua_loading && (addr == 0x622730u || addr == 0x5f48c0u)) {
            const uint32_t esp = state.gpr.rsp.dword;
            const uint32_t outsz = win32_mem_read32(esp + 0xc);       // arg2
            if (!g_bo2_lua_reader_done) {
                g_bo2_lua_reader_done = true;
                if (outsz) win32_mem_write32(outsz, g_bo2_lua_reader_len);
                state.gpr.rax.dword = g_bo2_lua_reader_buf;
                fprintf(stderr, "[BO2-LUA] reader: served %u bytes once (via 0x%x)\n",
                        g_bo2_lua_reader_len, addr);
            } else {
                if (outsz) win32_mem_write32(outsz, 0);
                state.gpr.rax.dword = 0;                              // EOF
            }
            state.gpr.rsp.dword = esp + 4;                            // cdecl ret
            return mem;
        }
    }
    extern uint32_t g_bo2_lua_allocf;                 // defined with the console
    if (g_bo2_lua_allocf && addr == g_bo2_lua_allocf) {
        const uint32_t esp = state.gpr.rsp.dword;
        const uint32_t nsize = win32_mem_read32(esp + 0x10);
        // 🎯 LA SONDE NE COMPTAIT QUE LES ALLOCATIONS. Le `if (nsize)` plus bas
        // saute les LIBERATIONS (nsize==0), donc elle ne pouvait pas repondre a
        // la seule question qui decide : le tas LUI de 4 Mio (0x400000, monte
        // par le jeu en 0x0063d9ea) se remplit-il parce que rien n'est rendu ?
        // Son `total=5323067` sur un tas de 4194304 n'est PAS une preuve de
        // fuite : c'est un CUMUL de demandes, et un cumul ignore les retours.
        // l_alloc(ud, ptr, osize, nsize) donne le delta exact : ptr==0 = neuf,
        // sinon osize est l'ancienne taille. On imprime donc l'occupation VIVE.
        {
            const uint32_t lptr   = win32_mem_read32(esp + 0x8);
            const uint32_t losize = win32_mem_read32(esp + 0xc);
            static int64_t  s_live = 0, s_live_peak = 0;
            static uint64_t s_frees = 0, s_seq = 0;
            s_live += (int64_t)nsize - (int64_t)(lptr ? losize : 0u);
            if (!nsize) s_frees++;
            if (s_live > s_live_peak) s_live_peak = s_live;
            // 🎯 PROUVER LE DOUBLE FREE PLUTOT QUE LE SUPPOSER. La mesure
            // precedente donne une occupation VIVE NEGATIVE (-156 420 o) et
            // 24 924 liberations pour 676 allocations : le tas n'est pas plein
            // (pic 2,85 Mio sur 4), sa COMPTABILITE est detruite. L'hypothese
            // de tete est qu'un bloc est rendu plusieurs fois.
            //
            // On ne voit que l'ENTREE de l'allocateur, jamais sa valeur de
            // retour : impossible donc de tenir l'ensemble des blocs vivants.
            // Mais un double free se detecte sans ca — on retient les pointeurs
            // LIBERES, et un pointeur qui repasse en liberation sans avoir ete
            // realloue entre-temps EST rendu deux fois. C'est sain dans les deux
            // sens : zero ligne ne refute pas l'hypothese (le bloc peut avoir
            // ete realloue via un chemin qu'on ne voit pas), mais une ligne la
            // prouve.
            static std::unordered_map<uint32_t, uint32_t> s_freed;
            static uint64_t s_dbl = 0;
            if (lptr) {
                if (!nsize) {
                    const uint32_t n = ++s_freed[lptr];
                    if (n > 1u && ++s_dbl <= 20u)
                        fprintf(stderr, "[LUA-DOUBLEFREE] ptr=0x%08x rendu %u fois"
                                        " (osize=%u, appel #%llu)\n",
                                lptr, n, losize, (unsigned long long)(s_seq + 1));
                } else {
                    s_freed.erase(lptr);        // realloue : il revit
                }
            }
            if ((++s_seq % 256u) == 0u)
                fprintf(stderr, "[LUA-LIVE] vif=%lld o  pic=%lld  tas=4194304"
                                "  appels=%llu dont %llu liberations"
                                "  | doubles=%llu sur %zu pointeurs libres distincts\n",
                        (long long)s_live, (long long)s_live_peak,
                        (unsigned long long)s_seq, (unsigned long long)s_frees,
                        (unsigned long long)s_dbl, s_freed.size());
        }
        static uint64_t s_calls = 0, s_bytes = 0;
        static uint32_t s_peak = 0;
        if (nsize) {
            s_calls++; s_bytes += nsize;
            // Every LARGE request by name, plus each new peak: the size the
            // allocator refuses is the last one logged before the engine's
            // "LUI: Out of memory". A tally alone could not say which.
            // A SECOND, API-FREE OUTPUT CHANNEL. Sizes in the magic window are
            // always reported, whatever the peak: a payload that does
            // `string.rep("x", 0xB0000 + n)` puts the number n in the log
            // without needing print, without needing error to survive an
            // unwind, and without knowing one engine function. Independent of
            // the stack scan on purpose — the two can disagree, and then the
            // disagreement is itself the finding.
            const bool beacon = (nsize >= 0xB0000u && nsize < 0xC0000u);
            if (beacon)
                fprintf(stderr, "[BO2-LUA-BEACON] n=%u (size=%u)\n", nsize - 0xB0000u, nsize);
            else if (nsize >= 4096u || nsize > s_peak) {
                if (nsize > s_peak) s_peak = nsize;
                fprintf(stderr, "[LUA-ALLOC] request %u bytes (calls=%llu total=%llu peak=%u)\n",
                        nsize, (unsigned long long)s_calls, (unsigned long long)s_bytes, s_peak);
            }
        }
    }
    {   // Which LUI element builtins does the frontend actually invoke?
        // ⚠️ THE PRINT BELOW IS FIRST-USE-ONLY (then one in 2000), so it lists the
        // builtins the frontend has EVER touched and can say nothing about
        // whether it is still running — which is exactly the question "why does
        // the menu draw no text" needs. It reported 38 lines before Return and 2
        // after, and reading that as "LUI stopped" would have been the same
        // capped-view mistake this file already documents twice. Count into a
        // wall-clock counter as well, and let bo2_lui_rate() report a RATE.
        if (bo2_lui_names_ready()) bo2_lui_count(addr);
        // The OTHER Lua->engine boundary: UIExpression's 444 functions through
        // one dispatcher + the individually registered LUI globals. BO2_UIX_PROBE.
        bo2_uix_count(addr, &state);
        // WHICH DVAR DOES THE RETURN HANDLER SET? [LUI-SPLIT] says lua.dvar_set
        // fires exactly ONCE after the keypress and that the handler does nothing
        // else — so that single dvar is the whole visible effect of pressing
        // Return, and naming it names the transition.
        //
        // lua.dvar_set takes an already-resolved DvarMetatable userdata, not a
        // name, so the name has to come out of the dvar struct ([dvar+0] per the
        // layout this shim already uses elsewhere: +0x10 type, +0x18 value).
        // Rather than assume the Lua stack layout (HavokScript is not stock
        // Lua 5.1 — its TValue tag is packed into the low nibble), PRINT THE
        // SHAPE and let the data say where the pointer lives.
        if (addr == 0x89e760u && bo2_getenv("BO2_DVAR_PROBE")) {
            static uint32_t nd = 0;
            if (++nd <= 6) {
                const uint32_t esp = state.gpr.rsp.dword;
                const uint32_t L   = win32_mem_read32(esp + 4);
                const uint32_t top = L ? win32_mem_read32(L + 0x24) : 0;
                const uint32_t bas = L ? win32_mem_read32(L + 0x28) : 0;
                fprintf(stderr, "[DVAR-SET #%u] L=%08x top=%08x base=%08x\n",
                        nd, L, top, bas);
                for (uint32_t k = 0; k < 4 && bas; k++) {
                    const uint32_t slot = bas + k * 8;
                    const uint32_t lo = win32_mem_read32(slot);
                    const uint32_t hi = win32_mem_read32(slot + 4);
                    fprintf(stderr, "[DVAR-SET]   slot%u @%08x = %08x %08x", k, slot, lo, hi);
                    // Follow one and two levels of indirection, printing anything
                    // that reads as a C identifier — a dvar's name is its first
                    // field, so the right pointer announces itself.
                    // THE VALUE IS THE HIGH DWORD. The slot dumped as
                    // "00000007 40ca1760" is {tag=7 (userdata), value=ptr} — the
                    // tag is at +0 and the payload at +4, so following `lo` found
                    // nothing. Follow `hi`, then one more level: the userdata
                    // holds the dvar pointer and a dvar's first field is its name.
                    // ...but the PAYLOAD sits past the userdata header, and
                    // guessing that header's size is exactly the hand-computed
                    // offset this project has a rule against. SCAN instead: treat
                    // each dword in the object's first 64 bytes as a pointer, read
                    // ITS first field as a C string, and print whatever reads as an
                    // identifier. A dvar's first field is its name, so the correct
                    // offset announces itself instead of being assumed.
                    for (uint32_t off = 0;
                         off <= 64 && hi >= 0x1000u && hi < 0xF0000000u; off += 4) {
                        uint32_t cand = win32_mem_read32(hi + off);
                        if (cand < 0x1000u || cand >= 0xF0000000u) continue;
                        uint32_t np = win32_mem_read32(cand);
                        if (np < 0x1000u || np >= 0xF0000000u) continue;
                        char nm[48]; int n = 0;
                        while (n < 47) {
                            uint8_t c = win32_mem_read8(np + n);
                            if (c < 0x20 || c > 0x7e) break;
                            nm[n++] = (char)c;
                        }
                        nm[n] = 0;
                        bool ident = n >= 3;
                        for (int q = 0; q < n && ident; q++)
                            if (!(isalnum((unsigned char)nm[q]) || nm[q] == '_'))
                                ident = false;
                        if (ident) {
                            // ⚠️ THE VALUE IS A BYTE FOR A BOOL DVAR, not a dword.
                            // Dvar_GetBool (0x4ba000) is exactly
                            //     cmp [eax+0x10], 1 ; mov al, byte ptr [eax+0x18]
                            // so type 1 = bool and only the LOW BYTE of +0x18 is
                            // the value. Printing the dword read 0x40c82b01 and I
                            // flagged it as untrustworthy — it was the right
                            // offset read at the wrong width, and its low byte was
                            // the 1 I was looking for.
                            const uint32_t ty = win32_mem_read32(cand + 0x10);
                            const uint32_t raw = win32_mem_read32(cand + 0x18);
                            fprintf(stderr, "   +%u -> dvar \"%s\" type=%u", off, nm, ty);
                            if (ty == 1) fprintf(stderr, " BOOL=%u", raw & 0xFFu);
                            else         fprintf(stderr, " value=0x%x", raw);
                        }
                    }
                    fprintf(stderr, "\n");
                }
            }
        }
        // BO2_CFN_DIFF=1 — WHICH CODE PATHS ARE NEW AFTER THE KEYPRESS.
        //
        // The open question is what the title screen's Return handler asks the
        // engine for, and the existing LUI probe cannot see it: it only knows LUI
        // *element* builtins, while the Engine.* functions Lua calls (open a menu
        // by name and friends) are registered in a different table entirely.
        // Rather than hunt for that table, take a DIFFERENCE: every indirect call
        // target is already funnelled through this dispatch point, so record the
        // set seen before the key and report only targets that appear for the
        // first time after it. Those are, by construction, the work the keypress
        // caused — no name table required.
        bo2_cfn_diff_note(addr);
        static const int lui_probe = bo2_getenv("BO2_LUI_PROBE") ? 1 : 0;
        if (lui_probe && bo2_lui_table_call(state, addr)) {
            // BO2_LUI_TABLE named it (bo2_lui_table_call logged it)
        } else if (lui_probe) {
            const char* bn = lui_builtin_name(addr);
            if (bn) {
                static std::unordered_map<uint32_t, uint32_t> seen;
                uint32_t& c = seen[addr];
                if (c++ == 0 || (c % 2000) == 0)
                    fprintf(stderr, "[LUI] %s (sub_%08x) call #%u — %zu distinct builtins used\n",
                            bn, addr, c, seen.size());
            }
        }
    }
    // check if it's a jump-table target (for thunk-style calls)
    if (const BlockFn fn = lifted_fn(addr)) {   // C32
        // Instrument: log call + return eax for first 200 calls (finds init failures)
        if (g_call_log_count < 200) {
            fprintf(stderr, "[CFN] call sub_%08x\n", addr);
            void* result = fn(&state, addr, mem);
            fprintf(stderr, "[CFN] ret  sub_%08x eax=0x%08x\n", addr, state.gpr.rax.dword);
            g_call_log_count++;
            return result;
        }
        return fn(&state, addr, mem);
    }
    if (bo2_est_heap_code(addr)) {                   // P708 : `call` vers le code du tas
        tas_provenance("call", state, addr, __builtin_return_address(0));
        const uint32_t attendu = win32_mem_read32(state.gpr.rsp.dword);   // le retour empile par le `call`
        const uint32_t suite = bo2_heap_code(state, addr, &mem);
        state._0 = suite;
        if (suite != attendu) bo2_reprise_non_locale(state, suite);   // le tas rend ailleurs : reprise
        return mem;
    }
    // Cible de .text non liftee : ses octets d'origine, au lieu de sauter l'appel.
    if (bo2_interp_peut(addr)) {
        const uint32_t attendu = win32_mem_read32(state.gpr.rsp.dword);   // le retour empile par le `call`
        bool traduite = false;
        const uint32_t suite = bo2_interp(state, addr, &mem, "appel", &traduite);
        if (traduite) {   // la fin du cadre est traduite : elle rend elle-meme a l'appelant
            const BlockFn fn = lifted_fn(suite);
            if (!fn) abort();
            return fn(&state, suite, mem);
        }
        state._0 = suite;
        if (suite != attendu) bo2_reprise_non_locale(state, suite);
        return mem;
    }
    // Bound the unknown-target spam: a run that keeps calling unresolvable
    // targets is corrupt — stop it before it writes gigabytes of trace.
    {
        static int s_unknown_total = 0;
        if (++s_unknown_total > 5000) {
            win32_iat_summary();   // was an import slot destroyed? print it before dying
            fprintf(stderr, "[RUNAWAY] %d unknown-target calls — aborting\n", s_unknown_total);
            abort();
        }
    }
    fprintf(stderr, "[shim] function_call: unknown target %#x\n", addr);
    // Null function pointer: name the caller — an unregistered callback slot
    // (suspected in the streaming_temp_image wait). Log ret + this + tid.
    if (addr == 0) {
        static int s_null_calls = 0;
        // ⚠️ THE CAP WAS 16, AND 16 IS WHAT EVERY RUN REPORTED — so the number
        // looked like a measurement and was a ceiling. The true count comes from
        // the uncapped "[shim] function_call: unknown target" line above and is
        // 36, deterministically, in four runs (and ZERO in the last run that
        // rendered the menu room). Reading a PRESENCE off a capped probe is the
        // same mistake as reading an absence off one; the guide records the
        // second and this is the first. 64 covers the 36 with headroom.
        // ⚠️⚠️ ONLY THE FIRST ONE IS REAL. THE REST ARE THIS PROBE'S OWN WAKE.
        //
        // These calls are COM `call [vtable+n]` — __stdcall, callee cleans. Read
        // sub_5e3f70 at 0x5e3f8a: `push edx; push eax; call [ecx+0x1c]`, then at
        // 0x5e3f97 `mov eax,[esp+0x50]` and immediately `push edx; push eax;
        // call [ecx+0x28]`. Two pushes between the two calls and NO pops, because
        // the callee is supposed to have removed its own 8 bytes.
        //
        // When the target is null we log and RETURN — without that cleanup. So
        // esp is 8 low for the next call, 12 for the one after, and every later
        // `this` is read off a stack that has drifted. That is exactly what the
        // measured column shows: esp 0x431446a8 -> a0 -> 9c -> 98, each line's
        // args being the previous line's shifted by one slot, `this=0x004a1ef5`
        // (a CODE address) and `vtbl=0xccccccc3` (MSVC's uninitialised-stack
        // filler). Not objects. Not faults. Debris.
        //
        // I wrote "36 null vtable calls" into two commits and the handoff before
        // noticing. The number is 1. So SAY SO IN THE LOG, per thread, rather
        // than emitting 35 more lines that each look like a finding.
        //
        // NOT FIXED, deliberately: cleaning the stack would need the callee's
        // argument count, which is unknowable for an unresolved target, and
        // aborting on a null call would turn runs that currently survive into
        // crashes. Both are real options and both are decisions about the GUEST's
        // fate; this change is only about the instrument telling the truth.
        thread_local uint32_t t_first_null_esp = 0;
        const bool cascade = (t_first_null_esp != 0 &&
                              state.gpr.rsp.dword < t_first_null_esp);
        if (cascade) {
            static int s_cascade = 0;
            if (s_cascade++ < 8)
                fprintf(stderr, "[NULL-CALL-CASCADE] ret=0x%08x esp=0x%08x (%u bytes below the "
                                "first null call on tid %d) — `this` and args below are DEBRIS "
                                "from the uncleaned stdcall stack, not a second fault\n",
                        win32_mem_read32(state.gpr.rsp.dword), state.gpr.rsp.dword,
                        t_first_null_esp - state.gpr.rsp.dword, win32_current_tid());
        } else if (s_null_calls++ < 64) {
            uint32_t esp = state.gpr.rsp.dword;
            t_first_null_esp = esp;
            // THE OBJECT, NOT JUST THE CALLER. d3d_iface_obj() fills all 256
            // slots of every fake vtable with a 0xE6iissss sentinel, so a null
            // slot cannot belong to an object this runtime created — the guest
            // is dispatching on something we never made. `this` is the first
            // stack arg (COM on x86 is __stdcall, `this` pushed last), its
            // vtable is [this], and the first few slots say whether the vtable
            // is absent, zeroed, or real-but-short.
            const uint32_t self = win32_mem_read32(esp + 4);
            const uint32_t vt   = (self >= 0x1000u && self < 0xF0000000u)
                                ? win32_mem_read32(self) : 0;
            // THE CINEMATIC GLOBALS, AT THE FAULT. 0xeb9938 is the WebM
            // cinematic class's vtable — proved by iscinematicwebm (sub_6cdf50):
            //     cmp [0x37d45c0], esi        ; the CURRENT cinematic handle
            //     cmp [0x37d48f4], 0xeb9938   ; its CLASS
            // and that class's vtable slot +0x1c is the teardown thunk 0x703c30
            // -> sub_52a120, which is EXACTLY the slot this failing call
            // dispatches through (0x5e3f92: mov eax,[ecx+0x1c]; call eax).
            // So the question this answers in one line: is the object the video
            // system is tearing down still the cinematic the engine thinks is
            // current, or has it already been replaced underneath it?
            const uint32_t cine_handle = win32_mem_read32(0x37d45c0u);
            const uint32_t cine_class  = win32_mem_read32(0x37d48f4u);
            fprintf(stderr, "[NULL-CALL] cinematic: handle=0x%08x class=0x%08x%s\n",
                    cine_handle, cine_class,
                    cine_class == 0xeb9938u ? " (= the WebM cinematic class)"
                                            : " ⚠️ NOT the WebM class 0xeb9938");
            // ⚠️ THIS PRINTS THE STDCALL/COM LAYOUT AND SAYS SO. `this` and
            // `vtbl` below are [esp+4] and [esp+8] — correct for a COM
            // `call [vtable+n]` where `this` was pushed, and WRONG for a
            // thiscall site, where `this` is in ECX and [esp+4] is just the
            // first real argument. Measured on t6mp: at sub_534080's
            // `mov eax,[ecx]; mov eax,[eax+0x14]; call eax` this line reported
            // this=0x0010fe5c vtbl=0xbf800000, and 0xbf800000 is not a vtable at
            // all — it is the float -1.0f being passed. ECX is printed too;
            // compare them before believing either.
            fprintf(stderr, "[NULL-CALL] ret=0x%08x ecx=0x%08x esp=0x%08x args:[%08x %08x %08x] tid=%d"
                            " (stdcall view) this=0x%08x vtbl=0x%08x slots:[%08x %08x %08x %08x]"
                            "  — if this is a THISCALL site, `this` is ECX above\n",
                    win32_mem_read32(esp), state.gpr.rcx.dword, esp,
                    self, win32_mem_read32(esp+8),
                    win32_mem_read32(esp+0xc), win32_current_tid(), self, vt,
                    (vt >= 0x1000u && vt < 0xF0000000u) ? win32_mem_read32(vt)       : 0xBADBAD00u,
                    (vt >= 0x1000u && vt < 0xF0000000u) ? win32_mem_read32(vt + 4)   : 0xBADBAD04u,
                    (vt >= 0x1000u && vt < 0xF0000000u) ? win32_mem_read32(vt + 8)   : 0xBADBAD08u,
                    (vt >= 0x1000u && vt < 0xF0000000u) ? win32_mem_read32(vt + 0x1c): 0xBADBAD1Cu);
        }
    }
    // The CRT's fatal reporter resolves MessageBoxW via GetProcAddress (sentinel
    // in the 0xdead0000 range) then calls it — arg2 is the wide error message,
    // which names the runtime error (e.g. "R6009 - not enough space for ...").
    if ((addr & 0xffff0000u) == 0xdead0000u) {
        uint32_t esp = state.gpr.rsp.dword;
        crt_dump_wstr("mb_text",    win32_mem_read32(esp + 8));
        crt_dump_wstr("mb_caption", win32_mem_read32(esp + 12));
        crt_dump_wstr("mb_a4",      win32_mem_read32(esp + 4));
    }
    // Real-code (non-sentinel) unknown target: this returns 0 to the caller, so
    // dump the CALLER (return address the indirect `call` pushed, popped just
    // below) + this/ecx once per unique target — pinpoints the function that
    // branches on the (garbage) result. Read-only diagnostic.
    // ⚠️ THE RANGE WAS THE HOLE IN THE INSTRUMENT (2026-09-12). It covered the PE
    // image only, so the target that actually ENDED w28_3 printed nothing beyond
    // the one-line "[shim] function_call: unknown target 0x410302b0": that target
    // is a GUEST HEAP address, and a heap target is MORE interesting than a code
    // one, not less — it means the object being dispatched on is not what the
    // guest thinks it is. Print the caller for anything that is not one of our
    // own sentinels (0xdead.... GetProcAddress, 0xE5/0xE6 D3D, 0xE7 Steam); it is
    // one line per DISTINCT target, so widening it costs nothing.
    const bool own_sentinel = (addr & 0xffff0000u) == 0xdead0000u ||
                              (addr & 0xff000000u) == 0xe5000000u ||
                              (addr & 0xff000000u) == 0xe6000000u ||
                              (addr & 0xff000000u) == 0xe7000000u;
    if (!own_sentinel && addr >= 0x1000u && addr < 0xf0000000u) {
        static DiagCounter<10> seen_unk;   // P661/C15 : sans verrou, tous les fils passent ici
        if (seen_unk.bump(addr) == 0) {
            uint32_t esp = state.gpr.rsp.dword;
            fprintf(stderr, "[UNK-CALLER] target=%#010x ret=0x%08x ecx=0x%08x eax=0x%08x edx=0x%08x\n",
                    addr, win32_mem_read32(esp), state.gpr.rcx.dword,
                    state.gpr.rax.dword, state.gpr.rdx.dword);
            // THE OBJECT THAT WAS DISPATCHED ON. A `call [[ecx]]` that lands on a
            // heap address means the vtable word is not a vtable. Print both
            // readings — ECX (thiscall) and [esp+4] (stdcall/COM `this`) — and
            // the first slots of whatever each points at, so the next log says
            // which one is the object without another run.
            const uint32_t self = win32_mem_read32(esp + 4);
            auto slots = [&](uint32_t o, const char* tag) {
                if (o < 0x1000u || o >= 0xf0000000u) return;
                const uint32_t vt = win32_mem_read32(o);
                fprintf(stderr, "    [UNK-OBJ %s] obj=0x%08x vtbl=0x%08x slots:[%08x %08x %08x]\n",
                        tag, o, vt,
                        (vt >= 0x1000u && vt < 0xf0000000u) ? win32_mem_read32(vt)     : 0xBADBAD00u,
                        (vt >= 0x1000u && vt < 0xf0000000u) ? win32_mem_read32(vt + 4) : 0xBADBAD04u,
                        (vt >= 0x1000u && vt < 0xf0000000u) ? win32_mem_read32(vt + 8) : 0xBADBAD08u);
            };
            slots(state.gpr.rcx.dword, "thiscall ecx");
            slots(self, "stdcall [esp+4]");
            // Walk the EBP chain so the exit-DECIDING frame (higher than the
            // immediate caller) can be identified — the ESP unwind after this
            // call shows the decision is made further up.
            uint32_t bp = state.gpr.rbp.dword;
            for (int i = 0; i < 14 && bp >= 0x1000 && bp < 0xFFFFF000; i++) {
                uint32_t ret2 = win32_mem_read32(bp + 4), saved = win32_mem_read32(bp);
                fprintf(stderr, "    [UNK-CHAIN %#010x] bp=0x%08x ret=0x%08x\n", addr, bp, ret2);
                if (saved <= bp) break;
                bp = saved;
            }
        }
    }
    state.gpr.rax.dword = 0;
    state.gpr.rsp.dword += 4;
    return mem;
}

// ── 🎯 BO2_CSV=1 — WHICH GUEST CALL LOSES A CALLEE-SAVED REGISTER ────────────
//
// In Win32 x86, EBP/EBX/ESI/EDI are callee-saved: after a `call` returns
// normally they must hold what they held before it. That is a HARD invariant,
// and it is the one the port is visibly breaking. Five consecutive angola runs
// end with Main's EBP at 0x00000000 / 0x51 / 0x3c / 0xa3b0f8 over a healthy ESP,
// and the Server dies of the same thing: the GSC VM's epilogue
// `lea esp,[ebp+0x74]; pop ebp; ret` turns a dead EBP into esp=0x7d and a return
// to 0x002054ec — the [unwind-badret] that orphans the event Main waits on.
// EBP is a general-purpose register in this binary (it dies and revives by
// import #606 in a perfectly healthy boot), so only the ACROSS-A-CALL invariant
// can tell a legitimate scratch use from a lost save.
//
// Checked only when the call returned normally — ESP back to entry+4. A longjmp
// out of the callee leaves ESP elsewhere and must not be reported.
static uint64_t g_csv_calls, g_csv_bad_bp, g_csv_bad_other;
// P708 : heap_code.cpp rend ici chaque sortie du code du tas vers .text ou un import,
// comme un appel invite dont le retour est deja empile.
extern "C" void* bo2_heap_code_appel(State& state, uint32_t addr, void* mem) {
    return bo2_remill_call_inner(state, addr, mem);
}
// 🎯 C52 (2026-10-24) — VOIE COURTE DE L'APPEL INDIRECT. Chaque `call` indirect vers du code lifte traversait
// bo2_remill_call_inner : anneau de miettes (TLS, 2 lectures, 6 champs dans un tableau partage), sondes eteintes,
// compteur LUI, 4 tests de vtables factices, IAT, GetProcAddress, puis lifted_fn. Profil P918 (multi Rush, fil
// principal) : crumb_and_check 0,9 % + call_inner 0,7 % + l'entree 0,3 %. Ici, quand rien ne sonde, une cible du
// .text deja liftee part droit a son corps. Seule semantique gardee devant elle : audio_preempt (cession au mixeur,
// meme compte par fil). Retombent sur l'entree complete : le thunk `call $+5` (cible = [esp]), le lecteur Lua
// (g_bo2_lua_loading), un VA surveille ([BI-TRACE]/[BUILTIN]), un builtin LUI (compteurs [LUI-SPLIT]), RING2, les
// 200 premiers appels ([CFN]), toute cible non liftee (tas, interprete, imports, vtables). Perdu : les miettes
// d'appel des vidages de plantage ; BO2_CALL_SLOW=1 remet l'ancien chemin. Temoin : [APPELFAST].
#if defined(BO2_TARGET_SPS)
static constexpr uint32_t kAppelTexteFin = 0x9ef000u;
#elif defined(BO2_TARGET_MPS)
static constexpr uint32_t kAppelTexteFin = 0xb09000u;
#else
static constexpr uint32_t kAppelTexteFin = 0xb07000u;
#endif
extern bool g_bo2_lua_loading;
static uint32_t bo2_appel_cold = 0xffffffffu;   // 0 voie courte, 1 entree complete, ~0 pas resolu
[[gnu::noinline]] static void appel_cold_resolve() {
    static const char* const kSondes[] = {"BO2_CALL_SLOW", "BO2_CSV", "BO2_PRED_WATCH", "BO2_WALK_LOG", "BO2_GUMP", "BO2_GUMP_CALL",
        "BO2_RING2_TRACE", "BO2_EBP_WATCH", "BO2_LUI_PROBE", "BO2_UIX_PROBE", "BO2_CFN_DIFF", "BO2_LUA", "BO2_LUA_SRC",
        "BO2_SAVEDEV", "BO2_LUA_DUMP"};
    const char* qui = nullptr;
    for (const char* k : kSondes) {
        const char* e = bo2_getenv(k);
        if (e && *e && !(k == kSondes[0] && *e == '0')) { qui = k; break; }
    }
    bo2_appel_cold = qui ? 1u : 0u;
    fprintf(stderr, "[APPELFAST] %s%s\n", qui ? "DESARME par " : "ARME : appel indirect vers le lifte en direct",
            qui ? qui : "");
}
static inline bool lui_bit(uint32_t va) {
    const uint32_t k = (va >> 4) & 0xffffu;
    return (g_lui_bits[k >> 6] >> (k & 63u)) & 1u;
}
extern "C" [[gnu::used]] void* __remill_function_call(State& state, uint32_t addr, void* mem) {
    if (__builtin_expect(bo2_appel_cold == 0, 1)) {
        if (addr - 0x401000u < kAppelTexteFin - 0x401000u && !g_r2_armed && !g_bo2_lua_loading &&
            g_call_log_count >= 200 && g_wva_slot[(addr >> 4) & 1023u] == 0 && !lui_bit(addr) &&
            addr != win32_mem_read32(state.gpr.rsp.dword)) {
            if (const BlockFn fn = lifted_fn(addr)) {
                audio_preempt();
                return fn(&state, addr, mem);
            }
        }
        return bo2_remill_call_inner(state, addr, mem);
    }
    if (bo2_appel_cold == 0xffffffffu) appel_cold_resolve();
    static const bool on = bo2_getenv("BO2_CSV") != nullptr;
    if (__builtin_expect(!on, 1)) return bo2_remill_call_inner(state, addr, mem);
    const uint32_t sp = state.gpr.rsp.dword, bp = state.gpr.rbp.dword, bx = state.gpr.rbx.dword,
                   si = state.gpr.rsi.dword, di = state.gpr.rdi.dword;
    // 🎯 SCOPE IT TO THE GSC VM. [VM-EBP] caught the VM (sub_87f7c0,
    // 0x87f7c0..0x8833d1) calling _setjmp3 with ebp=1 where its own frame says
    // 0x4e5daad0 (runs/name_7) — and the VM writes EBP only in its prologue and
    // two epilogues, so a CALLEE lost it. Its builtins are called through a
    // function pointer, i.e. through here. Report ANY EBP change across a call
    // the VM makes, normal return or not: an abnormal return (a longjmp out of
    // the builtin, resumed by the unwind climb) is exactly where a wrong EBP
    // would be installed, so it must not be filtered away.
    const uint32_t caller = win32_mem_read32(sp);
    const bool from_vm = caller >= 0x87f7c0u && caller < 0x8833d1u;
    void* r = bo2_remill_call_inner(state, addr, mem);
    ++g_csv_calls;
    if (from_vm && state.gpr.rbp.dword != bp) {
        static int shown_vm = 0;
        if (shown_vm++ < 16)
            fprintf(stderr, "🎯 [VM-CALLEE-EBP] the GSC VM called sub_%08x from 0x%08x and got EBP back CHANGED: 0x%08x -> 0x%08x "
                            "(esp 0x%08x -> 0x%08x, %s) tid=%d\n",
                    addr, caller, bp, state.gpr.rbp.dword, sp, state.gpr.rsp.dword,
                    state.gpr.rsp.dword == sp + 4u ? "normal return" : "ABNORMAL return (longjmp/climb)",
                    win32_current_tid());
    }
    if (state.gpr.rsp.dword != sp + 4u) return r;         // did not return normally (longjmp / thunk)
    if (state.gpr.rbp.dword != bp) {
        ++g_csv_bad_bp;
        static int shown = 0;
        if (shown++ < 24)
            fprintf(stderr, "🎯 [CALLEE-SAVED] sub_%08x returned with EBP CHANGED: 0x%08x -> 0x%08x "
                            "(esp 0x%08x -> 0x%08x, ret=0x%08x) tid=%d call #%llu\n",
                    addr, bp, state.gpr.rbp.dword, sp, state.gpr.rsp.dword,
                    win32_mem_read32(sp), win32_current_tid(), (unsigned long long)g_csv_calls);
    }
    if (state.gpr.rbx.dword != bx || state.gpr.rsi.dword != si || state.gpr.rdi.dword != di) ++g_csv_bad_other;
    if ((g_csv_calls % 4000000ull) == 0)
        fprintf(stderr, "[CALLEE-SAVED] %llu calls checked: %llu lost EBP, %llu lost EBX/ESI/EDI\n",
                (unsigned long long)g_csv_calls, (unsigned long long)g_csv_bad_bp,
                (unsigned long long)g_csv_bad_other);
    return r;
}

// Return address of the most recent guest `ret`. A guest longjmp unwinds the
// HOST frames of the lifted call chain, so after the resumed function returns
// there is no host frame left to return into — but the guest return address it
// popped is still the correct next PC. thread_trampoline re-dispatches there to
// walk the guest chain back up to the thread proc (see [unwind] logs).
uint32_t g_last_ret_pc = 0;
// 🎯 P644 (2026-09-24) — UN PAR FIL HOTE, SINON LA REMONTEE LIT LE RET D'UN AUTRE.
// `g_last_ret_pc` etait ecrite par CHAQUE `ret` invite, sur TOUS les fils hotes.
// Des qu'une coroutine est hebergee (snd, snddec, jq), ses `ret` tournent EN
// PARALLELE du tourniquet : un fil qui remonte apres un longjmp lisait l'adresse
// de retour d'un AUTRE fil et rentrait dans son code avec ses propres registres.
// Mesure (runs/p643_angola_clean_snd-snddec_2_173735) : le serveur (tid 11)
// execute sub_576580, code flottant d'un autre fil, ecrit deux entrees d'IAT,
// puis finit en silence ; en JSS, les morts « NO LIFTED BLOCK » changent de VA a
// chaque run. Windows n'a aucun etat partage de ce genre.
// Meme porte que `g_cur` : tant que rien n'est heberge, ni lecture TLS ni
// changement de chemin ; le fil ordonnanceur garde la globale.
// C41 (P681) : la remontee lit desormais `State::_0` (ci-dessous), propre a chaque fil par construction.
// g_last_ret_pc ne sert plus qu'aux sondes qui l'impriment, et seulement depuis l'entree complete.
static inline bool ret_pc_heberge() {
    // C31 (P673) : le fil ordonnanceur (t_host_tid = -1) se reconnait sans TLS, voir kernel32_impl.cpp.
    return __builtin_expect(g_any_hosted, 0) && w32_read_tp() != bo2_sched_tp && t_host_tid >= 0;
}

// ── BO2_RET_RING=1 — THE LAST GUEST RETURNS BEFORE A STACK DIES ─────────────
//
// The crumb ring only sees INDIRECT dispatches, so it brackets tid 5's death
// between GetCurrentThreadId (ret 0x80df5b, esp healthy) and the CRT's __getptd
// (esp already 0xfffffbec) and cannot say what ran in between — direct
// lifted->lifted calls are invisible to it. Every guest `ret` comes through
// HERE, direct or not, so a ring of (target, esp) recorded here closes exactly
// that gap: the entry where esp stops being plausible names the function whose
// epilogue destroyed it.
//
// Two stores and a mask per return, behind an env gate, and dumped once per
// thread by the wild-esp branch below — which already exists and already fires.
struct RetCrumb { uint32_t addr, esp; };
static RetCrumb g_retring[64][32];
static uint32_t g_retn[64];
static inline bool ret_ring_on() {
    static const bool on = bo2_getenv("BO2_RET_RING") != nullptr;
    return on;
}
static void ret_ring_dump(int tid) {
    if (!ret_ring_on() || tid < 0 || tid >= 64) return;
    const uint32_t n = g_retn[tid];
    const uint32_t have = n < 32u ? n : 32u;
    fprintf(stderr, "   the last %u guest returns on tid %d, oldest first "
            "(esp is the value AFTER the ret):\n", have, tid);
    for (uint32_t i = n - have; i != n; ++i) {
        const RetCrumb& c = g_retring[tid][i & 31u];
        const bool wild = c.esp < 0x00010000u || c.esp >= 0xfff00000u;
        fprintf(stderr, "     ret -> 0x%08x   esp=0x%08x%s\n", c.addr, c.esp,
                wild ? "   <== already impossible here" : "");
    }
}

// 🎯 C41 (2026-09-27) — L'ADRESSE DU DERNIER `ret` VIT DANS LA State DU FIL, ET LE `ret` SE REPLIE.
// Chaque `ret` invite appelait cette fonction : 2,1 % de TOUT le CPU en P680 (xctrace 013120), pour
// des sondes eteintes et une globale. La remontee apres un longjmp (thread_trampoline,
// win32_run_main_thread_impl) n'a besoin que de l'adresse du dernier `ret` du fil qui remonte : elle va
// dans `ArchState::_0` (4 octets de bourrage a l'offset 4, qu'aucune semantique remill n'ecrit), qui est
// par construction celle du fil courant — plus de globale partagee, plus de TLS (P644).
// tools/boot.py `_inline_guest_ret` replie ce `ret` dans l'IR : le rangement dans `_0`, puis cette
// entree complete seulement si bo2_ret_cold != 0 (sondes BO2_EBP_WATCH / BO2_RET_RING, BO2_RET_SLOW=1,
// ou ~0 = pas encore resolu), si esp est hors de [0x10000, 0xfff00000) ([RET-WILD-ESP]) ou si la cible
// vaut 0x883440 ([RET-TO-883440]). BO2_RET_SLOW=1 remet l'ancien chemin a chaque `ret`, g_last_ret_pc
// compris (les sondes qui l'impriment). Temoin : [RETFAST].
uint32_t bo2_ret_cold = 0xffffffffu;   // 0 replie, 1 entree complete, ~0 pas resolu
[[gnu::noinline]] static void ret_cold_resolve() {
    const char* e = bo2_getenv("BO2_RET_SLOW");
    const bool lent = e && *e && *e != '0';
    const bool sondes = ret_ring_on() || (g_ebp_watch < 0 ? ebp_watch_init() : g_ebp_watch) != 0 ||
                        bo2_getenv("BO2_CMD_ABI") != nullptr;
    bo2_ret_cold = (lent || sondes) ? 1u : 0u;
    fprintf(stderr, "[RETFAST] %s (BO2_RET_SLOW=%s, sondes de ret %s)\n",
            bo2_ret_cold ? "DESARME : chaque ret passe par l'entree complete" : "ARME : ret replie",
            e ? e : "(defaut 0)", sondes ? "ARMEES" : "eteintes");
}
[[gnu::used]] void* __remill_function_return(State& state, uint32_t addr, void* mem) {
    state._0 = addr;
    // Android : le repli IR du `ret` (_inline_guest_ret) n'est pas applique par fold_lift.sh, a cause du test
    // du code du tas ; chaque `ret` arrive donc ici (3 a 4 % du fil ordonnanceur sur le S26). Meme voie courte
    // que le repli, plus ce test fait en ligne : une cible dans l'image [0x400000, 0x43bc000) n'est jamais du
    // code du tas (bo2_est_heap_code, heap_code.cpp). Sondes de ret (bo2_ret_cold != 0), esp sauvage et cible
    // 0x883440 prennent l'entree complete, comme avec le repli.
    {
        const uint32_t esp = state.gpr.rsp.dword;
        if (__builtin_expect(bo2_ret_cold == 0 && addr - 0x400000u < 0x43bc000u - 0x400000u &&
                                 esp - 0x10000u < 0xfff00000u - 0x10000u && addr != 0x883440u, 1))
            return mem;
    }
    // P725 : un `ret` vers le tas. Le destructeur de garde CEG 0x8ce090 a glisse l'entree du corps
    // dechiffre (bloc+0x40) dans la case de retour de l'enveloppe (sub_5090f0 pour
    // updategamerprofile), qui a ete decalee d'un mot. Sous Windows le processeur y va : le corps
    // tourne, puis 0x53dbf0 libere le bloc et rend a l'appelant d'origine ([esp] ici) avec esp+4.
    // Chez nous le code lifte de l'appelant reprenait apres son `call` : corps jamais execute,
    // pile decalee d'un mot, Cbuf_Execute lisait hors de cmd_text (gel OPTIONS et fin de mission).
    // Meme regle que le `jmp` vers le tas : la suite est le retour attendu, sinon reprise.
    // P729 : sauf le retour qu'attend la session du tas de ce fil (fonction liftee appelee par le
    // code du tas) : il revient a bo2_heap_code_appel, qui reprend l'emulation a cette adresse.
    if (__builtin_expect(bo2_est_heap_code(addr), 0) && !bo2_heap_code_attend(addr)) {
        tas_provenance("ret", state, addr, __builtin_return_address(0));
        const uint32_t attendu = win32_mem_read32(state.gpr.rsp.dword);
        const uint32_t suite = bo2_heap_code(state, addr, &mem);
        state._0 = suite;
        if (suite != attendu) bo2_reprise_non_locale(state, suite);
        addr = suite;
    }
    if (__builtin_expect(bo2_ret_cold == 0xffffffffu, 0)) ret_cold_resolve();
    ebp_poison_probe(state, 'R', addr);
    if (__builtin_expect(g_abi_tid >= 0, 0) && win32_current_tid() == g_abi_tid) abi_ret(state, addr);
    if (__builtin_expect(ret_ring_on(), 0)) {
        const int t = win32_current_tid();
        if (t >= 0 && t < 64) {
            RetCrumb& c = g_retring[t][g_retn[t] & 31u];
            c.addr = addr; c.esp = state.gpr.rsp.dword;
            ++g_retn[t];
        }
    }
    // 🎯 THE NET THAT CATCHES A DIRECT-CALL STACK DEATH.
    //
    // [ESP-FIRST-WILD] hangs off crumb_and_check, which only sees INDIRECT
    // dispatches — and this file says so itself at the crumb ring: "Direct
    // lifted->lifted calls are invisible to the shim". tid 10 dies inside
    // sub_4a98c0 -> sub_7fa710 -> _chkstk, which is direct calls end to end, so
    // that probe reported nothing while the thread's esp went to 0x00000014.
    //
    // EVERY guest `ret` comes through here, direct or not. Two compares on a
    // register gate it, so the hot path is unchanged (the earlier version of the
    // esp test cost 25x by calling a cross-TU accessor unconditionally), and the
    // window — below 64 KB or above 0xfff00000 — is far from any legitimate esp:
    // the main thread sits near 0x0010e000 and guest coroutine stacks above
    // 0x40000000. Every wild value actually recorded on tid 10 (0, 8, 0x14,
    // 0xfffffff8, 0xffffffec) is inside it.
    //
    // Reports once per thread, with the return TARGET — which is the caller that
    // was about to be resumed, i.e. the frame that was destroyed.
    if (__builtin_expect(state.gpr.rsp.dword < 0x00010000u ||
                         state.gpr.rsp.dword >= 0xfff00000u, 0)) {
        // ⚠️ uint8_t HERE WROTE A 155 MB LOG. `said[k]++ == 0` on a uint8_t
        // re-fires every 256 hits, and this sits on a loop doing tens of
        // millions of iterations — 528,010 lines from a probe meant to print
        // once. memory/probe-design-rules: "never leave a probe uncapped on a
        // known-infinite loop". uint32_t, and a hard ceiling that never wraps.
        static uint32_t said[64] = {0};
        const int tid = win32_current_tid();
        const int k = (tid >= 0 && tid < 64) ? tid : 63;
        if (said[k]++ < 3u) {
            uint32_t lo = 0, hi = 0;
            win32_thread_stack_range(tid, &lo, &hi);
            fprintf(stderr, "\n🎯 [RET-WILD-ESP] tid %d: a guest `ret` to 0x%08x with "
                    "esp=0x%08x, stack [0x%08x,0x%08x)\n"
                    "   eax=%08x ebx=%08x ecx=%08x edx=%08x esi=%08x edi=%08x ebp=%08x\n",
                    tid, addr, state.gpr.rsp.dword, lo, hi,
                    state.gpr.rax.dword, state.gpr.rbx.dword, state.gpr.rcx.dword,
                    state.gpr.rdx.dword, state.gpr.rsi.dword, state.gpr.rdi.dword,
                    state.gpr.rbp.dword);
            // 🎯 AND WHICH LIFTED FUNCTION'S `ret` THIS IS.
            //
            // `addr` is the return TARGET (0x00000000 here — useless, it is just
            // what the dead stack held). What is wanted is the function whose
            // epilogue is running, because the esp was destroyed INSIDE it,
            // between its last boundary and this ret — a `mov esp, <reg>` or
            // `leave` that no probe can straddle.
            //
            // The guest cannot say, but the HOST can: this handler is called
            // from the lifted body that is returning, so its own return address
            // names that body. Same trick __remill_missing_block already uses to
            // answer "who dispatched me". backtrace() here is safe — we are on a
            // normal call path, not in a signal handler.
            ret_ring_dump(tid);
            {
                void* fr[8];
                const int nf = backtrace(fr, 8);
                fprintf(stderr, "   the lifted body whose `ret` this is:\n");
                for (int f = 1; f < nf && f < 5; f++) {
                    Dl_info di{};
                    if (dladdr(fr[f], &di) && di.dli_sname)
                        fprintf(stderr, "     %-34s +0x%lx\n", di.dli_sname,
                                (unsigned long)((char*)fr[f] - (char*)di.dli_saddr));
                    else
                        fprintf(stderr, "     %p\n", fr[f]);
                }
            }
        }
    }
    // 🎯 DID A GUEST `ret` TARGET 0x883440?
    //
    // esi is preserved across every call measured (0x479b90 396,397; 0x62bb70
    // 35,425; the six inside 0x8833e0 386,306 — all zero violations), 0x883790 is
    // always entered with a good instance (47/47), and esi is written nowhere in
    // 0x8833e0..0x883560. So the one dispatch to sub_883440 with esi=1043 cannot
    // be the continuation of a real 0x8833e0 invocation.
    //
    // That leaves two ways to arrive there: a `ret` to a bogus address, or a
    // computed jump to a bogus target. This separates them in one run — and it is
    // the RIGHT place to ask, unlike the earlier sub_87cc9f test which could only
    // see one of the jump table's four cases.
    if (__builtin_expect(addr == 0x883440u, 0)) {
        static int n = 0;
        if (n++ < 4)
            fprintf(stderr, "\n[RET-TO-883440 #%d] a guest `ret` targeted 0x883440 — an address "
                    "no call site ends at. esp=%08x esi=%08x edi=%08x ebx=%08x ebp=%08x tid=%d "
                    "(so the dispatch is a RETURN to a corrupt address, not a jump)\n",
                    n, state.gpr.rsp.dword, state.gpr.rsi.dword, state.gpr.rdi.dword,
                    state.gpr.rbx.dword, state.gpr.rbp.dword, win32_current_tid());
    }
    if (__builtin_expect(!ret_pc_heberge(), 1)) g_last_ret_pc = addr;
    return mem;
}
[[gnu::used]] void* __remill_function_return_slow(State& state, uint32_t addr, void* mem) {
    return __remill_function_return(state, addr, mem);
}

extern "C" void* sub_51d360(State*, uint32_t, void*);
extern "C" __attribute__((used)) void* bo2_gsc_size(State* s, uint32_t pc, void* mem) {
    // GSC `size` handler. Operand at [esp+0xc] is a VariableValue: type at +0, data
    // at +4. It errors ("size cannot be applied to %s") unless the type is 1 or 2.
    uint32_t esp = s->gpr.rsp.dword;
    // `push esi; mov esi,[esp+0xc]` => operand VariableValue = arg2 = [esp+8].
    uint32_t a1 = win32_mem_read32(esp + 4), a2 = win32_mem_read32(esp + 8), a3 = win32_mem_read32(esp + 0xc);
    uint32_t vv = a2;
    uint32_t ty = win32_mem_read32(vv) & 0x7f, dat = win32_mem_read32(vv + 4);
    static int n = 0;
    if (n < 8 || (ty != 1 && ty != 2))
        fprintf(stderr, "[GSC-SIZE] #%d ret=0x%08x a1=0x%08x a2(vv)=0x%08x a3=0x%08x type=%u data=0x%08x%s\n",
                n, win32_mem_read32(esp), a1, a2, a3, ty, dat,
                (ty != 1 && ty != 2) ? "  <-- ERRORS" : "");
    n++;
    return sub_51d360(s, pc, mem);
}

// Interposer on FUN_0087e1d0 (save a suspended GSC thread's operand stack).
// It is reached by a DIRECT `bl _sub_87e1d0`, so the only way to see its
// arguments is to redirect the symbol's entry here (tools/patch_redirect.py) and
// tail-call a renamed copy of the real body. Prints the six stdcall-style args
// pushed by the caller; arg1 - arg2 is the byte span it copies, and that value
// coming out NEGATIVE is the ~4-billion-iteration hang.
extern "C" void* sub_87e1d0(State*, uint32_t, void*);
extern "C" __attribute__((used)) void* bo2_gsc_savestack(State* s, uint32_t pc, void* mem) {
    uint32_t esp = s->gpr.rsp.dword, a[6];
    for (int i = 0; i < 6; i++) a[i] = win32_mem_read32(esp + 4 + i * 4);
    int32_t span = (int32_t)(a[1] - a[2]);
    static int n = 0;
    if (n < 40 || span < 0) {
        fprintf(stderr, "[GSC-SAVESTACK] #%d ret=0x%08x thread=%u stackPtr=0x%08x base=0x%08x "
                "span=%d count=%d a3=0x%08x a4=0x%08x a5=0x%08x\n",
                n, win32_mem_read32(esp), a[0], a[1], a[2], span, span >> 3,
                a[3], a[4], a[5]);
        // a5 = lea eax,[ebp+0x68] in every caller, so the VM frame is recoverable.
        // The `wait` handler leaves its float->int conversion inputs and result in
        // that frame: [ebp-0x40] = seconds*fps as a float, [ebp-0xcc] = the 2^-30
        // rounding epsilon, [ebp-0x18] = the fistp result, [ebp+0x38] = frame count.
        uint32_t ebp = a[5] - 0x68;
        uint32_t f = win32_mem_read32(ebp - 0x40);
        uint32_t dlo = win32_mem_read32(ebp - 0xcc), dhi = win32_mem_read32(ebp - 0xc8);
        float ff; std::memcpy(&ff, &f, 4);
        double dd; uint64_t db = ((uint64_t)dhi << 32) | dlo; std::memcpy(&dd, &db, 8);
        fprintf(stderr, "    wait-frame: [ebp-0x40]=%08x (%g)  [ebp-0xcc]=%016llx (%g)  "
                "fistp[ebp-0x18]=%d  frames[ebp+0x38]=%d\n",
                f, (double)ff, (unsigned long long)db, dd,
                (int32_t)win32_mem_read32(ebp - 0x18), (int32_t)win32_mem_read32(ebp + 0x38));
    }
    n++;
    return sub_87e1d0(s, pc, mem);
}

// --- Interpose DB_FindXAssetHeader (FUN_004637c0) to break the INFINITE precache
// wait on SP models the frontend references but that are absent from every loaded
// zone (car_sp, inigun_enemy_pilot, scar_rangefinder_gl, concussion_grenade_mp.shock
// — verified MISSING from the asset DB while frontend.d3dbsp/GfxWorld and its GSCs
// ARE registered). Signature: DB_FindXAssetHeader(name=arg0, ..., timeout=arg3);
// timeout==-1 = "wait forever" (0x463978 `cmp ebx,-1; je <infinite Sleep loop>`).
// Those assets never stream in, so tid0's one-shot init pump (FUN_0080aaf0) waits
// forever and the menu frame loop never starts → LUI never draws. Clamp the timeout
// to 0 for exactly those names so the real body takes its OWN give-up/default-asset
// path (0x4639f2+ per-type default switch) and init proceeds. Wired via
// patch_redirect (_sub_4637c0=_bo2_db_find); tail-calls the untouched impl copy.
char g_db_last_inf[16][64];
uint32_t g_db_last_inf_type[16];
extern "C" void* sub_4637c0_impl(State*, uint32_t, void*);
extern "C" void* sub_4d4e70_impl(State*, uint32_t, void*);

// BO2_LUA_SRC: a fabricated LuaFile asset (type 41) served by bo2_db_find under
// the reserved name "bo2native.lua". execlua's loader (sub_005d2dc0 →
// sub_4998e0) LOWERCASES the requested name and resolves it through
// DB_FindXAssetHeader(type=0x29, name, 0, 0) — measured, not guessed: 0x4998e0
// is tolower-into-a-0x400-buffer then `push 0;push 0;push buf;push 0x29;
// call 0x4637c0`. The header it returns is consumed by the stream opener
// 0x55cb60, which reads exactly {len@+4, buffer@+8} and returns the buffer —
// so the whole asset is three dwords: {name, len, buffer}. Since we ARE
// DB_FindXAssetHeader (bo2_db_find is patched over it), serving one fabricated
// header turns execlua into an arbitrary-script console: host file → guest
// buffer → the game's own compiler (0x8b5a70's source path, alive in .rdata
// and in code) → lua_pcall.
static uint32_t g_bo2_luafile_va = 0;
// The frontend Lua state's allocator function pointer, learned at console time
// (see bo2_lua_console). Non-zero enables the [LUA-ALLOC] probe in the indirect
// dispatcher — the allocator is reached through `call ecx`, so the shim sees it.
uint32_t g_bo2_lua_allocf = 0;
// A ONE-SHOT lua_Reader for the fabricated asset, live only while the console's
// load is in flight. WHY IT IS NEEDED: the shipped luafiles are all PRECOMPILED
// (they start with 0x1b and take 0x8b5a70's bytecode branch, which consumes the
// opener's buffer whole and never reads again). Our SOURCE text takes the other
// branch, which drives an incremental reader — and the engine's reader
// (0x622730) is backed by a real streamed file we do not have, so with no
// stream it hands back a static 4-byte buffer FOREVER and the lexer never sees
// EOF. Measured: 7366 allocator calls / 7.7 MB / repeated 32768-byte requests
// for a 25-byte script, ending in "LUI: Out of memory". A correct one-shot
// reader returns the whole buffer once and EOF after; that is what this is.
// Both readers in the chain share the signature (L, ud, size_t* out).
uint32_t g_bo2_lua_reader_buf = 0, g_bo2_lua_reader_len = 0;
bool     g_bo2_lua_loading = false, g_bo2_lua_reader_done = false;

// Fresh full-link a GSC script by name, from the shim, via fabricated cdecl frames:
// DB_FindXAssetHeader(type=48, name) → header; then FUN_004d4e70(ns=0, [header+8]).
// Used to PRE-LINK war_room_util.gsc before frontend_sf_a.gsc processes its imports —
// so holo_table_feature_prop's export is registered (under war_room_util's fresh id)
// and frontend_sf_a's import resolves normally instead of erroring. Returns the
// FUN_004d4e70 result (0 = full-linked, 1 = was already loaded, -1 = bad magic), or
// -2 if the asset wasn't found. Reuses a scratch guest page for the name.
static uint32_t g_last_linked_script = 0;
static int bo2_force_link_script(State* s, void* mem, const char* name) {
    const uint32_t scratch = 0x30002000u;
    int i = 0; for (; name[i]; i++) win32_mem_write8(scratch + (uint32_t)i, (uint8_t)name[i]);
    win32_mem_write8(scratch + (uint32_t)i, 0);
    uint32_t se = s->gpr.rsp.dword;
    // DB_FindXAssetHeader(type=48, name=scratch, flag=1, timeout=0): args at [esp+4..0x10].
    uint32_t ne = (se - 0x120) & ~0xFu;
    win32_mem_write32(ne + 0, 0x4637c9u);         // plausible return addr
    win32_mem_write32(ne + 4, 48u);
    win32_mem_write32(ne + 8, scratch);
    win32_mem_write32(ne + 0xc, 1u);
    win32_mem_write32(ne + 0x10, 0u);
    s->gpr.rsp.dword = ne;
    sub_4637c0_impl(s, 0x4637c0u, mem);
    uint32_t hdr = s->gpr.rax.dword;
    s->gpr.rsp.dword = se;
    if (!hdr) return -2;
    uint32_t scriptPtr = win32_mem_read32(hdr + 8);
    // Clear any stale loaded-list entry (0x2ec42e8, stride 0x28, count [0x2edb218] for
    // ns0) so FUN_004d4e70 does a FULL link (→ FUN_004018a0 registers exports) instead of
    // skipping it as already-loaded.
    { uint32_t cnt = win32_mem_read32(0x2edb218u);
      for (uint32_t k = 0; k < cnt && k < 8000; k++) {
          uint32_t e = 0x2ec42e8u + k * 0x28u;
          if (win32_mem_read32(e) == scriptPtr) { win32_mem_write32(e, 0); win32_mem_write32(e + 4, 0); }
      } }
    uint32_t ne2 = (se - 0x120) & ~0xFu;
    win32_mem_write32(ne2 + 0, 0x4d4eedu);
    win32_mem_write32(ne2 + 4, 0u);               // ns = 0
    win32_mem_write32(ne2 + 8, scriptPtr);
    s->gpr.rsp.dword = ne2;
    sub_4d4e70_impl(s, 0x4d4e70u, mem);
    int rv = (int)s->gpr.rax.dword;
    s->gpr.rsp.dword = se;
    fprintf(stderr, "[PRELINK] \"%s\" hdr=0x%08x scriptPtr=0x%08x magic=0x%08x ret=%d\n",
            name, hdr, scriptPtr, win32_mem_read32(scriptPtr), rv);
    g_last_linked_script = scriptPtr;
    return rv;
}

// RUN A SCRIPT'S `main`. Recipe taken verbatim from the engine's own autoexec
// walker 0x6631c0, which is the only thing in the campaign that ever enters the
// VM (19 of the 32 entries):
//
//     eax = [edi]            ; export's bytecode offset, relative to the script
//     push 0                 ; 3rd arg
//     add eax, esi           ; esi = scriptPtr -> absolute bytecode pointer
//     push eax               ; 2nd arg
//     push ebx               ; 1st arg = namespace index
//     call 0x469b20          ; -> thread id in AX
//     movzx eax, ax ; push eax ; push ebx ; call 0x62b240   ; release the handle
//
// Export table: base = [scriptPtr+0x1c] + scriptPtr + 4, count = word
// [scriptPtr+0x34], stride 0xc, [rec+0] = bytecode offset, [rec+7] bit 1 = the
// autoexec flag (which is why `main` is NOT run by the walker — it is not marked
// autoexec; the engine calls it explicitly during a real level change, and a real
// level change is exactly what never happens here).
// Plain lifted symbols, not _impl copies: neither is interposed, so the _impl
// names do not exist and only lifted.o's originals can be called.
extern "C" void* sub_600e60(State*, uint32_t, void*);
// 0x469b20 IS interposed (bo2_vm_enter), so its real body is the _impl copy —
// declared further down the file, hence this forward declaration.
extern "C" void* sub_469b20_impl(State*, uint32_t, void*);
static int bo2_exec_script_main(State* s, void* mem, uint32_t scriptPtr,
                                const char* fname, uint32_t ns) {
    if (!scriptPtr) return -1;
    const uint32_t se = s->gpr.rsp.dword;
    // SL_GetString(name) -> the 16-bit id the export table stores.
    const uint32_t scratch = 0x30003000u;
    int i = 0; for (; fname[i]; i++) win32_mem_write8(scratch + (uint32_t)i, (uint8_t)fname[i]);
    win32_mem_write8(scratch + (uint32_t)i, 0);
    // ⚠️ FIND, DO NOT ADD. The first version called 0x600e60, which is
    //     mov eax,[esp+4]; push 1; push eax; call 0x50ac90
    // and 0x50ac90 IGNORES its second argument, hardcoding 1 into
    //     0x64d340(str, 1, strlen+1, 6)
    // — the ADD flag. So every call interned a NEW canonical string and returned
    // a fresh high id: 0x5dfe in one run and 0x6578 in the next for the SAME
    // name, while this script's 21 export ids are stable and small (0x0058 ..
    // 0x08a3). A freshly added id can never match an id assigned at script load,
    // so the lookup could not succeed in any run. Measured across two runs; the
    // instability is what gave it away.
    //
    // Calling 0x64d340 directly with the flag CLEARED asks it to find without
    // interning. If the name is present the id comes back small and stable; if
    // it is absent the answer is 0, which is itself the fact worth having.
    extern void* sub_64d340(State*, uint32_t, void*);
    uint32_t slen = 0; while (fname[slen]) slen++;
    uint32_t ne = (se - 0x80) & ~0xFu;
    win32_mem_write32(ne + 0x0, 0x5b2681u);      // plausible return addr
    win32_mem_write32(ne + 0x4, scratch);        // const char* str
    win32_mem_write32(ne + 0x8, 0u);             // add flag: 0 = FIND ONLY
    win32_mem_write32(ne + 0xc, slen + 1u);      // length incl. NUL
    win32_mem_write32(ne + 0x10, 6u);            // pool, as 0x50ac90 passes
    s->gpr.rsp.dword = ne;
    sub_64d340(s, 0x64d340u, mem);
    const uint32_t want_id = s->gpr.rax.dword & 0xffffu;
    s->gpr.rsp.dword = se;
    fprintf(stderr, "[LEVEL-MAIN] find-only id for \"%s\" = 0x%04x%s\n",
            fname, want_id,
            want_id ? "" : "  ⚠️  ZERO — the name is not a canonical string, so it "
                           "is not an export of ANY loaded script under that spelling");

    const uint32_t tbl = win32_mem_read32(scriptPtr + 0x1c) + scriptPtr + 4;
    const uint32_t cnt = win32_mem_read32(scriptPtr + 0x34) & 0xffffu;
    fprintf(stderr, "[LEVEL-MAIN] script=0x%08x exports=%u \"%s\" id=0x%04x\n",
            scriptPtr, cnt, fname, want_id);
    if (!cnt) {
        // The offsets came from the autoexec walker (esi = the loaded-list entry's
        // scriptPtr, table at [esi+0x1c]+esi+4, count word[esi+0x34]). Reading 0
        // means this script's header does not sit where that assumed, so print it
        // instead of guessing again.
        fprintf(stderr, "[LEVEL-MAIN]   header dwords:");
        for (uint32_t o = 0; o < 0x40; o += 4)
            fprintf(stderr, " +%02x=%08x", o, win32_mem_read32(scriptPtr + o));
        fprintf(stderr, "\n");
        // ...and what the ENGINE has in its loaded list for ns0, which is what the
        // walker actually iterates.
        uint32_t lc = win32_mem_read32(0x2edb218u);
        fprintf(stderr, "[LEVEL-MAIN]   ns0 loaded count=%u; entries with our ptr:", lc);
        for (uint32_t k = 0; k < lc && k < 4000; k++) {
            uint32_t ee = 0x2ec42e8u + k * 0x28u;
            uint32_t sp = win32_mem_read32(ee);
            if (sp == scriptPtr)
                fprintf(stderr, " [%u]@0x%08x cnt34=%u off1c=0x%x", k, ee,
                        win32_mem_read32(sp + 0x34) & 0xffffu,
                        win32_mem_read32(sp + 0x1c));
        }
        fprintf(stderr, "\n");
    }
    for (uint32_t k = 0; k < cnt && k < 4096; k++) {
        const uint32_t rec = tbl + k * 0xcu;
        const uint32_t nid = win32_mem_read32(rec + 4) & 0xffffu;
        if (nid != want_id) continue;
        const uint32_t off = win32_mem_read32(rec);
        fprintf(stderr, "[LEVEL-MAIN] found export %u: offset=0x%x flags=0x%02x — running\n",
                k, off, win32_mem_read8(rec + 7));
        uint32_t n2 = (se - 0x80) & ~0xFu;
        win32_mem_write32(n2 + 0, 0x663216u);    // the walker's own return addr
        win32_mem_write32(n2 + 4, ns);
        win32_mem_write32(n2 + 8, scriptPtr + off);
        win32_mem_write32(n2 + 0xc, 0u);
        s->gpr.rsp.dword = n2;
        sub_469b20_impl(s, 0x469b20u, mem);
        const uint32_t tid = s->gpr.rax.dword & 0xffffu;
        s->gpr.rsp.dword = se;
        fprintf(stderr, "[LEVEL-MAIN] Scr_ExecThread -> thread 0x%04x\n", tid);
        return (int)tid;
    }
    // ⚠️ LIST WHAT IS ACTUALLY THERE. "no export named X" with 21 exports present
    // is not an answer, it is a prompt: either the name is in another script or
    // the id we computed is not the id the table stores. Printing the table
    // settles which, and costs one line per export.
    fprintf(stderr, "[LEVEL-MAIN] no export named \"%s\" (id=0x%04x) among %u exports; "
                    "the table holds:\n", fname, want_id, cnt);
    // ── NAME THE EXPORTS ────────────────────────────────────────────────────
    // Canonical strings live in the MT allocator's node pool: 0x64d340 hashes the
    // text, indexes a bucket table at [0xbf0f00] (8 bytes/bucket), and reaches a
    // 24-byte record at [0x2d43da4] + idx*24 — the same 0x2d43da4 MT_Init sets up.
    // So an export's nameid IS an index into that pool, which is why ids run to
    // 0x27a3 and 0x5dfe rather than being small per-script numbers (that
    // hypothesis is dead: maps/_load_common.gsc's 86 exports start at 0x27a3).
    //
    // Dump each record and any ASCII reachable from its dwords. Printed rather
    // than parsed into a assumed layout — guessing a header shape is how this
    // file has been wrong before, and the bytes settle it either way.
    const uint32_t pool = win32_mem_read32(0x2d43da4u);
    fprintf(stderr, "[LEVEL-MAIN]   (string pool base [0x2d43da4] = 0x%08x, 24-byte records)\n",
            pool);
    for (uint32_t k = 0; k < cnt && k < 64; k++) {
        const uint32_t rec = tbl + k * 0xcu;
        const uint32_t nid = win32_mem_read32(rec + 4) & 0xffffu;
        char txt[64]; txt[0] = 0;
        if (pool) {
            const uint32_t node = pool + nid * 24u;
            for (uint32_t f = 0; f < 24 && !txt[0]; f += 4) {
                const uint32_t cand = win32_mem_read32(node + f);
                if (cand < 0x1000u || cand >= 0xF0000000u) continue;
                int n = 0;
                while (n < 60) { uint8_t c = win32_mem_read8(cand + (uint32_t)n);
                                 if (c < 0x20 || c > 0x7e) break; txt[n++] = (char)c; }
                txt[n] = 0;
                if (n < 3) txt[0] = 0;           // not text, keep looking
            }
        }
        fprintf(stderr, "[LEVEL-MAIN]   [%2u] nameid=0x%04x offset=0x%06x flags=0x%02x  %s\n",
                k, nid, win32_mem_read32(rec), win32_mem_read8(rec + 7),
                txt[0] ? txt : "(no ascii reachable from its record)");
    }
    return -2;
}
// ── BO2_EXEC_SCRIPT=<name-substr>:<export> — RUN AN EXPORT OF A SCRIPT THAT IS
//    ALREADY LOADED, FOUND BY NAME ───────────────────────────────────────────
//
// WHY, and why the existing lever could not do it. BO2_LEVEL_SCRIPT force-links
// by asset name and then runs an export of whatever `bo2_force_link_script` last
// produced. Pointed at maps/_callbacksetup it reported success and handed back a
// script with ZERO exports whose header is a run of 0x57 bytes — not that script
// at all. Its gate is also `load-completes >= 900` while angola's counter tops
// out at 728..791, varying run to run, so on this level it could never fire.
//
// The script we need is already resident: the GSC ring resolves the parked
// thread to "maps/_callbacksetup.gsc" by walking the loaded lists (0x2ec42e8 +
// ns*0x4e20, stride 0x28, [+0]=scriptPtr; counts at 0x2edb218 + ns*4) and
// reading ASCII out of the first 0x80 bytes of the blob. Same walk here, matched
// on a substring, then bo2_exec_script_main on the entry that actually matched.
//
// ⚠️ THIS IS A TEST INSTRUMENT, NOT A FIX. It exists to answer one question —
// does invoking CodeCallback_StartGameType by hand release the wait that
// maps/_callbacksetup.gsc is parked in? A yes names the missing engine event; it
// does not make the engine fire it.
static bool bo2_exec_in_loaded_script(State* s, void* mem,
                                      const char* want, const char* fname) {
    for (int ns = 0; ns < 4; ns++) {
        const uint32_t cnt = win32_mem_read32(0x2edb218u + 4u * (uint32_t)ns);
        if (cnt > 4000u) continue;
        for (uint32_t k = 0; k < cnt; k++) {
            const uint32_t sp = win32_mem_read32(0x2ec42e8u + (uint32_t)ns * 0x4e20u
                                                            + k * 0x28u);
            if (!sp) continue;
            char nm[96]; int n = 0;
            for (uint32_t o = 0; o < 0x80 && n < 90; o++) {
                const uint8_t c = win32_mem_read8(sp + o);
                if (c >= 0x20 && c <= 0x7e) nm[n++] = (char)c;
                else if (n > 6) break;
                else n = 0;
            }
            nm[n] = 0;
            if (n <= 6 || !std::strstr(nm, want)) continue;
            fprintf(stderr, "[EXEC-SCRIPT] matched ns%d entry %u at 0x%08x \"%s\" — "
                            "running \"%s\"\n", ns, k, sp, nm, fname);
            const int rc = bo2_exec_script_main(s, mem, sp, fname, (uint32_t)ns);
            fprintf(stderr, "[EXEC-SCRIPT] -> %d%s\n", rc,
                    rc >= 0 ? "" : "  (negative: see [LEVEL-MAIN] above for why)");
            return rc >= 0;
        }
    }
    fprintf(stderr, "[EXEC-SCRIPT] ⚠️  no LOADED script matched \"%s\" — it is not "
                    "resident under that name, so silence from it means nothing\n", want);
    return false;
}

extern "C" bool bo2_exec_in_loaded_script_fwd(State* s, void* mem,
                                             const char* want, const char* fname) {
    return bo2_exec_in_loaded_script(s, mem, want, fname);
}

extern "C" __attribute__((used)) void* bo2_db_find(State* s, uint32_t pc, void* mem) {
    // DB_FindXAssetHeader(type=arg0=[esp+4], name=arg1=[esp+8], flag=arg2, timeout=arg3=[esp+0x10]).
    uint32_t esp = s->gpr.rsp.dword;
    uint32_t type   = win32_mem_read32(esp + 4);
    uint32_t namep  = win32_mem_read32(esp + 8);
    uint32_t timeout = win32_mem_read32(esp + 0x10);
    // BO2_DB_FIND=<substr> — log every asset the engine LOOKS UP whose name
    // contains <substr>, once per distinct name plus a repeat tally. The whole
    // question "is ui/t6/mainmenu.lua ever asked for?" runs through this one
    // function, which is already interposed, so it costs nothing to answer.
    // Count, don't cap: a name that is only requested late must not fall off the
    // end of a budget the way [DB-LOADXFILE] did.
    {
        static const char* filt = bo2_getenv("BO2_DB_FIND");
        if (filt) {
            char nm[96]; int n = 0;
            while (n < 95) { uint8_t c = win32_mem_read8(namep + n);
                             if (c < 0x20 || c > 0x7e) break; nm[n++] = (char)c; }
            nm[n] = 0;
            if (n && (!*filt || std::strstr(nm, filt))) {
                static std::unordered_map<std::string, uint32_t> seen;
                uint32_t& c = seen[nm];
                if (c++ == 0)
                    fprintf(stderr, "[DB-FIND] type=%u \"%s\" (%zu distinct)\n",
                            type, nm, seen.size());
                else if ((c % 200) == 0)
                    fprintf(stderr, "[DB-FIND] \"%s\" x%u\n", nm, c);
            }
        }
    }
    // Serve the fabricated BO2_LUA_SRC asset (see g_bo2_luafile_va above). One
    // global test on the hot path; the name compare only runs for luafile
    // lookups while the fabricated asset exists.
    if (type == 41u && g_bo2_luafile_va) {
        char nm[32]; int n = 0;
        while (n < 31) { uint8_t c = win32_mem_read8(namep + n); if (!c) break; nm[n++] = (char)c; }
        nm[n] = 0;
        if (std::strcmp(nm, "bo2native.lua") == 0) {
            fprintf(stderr, "[BO2-LUA] serving fabricated luafile asset 0x%08x\n", g_bo2_luafile_va);
            s->gpr.rax.dword = g_bo2_luafile_va;
            s->gpr.rsp.dword += 4;                       // cdecl ret
            return mem;
        }
    }
    // EXPERIMENT: no DB_FindXAssetHeader wait is infinite. Present assets are found
    // before the wait (timeout irrelevant); genuinely-missing ones give up now and
    // take the game's own default-asset path (0x4639f2+). Tests whether an infinite
    // DB wait is what stalls tid0's init before the menu frame loop starts.
    // Break the infinite precache waits that never resolve in our port (config
    // files, streaming_temp_image_*, video materials, fx, models absent from every
    // loaded zone) so tid0's init proceeds — BUT leave the MAP-family waits
    // (col_map/com_map/game_map/map_ents/gfx_map, types 11-17) infinite: those DO
    // register once the frontend zone finishes streaming, and the map-load legitimately
    // waits for them (clamping them gives "Couldn't find the bsp"). record the
    // last infinite wait per thread for diagnosis.
    if (timeout == 0xFFFFFFFFu) {
        int tid = win32_current_tid();
        if (tid >= 0 && tid < 16) {
            char* d = g_db_last_inf[tid];
            int nn = 0; while (nn < 63) { uint8_t c = win32_mem_read8(namep + nn); if (c < 0x20 || c > 0x7e) break; d[nn++] = (char)c; } d[nn] = 0;
            g_db_last_inf_type[tid] = type;
        }
        // A give-up is DESTRUCTIVE, not merely a "return null": DB_FindXAssetHeader's
        // timeout path (0x4639a8 → DB_LinkXAssetEntry @0x463a85) PERMANENTLY registers
        // g_defaultAssetName[type] (0xbd47a8[type]) under the REQUESTED name, so the real
        // asset can never be seen again even after its zone streams in. So only clamp
        // types whose assets genuinely never arrive in our port. NEVER clamp:
        //   - the map family (11-17): col_map/gfx_map arrive when the zone streams
        //     (clamping them gave "Couldn't find the bsp for this map").
        //   - scriptparsetree (48): scripts arrive with their zone. frontend_sf_a.gsc is
        //     registered mid-walk and immediately VM-linked, so its imports are looked up
        //     BEFORE the rest of frontend.ff has streamed. Clamping burned
        //     `common_scripts/default` (87 bytes) into exactly the 7 scripts it imports —
        //     war_room_util, frontend_sf_b/_sf_c/_anim/_amb/_fx, createart/frontend_art —
        //     which is precisely why holo_table_feature_prop was "Unresolved external".
        //
        // 🎯 2026-08-16: TYPE 25 (WEAPON) BELONGS ON THIS LIST, and leaving it off
        // is measurable in every angola run:
        //
        //     109392  [ASSERT] "unknown weapon 'emp_grenade_sp'"
        //     109485  [DB-FIND] type=25 "emp_grenade_sp"
        //     109587  [DB-LOADXFILE] name="weapons!emp_grenade_sp"   <- 195 lines LATER
        //     111471  [ASSERT] "undefined is not an array, string, or vector"
        //
        // The weapon is not missing, it is LATE — it arrives with its zone exactly
        // like the map and script families already excluded here. Clamping its
        // wait to 0 makes the mission script receive `undefined` and then use it
        // as an array, which is the second assert, one screenful later.
        //
        // ⚠️ The clamp exists for a real reason (assets that NEVER arrive made
        // tid0's init wait forever and the menu never drew), so this is a flag,
        // not a silent behaviour change: BO2_ASSET_WAIT_TYPES=<csv> adds types to
        // the do-not-clamp set, and the run that measures it is the A/B.
        static const uint32_t* s_extra = [] {
            static uint32_t v[16] = {0};
            const char* e = bo2_getenv("BO2_ASSET_WAIT_TYPES");
            if (e) { int n = 0; while (*e && n < 15) {
                         if (*e >= '0' && *e <= '9') { v[n] = (uint32_t)strtoul(e, (char**)&e, 10); n++; }
                         else ++e; } }
            return v;
        }();
        // 🎯 P650 — LE CLAMP EST DESARME PAR DEFAUT (regle 7, zero garde).
        //
        // Serie p649 : « unknown weapon '%s' » 6/6 runs. precacheitem (0x86cd70)
        // cherche le type 25 avec waitTime=-1 (0x72bfe0 -> 0x4637c0), mais ce
        // clamp le ramenait a 0 ; les zones `weapons!*` sont dans le MEME lot que
        // angola (Com_LoadLevelFastFiles 0x4d6220) et rien ne retient le script
        // de niveau apres elles. Avant C3 (Sleep reel), le fil Database gagnait la
        // course ; depuis, l'arme arrive apres et le defaut est inscrit a sa place
        // pour toujours (0x463a85). Sous Windows l'attente « infinie » n'est pas un
        // blocage : la boucle sort aussi quand l'evenement « base au repos »
        // (0x10014, [0x2925658]) est signale (0x4638bf / 0x46390a), donc un asset
        // vraiment absent se resout en defaut a la fin du lot, pas avant.
        // BO2_DB_CLAMP=1 rearme l'ancien comportement (A/B seulement).
        static const bool s_clamp = [] {
            const char* e = bo2_getenv("BO2_DB_CLAMP");
            return e && atoi(e) != 0;
        }();
        if (!s_clamp) {
            static uint64_t s_nc = 0;
            static uint64_t s_types = 0;
            const uint64_t k = ++s_nc;
            const uint64_t bit = type < 64u ? (1ull << type) : 0ull;
            if ((k & (k - 1)) == 0 || (bit && !(s_types & bit))) {
                s_types |= bit;
                char nm[64]; int n = 0;
                while (n < 63) { uint8_t c = win32_mem_read8(namep + n);
                                 if (c < 0x20 || c > 0x7e) break; nm[n++] = (char)c; }
                nm[n] = 0;
                fprintf(stderr, "[DB-NOCLAMP #%llu] tid=%d type=%u \"%s\" attente du jeu conservee\n",
                        (unsigned long long)k, win32_current_tid(), type, nm);
            }
        }
        bool arrives_with_zone = !s_clamp || (type >= 11u && type <= 17u) || type == 48u;
        for (int k = 0; k < 16 && s_extra[k]; k++)
            if (s_extra[k] == type) arrives_with_zone = true;
        // 🎯 BO2_ASSET_WAIT_MS=<n> — GIVE THE LATE ONES A CHANCE, BOUNDED.
        //
        // [CLAMP-VERDICT] measured that 128 of the 200 assets we starve are
        // RESIDENT later: they were never missing, only late. But the type cannot
        // be whitelisted, because the same type holds both — 96 of 112 materials
        // arrive and 16 never do — so restoring an infinite wait would reinstate
        // the original hang for those 16.
        //
        // The engine already has the answer. At 0x463978 a timeout of -1 loops
        // forever; anything else is compared against elapsed MILLISECONDS
        // (0x46398c: clock, subtract the start, `cmp eax, ebx / jge` gives up).
        // So a finite value gets both: the late ones are found, the absent ones
        // give up on their own.
        //
        // ⚠️ Bounded twice over. A name that has ALREADY timed out once is
        // clamped to 0 from then on, so a genuinely absent asset costs the wait
        // exactly once rather than on every lookup — without that, a per-frame
        // material lookup would pay it forever and turn a fix into a stall.
        static const uint32_t s_wait_ms = [] {
            const char* e = bo2_getenv("BO2_ASSET_WAIT_MS");
            return e ? (uint32_t)strtoul(e, nullptr, 0) : 0u;
        }();
        if (!arrives_with_zone) {
            uint32_t give = 0;
            if (s_wait_ms) {
                char nm2[80]; int n2 = 0;
                while (n2 < 79) { uint8_t c = win32_mem_read8(namep + n2);
                                  if (c < 0x20 || c > 0x7e) break; nm2[n2++] = (char)c; }
                nm2[n2] = 0;
                static std::set<std::string> s_expired;
                char k2[96]; snprintf(k2, sizeof k2, "%u:%s", type, nm2);
                if (!s_expired.count(k2)) {
                    give = s_wait_ms;
                    s_expired.insert(k2);      // one paid wait per distinct name
                }
            }
            win32_mem_write32(esp + 0x10, give);
            if (give) {
                static uint32_t ngrant = 0;
                if (++ngrant <= 12)
                    fprintf(stderr, "[DB-WAIT] type=%u granted %u ms instead of giving up "
                                    "immediately (grant #%u)\n", type, give, ngrant);
            }
            // 🎯 NAME EVERY CLAMP. Removing a wait is invisible by construction —
            // the engine simply reports "unknown <thing>" a moment before the
            // asset lands, and that is how `emp_grenade_sp` hid for 13 runs. One
            // line per distinct (type, name), plus a per-type tally, turns "which
            // assets are we starving?" into a list instead of an investigation.
            extern std::vector<std::pair<uint32_t,std::string>> g_clamped_assets;
            static std::unordered_map<std::string, uint32_t> seen;
            static uint32_t per_type[64] = {0};
            char nm[80]; int n = 0;
            while (n < 79) { uint8_t c = win32_mem_read8(namep + n);
                             if (c < 0x20 || c > 0x7e) break; nm[n++] = (char)c; }
            nm[n] = 0;
            char key[96]; snprintf(key, sizeof key, "%u:%s", type, nm);
            if (seen[key]++ == 0 && seen.size() <= 200) {
                if (type < 64) ++per_type[type];
                // ⚠️ Only count it as STARVED if it really got zero wait.
                // With BO2_ASSET_WAIT_MS set, a lookup that was granted a delay
                // has not been starved, and recording it anyway made the verdict
                // report the same 128 whatever the flag did — a probe measuring
                // its own pre-fix state.
                if (give == 0 && g_clamped_assets.size() < 400)
                    g_clamped_assets.emplace_back(type, std::string(nm));
                fprintf(stderr, "[DB-CLAMP] type=%u \"%s\" — its infinite wait was "
                                "removed (%zu distinct so far)\n", type, nm, seen.size());
            }
        }
    }
    // Diagnostic + FIX: the GSC import linker (FUN_004d3510) looks up each import's
    // DEFINING script via DB_FindXAssetHeader(type=48, "maps/<script>.gsc"). It FINDS
    // war_room_util.gsc (the holo_table_feature_prop definer) but never actually VM-LINKS
    // it (FUN_004d4e70 is never called for it), so its exports never register → the
    // resolve fails and the linker RETRY-LOOPS. FIX: when a type-48 lookup for a script
    // named in BO2_FORCE_LINK (comma-list of substrings) is found, force VM-link it once
    // by calling FUN_004d4e70(ns=0, scriptPtr=[header+8]) with a fabricated cdecl frame —
    // registering its exports so subsequent resolves succeed. Gated BO2_FORCE_LINK.
    if (type == 48u) {
        static const char* s_fl = bo2_getenv("BO2_FORCE_LINK");
        static bool s_lookup_log = bo2_getenv("BO2_GSC_SCRIPT_LOOKUP") != nullptr;
        char snm[96]; int sn = 0;
        while (sn < 95) { uint8_t c = win32_mem_read8(namep + sn); if (c < 0x20 || c > 0x7e) break; snm[sn++] = (char)c; } snm[sn] = 0;
        void* rr = sub_4637c0_impl(s, pc, mem);
        uint32_t hdr = s->gpr.rax.dword;
        if (s_lookup_log) {
            static int c = 0;
            bool rel = std::strstr(snm, "war_room") || std::strstr(snm, "frontend") || std::strstr(snm, "holo");
            if (rel || c++ < 40) fprintf(stderr, "[GSC-SCRIPT-LOOKUP] type48 \"%s\" -> header=0x%08x\n", snm, hdr);
        }
        // PRE-LINK: when the anchor script (default frontend_sf_a) is looked up — i.e.
        // BEFORE it processes its imports — fresh full-link the dependency scripts in
        // BO2_PRELINK (comma-list, default maps/war_room_util.gsc) so their exports (incl.
        // holo_table_feature_prop) register first and the anchor's imports resolve cleanly.
        static const char* s_prelink = bo2_getenv("BO2_PRELINK");
        static const char* s_pl_at = [] { const char* a = bo2_getenv("BO2_PRELINK_AT"); return a ? a : "frontend_sf_a"; }();
        static bool s_pl_done = false;
        if (s_prelink && *s_prelink && !s_pl_done && std::strstr(snm, s_pl_at)) {
            s_pl_done = true;
            const char* p = s_prelink; char tok[96];
            while (*p) {
                int k = 0; while (*p && *p != ',' && k < 95) tok[k++] = *p++; tok[k] = 0; if (*p == ',') p++;
                if (k) bo2_force_link_script(s, mem, tok);
            }
            s->gpr.rax.dword = hdr;   // restore the anchor lookup's result
        }
        if (s_fl && *s_fl && hdr) {
            // match snm against any comma-separated substring in s_fl, once per script
            static std::unordered_map<uint32_t, bool> s_linked;
            bool want = false; { const char* p = s_fl; char tok[64];
                while (*p) { int k = 0; while (*p && *p != ',' && k < 63) tok[k++] = *p++; tok[k] = 0; if (*p == ',') p++;
                             if (k && std::strstr(snm, tok)) { want = true; break; } } }
            if (want && !s_linked[hdr]) {
                s_linked[hdr] = true;
                uint32_t scriptPtr = win32_mem_read32(hdr + 8);
                uint32_t magic = win32_mem_read32(scriptPtr);
                // FUN_004d4e70 skips already-loaded scripts (loaded-list @0x2ec42e8,
                // stride 0x28, [+0]=[+4]=scriptPtr, count [0x2edb218] for ns0) WITHOUT
                // registering exports. war_room_util is in that list but its exports
                // aren't registered, so clear its entry to force a FULL re-link
                // (→ FUN_004018a0 registers exports). Optionally gated: BO2_FORCE_CLEAR.
                int cleared = 0;
                if (bo2_getenv("BO2_FORCE_CLEAR")) {
                    uint32_t cnt = win32_mem_read32(0x2edb218u);
                    for (uint32_t k = 0; k < cnt && k < 4000; k++) {
                        uint32_t e = 0x2ec42e8u + k * 0x28u;
                        if (win32_mem_read32(e) == scriptPtr) {
                            win32_mem_write32(e, 0); win32_mem_write32(e + 4, 0); cleared++;
                        }
                    }
                }
                uint32_t se = s->gpr.rsp.dword, ne = (se - 0x100) & ~0xFu;
                win32_mem_write32(ne + 0, 0x4d4eedu);   // plausible in-linker return addr
                win32_mem_write32(ne + 4, 0);            // ns = 0
                win32_mem_write32(ne + 8, scriptPtr);    // scriptPtr = [header+8]
                s->gpr.rsp.dword = ne;
                extern void* sub_4d4e70_impl(State*, uint32_t, void*);
                sub_4d4e70_impl(s, 0x4d4e70u, mem);
                int32_t rv = (int32_t)s->gpr.rax.dword;
                s->gpr.rsp.dword = se;
                s->gpr.rax.dword = hdr;                  // restore DB_FindXAssetHeader's result
                fprintf(stderr, "[FORCE-LINK] \"%s\" scriptPtr=0x%08x magic=0x%08x cleared=%d ret=%d\n",
                        snm, scriptPtr, magic, cleared, rv);
            }
        }
        return rr;
    }
    return sub_4637c0_impl(s, pc, mem);
}

// --- Interpose Com_Error (FUN_00444650; cdecl varargs Com_Error(level=arg0,
// fmt=arg1, ...)). Its fatal tail longjmps to the Com_Frame setjmp (0x63feff).
// The GSC loader calls Com_Error(0, "**** %d script error(s):\n%s", ...) when a
// script has unresolved externals (e.g. holo_table_feature_prop in
// maps/frontend_sf_a.gsc) — FATAL, so the frontend load aborts before LUI draws.
// Make ONLY that specific message non-fatal (return; cdecl caller cleans args) so
// the load continues past the missing 3D-scene function — a test of whether the
// 2D LUI menu then submits draws. Every other Com_Error keeps its real behavior.
extern "C" void* sub_444650_impl(State*, uint32_t, void*);
extern "C" __attribute__((used)) void* bo2_com_error(State* s, uint32_t pc, void* mem) {
    uint32_t esp = s->gpr.rsp.dword;
    uint32_t level = win32_mem_read32(esp + 4);
    // Scan fmt (arg1) + the first two varargs (arg2/arg3) as potential message
    // strings — the load-time error passes the text as the fmt ("**** %d script
    // error(s)"), the VM terminal error passes it as a "%s" arg ("Terminal script
    // error"). Match either so BOTH GSC error paths become non-fatal.
    auto rdstr = [&](uint32_t p, char* out) { int n = 0; while (n < 79) { uint8_t c = win32_mem_read8(p + n); if (!c) break; out[n++] = (char)c; } out[n] = 0; };
    char f[80], a2[80], a3[80];
    rdstr(win32_mem_read32(esp + 8), f);
    rdstr(win32_mem_read32(esp + 0xc), a2);
    rdstr(win32_mem_read32(esp + 0x10), a3);
    // This specific error is a named physical-memory stack order check, NOT
    // the MT allocator ledger. The direct call at 0x5ba514 preserves ESI=stack
    // base and EDI=matching slot. Its caller already cleared that slot's name.
    // At this entry, +0x18 is the free function's return address and +0x1c its
    // name argument (three saved registers, two error args, and CALL's return).
    // Read only on the actual error path: no per-store instrumentation tax.
    if (win32_mem_read32(esp) == 0x5ba519u &&
        win32_mem_read32(esp + 8) == 0xaef194u) {
        const uint32_t stack = s->gpr.rsi.dword, slot = s->gpr.rdi.dword;
        char requested[80]; rdstr(win32_mem_read32(esp + 0x1cu), requested);
        fprintf(stderr, "[PHYS-FREE-ERROR] name=\"%s\" caller=0x%08x stack=0x%08x "
                        "slot=%u tid=%d\n", requested, win32_mem_read32(esp + 0x18u),
                stack, slot, win32_current_tid());
        if (stack == 0x2b21f5cu || stack == 0x2b221e8u) {
            const uint32_t count = win32_mem_read32(stack);
            fprintf(stderr, "[PHYS-FREE-ERROR] count=%u cursor=0x%08x "
                            "matched slot was cleared before Com_Error\n",
                    count, win32_mem_read32(stack + 4));
            for (uint32_t i = 0; i < count && i < 80; ++i) {
                const uint32_t name = win32_mem_read32(stack + 8 + i * 8);
                char label[80]; rdstr(name, label);
                fprintf(stderr, "[PHYS-FREE-ERROR] slot=%u nameptr=0x%08x name=\"%s\" "
                                "saved_cursor=0x%08x%s\n", i, name, label,
                        win32_mem_read32(stack + 12 + i * 8), i == slot ? " MATCH" : "");
            }
            if (count > 80) fprintf(stderr, "[PHYS-FREE-ERROR] invalid count; dump bounded at 80\n");
        } else {
            fprintf(stderr, "[PHYS-FREE-ERROR] unexpected stack base; no table read\n");
        }
    }
    auto is_scripterr = [](const char* z) {
        return std::strstr(z, "script error") || std::strstr(z, "script runtime error") ||
               std::strstr(z, "Terminal script");
    };
    // Default: script errors stay FATAL so the build stops at the clear frontier
    // (the frontend scene GSC needs holo_table_feature_prop, which is undefined).
    // BO2_TOLERATE_SCRIPT_ERR=1 makes them non-fatal to EXPLORE the boot cascade
    // beyond — but forcing past them advances into a degraded state (next: the
    // "unknown type 'client' in 'radiant/keys.txt'" init error → ExitProcess), so
    // it never cleanly reaches the menu. Kept as a diagnostic lever, off by default.
    // On the FIRST GSC error (late in load, all zones registered) dump the asset DB
    // once — a good vantage to see whether the built-in images ($white/…) got created.
    if (is_scripterr(f) || is_scripterr(a2) || is_scripterr(a3)) {
        static bool dumped = false;
        if (!dumped) { dumped = true; extern void bo2_dump_asset_db(const char*); bo2_dump_asset_db("gsc-error"); }
        // Runtime GSC error = the undefined holo_table_feature_prop CALL. Dump the
        // opcode ring to identify the CALL_FAR opcode/handler for a no-op fix.
        if (std::strstr(f, "runtime") || std::strstr(a2, "runtime")) {
            static bool rdumped = false;
            if (!rdumped) { rdumped = true; extern void win32_gsc_dump_ring(); win32_gsc_dump_ring(); }
        }
    }
    // 🎯 SAY EVERY Com_Error OUT LOUD, unconditionally. Until now this only
    // logged under BO2_TOLERATE_SCRIPT_ERR and only for script errors, so an
    // ordinary Com_Error passed in silence — and one of them is why angola never
    // ticks: 0x4446fe, inside this very function, does
    //     mov dword[0x287bb30], 1
    // and SV_Frame parks at 0x852b70 sleeping 50 ms at a time for as long as
    // that word is non-zero, never reaching its tick gate. Measured: the word
    // goes 0 -> 1 and stays 1. Com_Error is rare, so this costs nothing.
    {
        static int n = 0;
        if (n++ < 16)
            // 🎯 THE SOUND REGISTRY'S OWN COUNTER, printed with the error that
            // depends on it. sub_59f6e0 — the lookup that fails for the asset
            // named 'default' — opens with `mov eax,[0x2ff2a90]; test eax,eax;
            // je not-found`, so a zero there means NOTHING was ever registered
            // and the search never even ran. That distinguishes "the asset is
            // missing from the zones" from "the registry is empty", which are
            // different bugs with different fixes, and it costs one read.
            // 🎯 THE CHAIN WALK'S BUMP CURSOR, so a bound can be chosen from a
            // measurement instead of a guess. It lives at [inst*0x42a8+0x2f3b8c8]
            // and the sound globals begin at 0x2f49400: if it already reads at or
            // past that, a clamp is the whole fix; if it reads well below, the
            // overrun happens INSIDE one walk (the cursor global is only updated
            // at 0x87e442, after the inner loop) and the bound has to go on the
            // store, not on the global.
            fprintf(stderr, "[CURSOR] inst0 [0x2f3b8c8]=0x%08x  inst1 [0x2f3fb70]=0x%08x "
                    "(sound globals start at 0x2f49400)\n",
                    win32_mem_read32(0x2f3b8c8u), win32_mem_read32(0x2f3b8c8u + 0x42a8u));
            // 🎯 THE SOUND HANDLE ITSELF, when this is the handle check.
            //
            // sub_6518d0 accepts a handle only if (h & 0xfff) <= 0x600, or one of
            // the sentinels 0xfff / 0xffe / bit 0x80000; anything else raises
            // "Invalid sound handle". The handle is in EBX at the raise, and this
            // wrapper already holds the State, so one read says whether the value
            // is in the same small-integer family the chain walk writes (0x3b43,
            // 0x3b47) — i.e. whether this is the SAME corruption one layer deeper,
            // or a genuinely different defect.
            fprintf(stderr, "[SND-HANDLE] ebx=0x%08x (low12=0x%03x, limit 0x600) "
                    "esi=0x%08x edi=0x%08x\n", s->gpr.rbx.dword,
                    s->gpr.rbx.dword & 0xfffu, s->gpr.rsi.dword, s->gpr.rdi.dword);
            // 🎯 WHAT THE 12 REGISTERED LISTS ACTUALLY CONTAIN.
            //
            // sub_59f6e0 walks table[0x2ff2a94], and for each list reads count at
            // +0x18, entries at +0x1c, and compares our id against [record+0x20]
            // over 0x4c-byte records. So the question "is 'default' missing" and
            // the question "are the ids from a different string table" look
            // identical from outside — and this port has a known dual string
            // table (GSC instance 0 vs 1). Printing the ids the lists hold, next
            // to the id we search for, tells them apart in one line.
            {
                const uint32_t n = win32_mem_read32(0x2ff2a90u);
                const uint32_t want = win32_mem_read32(0x2f49448u);
                fprintf(stderr, "\n[SND-LISTS] looking for id 0x%08x across %u list(s):\n", want, n);
                for (uint32_t i = 0; i < n && i < 16u; ++i) {
                    const uint32_t lst = win32_mem_read32(0x2ff2a94u + i * 4u);
                    if (!lst) { fprintf(stderr, "  list[%u] = null\n", i); continue; }
                    const uint32_t cnt = win32_mem_read32(lst + 0x18u);
                    const uint32_t arr = win32_mem_read32(lst + 0x1cu);
                    fprintf(stderr, "  list[%u] @0x%08x count=%u entries=0x%08x  first ids:",
                            i, lst, cnt, arr);
                    for (uint32_t j = 0; j < cnt && j < 6u; ++j)
                        fprintf(stderr, " 0x%08x", win32_mem_read32(arr + j * 0x4cu + 0x20u));
                    fprintf(stderr, "\n");
                }
            }
            fprintf(stderr, "\n[SND-REG] soundalias entries [0x2ff2a90]=%u, "
                    "'default' id [0x2f49448]=0x%08x, armed [0x2f49404]=%u\n",
                    win32_mem_read32(0x2ff2a90u), win32_mem_read32(0x2f49448u),
                    win32_mem_read32(0x2f49404u));
            // Only the variable-exhaustion error licenses a verdict; every other
            // Com_Error gets an unjudged snapshot. `a3` carries the message.
            bo2_varpool_report(strstr(a3, "script variables") ||
                               strstr(a2, "script variables")
                               ? "com-error EXHAUSTION" : "com-error");
            // P734 : « animation '%s' in '%s' cannot be sync looping and nonlooping » est leve par
            // sub_844fa0 (0x845008), qui parcourt l'arbre XAnim : ebp = arbre, edi = index de la
            // feuille, esi = ses XAnimParts, bl = bit loopsync herite. En-tete de 0x14 octets
            // ([+4] = nombre d'entrees), entrees de 16 octets a arbre+0x14 (0x844fb4) : word[+2] =
            // nombre d'enfants, word[+0xc] = drapeaux du noeud (OR des herites, 0x8450b7), word[+0xe]
            // = premier enfant, enfants contigus (0x8450c3) ; feuille : dword[+0xc] = XAnimParts,
            // [parts+0] = nom, byte[parts+0x10] = boucle. P735 : les enfants ne suivent pas l'ordre
            // des indices (noeud 4 -> 3702), donc table des parents, puis chemin racine -> feuille,
            // premier ancetre porteur du bit 0, soeurs de la feuille. BO2_XANIM_DUMP=<fichier> : tout
            // l'arbre, une ligne par entree, pour l'analyse hors ligne.
            if (strstr(f, "sync looping") && n <= 2) {
                const uint32_t arbre = s->gpr.rbp.dword, cible = s->gpr.rdi.dword;
                const uint32_t taille = win32_mem_read32(arbre + 4u);
                auto ent = [arbre](uint32_t i) { return arbre + 0x14u + i * 16u; };
                auto nb_enf = [&](uint32_t i) { return win32_mem_read32(ent(i)) >> 16; };
                auto mot_c = [&](uint32_t i) { return win32_mem_read32(ent(i) + 0xcu); };
                auto nom = [](uint32_t parts) -> std::string {
                    const uint32_t p = parts ? win32_mem_read32(parts) : 0u;
                    std::string r;
                    for (uint32_t k = 0; p && k < 64u; ++k) {
                        const char c = (char)win32_mem_read8(p + k);
                        if (!c) break;
                        r += c;
                    }
                    return r;
                };
                fprintf(stderr, "[XANIM-ARBRE] arbre=0x%08x taille=%u feuille=%u bl=%u entete:", arbre, taille,
                        cible, s->gpr.rbx.dword & 0xffu);
                for (uint32_t k = 0; k < 0x14u; k += 4u) fprintf(stderr, " %08x", win32_mem_read32(arbre + k));
                fprintf(stderr, "\n");
                if (taille && taille <= 0x10000u && cible < taille) {
                    std::vector<uint32_t> pere(taille, 0xffffffffu);
                    for (uint32_t i = 0; i < taille; ++i) {
                        const uint32_t nb = nb_enf(i), prem = mot_c(i) >> 16;
                        for (uint32_t c = 0; nb && c < nb && prem + c < taille; ++c) pere[prem + c] = i;
                    }
                    uint32_t chemin[64], prof = 0;
                    for (uint32_t i = cible; i != 0xffffffffu && prof < 64u; i = pere[i]) chemin[prof++] = i;
                    for (uint32_t p = prof; p-- > 1u;) {
                        const uint32_t i = chemin[p], w3 = mot_c(i);
                        fprintf(stderr, "[XANIM-ARBRE]   noeud idx %u : enfants=%u drapeaux=0x%04x premier=%u%s\n", i,
                                nb_enf(i), w3 & 0xffffu, w3 >> 16, (w3 & 1u) ? "   <- bit 0 (loopsync)" : "");
                    }
                    if (prof >= 2u) {
                        const uint32_t pe = chemin[1], nb = nb_enf(pe), prem = mot_c(pe) >> 16;
                        for (uint32_t c = 0; c < nb && c < 64u; ++c) {
                            const uint32_t i = prem + c, w3 = mot_c(i);
                            if (nb_enf(i))
                                fprintf(stderr, "[XANIM-ARBRE]     soeur idx %u : NOEUD enfants=%u drapeaux=0x%04x\n",
                                        i, nb_enf(i), w3 & 0xffffu);
                            else
                            {
                                // P736 : ou vit le nom, et ce bloc du tas invite est-il libere/reutilise ?
                                const uint32_t pn = w3 ? win32_mem_read32(w3) : 0u;
                                uint32_t hb = 0, hs = 0;
                                int hf = 0, hr = 0;
                                win32_heap_owner_locked(pn, &hb, &hs, &hf, &hr);
                                fprintf(stderr, "[XANIM-ARBRE]     soeur idx %u : parts=0x%08x boucle=%u nom@0x%08x "
                                        "tas=[0x%08x+0x%x libere=%d reutilise=%d] nom=\"%s\"%s\n",
                                        i, w3, w3 ? win32_mem_read8(w3 + 0x10u) : 0u, pn, hb, hs, hf, hr,
                                        nom(w3).c_str(), i == cible ? "   <- LEVEE" : "");
                            }
                        }
                    }
                    if (const char* chemin_vidage = bo2_getenv("BO2_XANIM_DUMP")) {
                        char nomf[512];
                        snprintf(nomf, sizeof nomf, "%s.%d", chemin_vidage, n);
                        if (FILE* fo = fopen(nomf, "w")) {
                            for (uint32_t i = 0; i < taille; ++i) {
                                const uint32_t e = ent(i), w3 = mot_c(i);
                                fprintf(fo, "%u %d %08x %08x %08x %08x", i, (int)pere[i], win32_mem_read32(e),
                                        win32_mem_read32(e + 4u), win32_mem_read32(e + 8u), w3);
                                if (!nb_enf(i))
                                    fprintf(fo, " boucle=%u nom@%08x nom=%s", w3 ? win32_mem_read8(w3 + 0x10u) : 0u,
                                            w3 ? win32_mem_read32(w3) : 0u, nom(w3).c_str());
                                fprintf(fo, "\n");
                            }
                            fclose(fo);
                            fprintf(stderr, "[XANIM-ARBRE] vidage complet -> %s\n", nomf);
                        }
                    }
                }
            }
            fprintf(stderr, "\n🎯 [COM-ERROR #%d] level=%u fmt=\"%s\" a2=\"%s\" a3=\"%s\" "
                    "— this is what parks SV_Frame on [0x287bb30]\n\n", n, level, f, a2, a3);
    }
    static bool s_tolerate = bo2_getenv("BO2_TOLERATE_SCRIPT_ERR") != nullptr;
    bool script_err = s_tolerate && (is_scripterr(f) || is_scripterr(a2) || is_scripterr(a3));
    if (script_err) {
        static int hit = 0;
        if (hit++ < 8)
            fprintf(stderr, "[COM-ERROR-SKIP] non-fatal: level=%u fmt=\"%s\" a2=\"%s\"\n", level, f, a2);
        s->gpr.rax.dword = 0;      // cdecl: caller cleans the pushed args
        return mem;                // return to caller instead of the fatal longjmp
    }
    return sub_444650_impl(s, pc, mem);
}

// --- Interpose the GSC function resolver FUN_00479b90(nsIndex=[esp+4], nameHi=[esp+8],
// nameLo=[esp+0xc]) → export handle (0 = unresolved). Bucket = [0x2f3b500 + nsIndex*512]
// then +(nameHi*0x65+nameLo & 0x7fff)*2. When it returns 0 we log the key + whether the
// namespace's bucket table is even allocated — to diagnose why war_room_util.gsc's export
// holo_table_feature_prop (its definer IS loaded + registered as type-48) fails to resolve
// for frontend_sf_a.gsc's import: a namespace-index mismatch, a name-hash bug, or the
// export never being registered (script asset loaded but not GSC-linked). Bounded log.
extern uint64_t g_e160_calls, g_e160_notfound, g_e160_nullval;
extern uint64_t g_e880_calls, g_e880_notfound, g_e880_obj0;
uint64_t g_e880_calls, g_e880_notfound, g_e880_obj0;
// 🎯 P591.1 — QUELLE BRANCHE DE Scr_KillThread APPELLE LE DETACHEMENT.
//
// Le desassemblage exact de sub_87e880 donne la pile au point de sonde :
//   entree E ; sub esp,0x10 ; push ebx,ebp,esi,edi ; push ebx,esi ; call (non
//   nettoye) ; push eax,edx,esi ; call ; push eax,esi ; call ; push ebx,ebp,esi
//   ; call ; push eax,esi ; call ; push eax,edi,esi ; call 0x479b90
// soit sp = E - 0x60, donc `mem32(sp + 0x60)` EST l'adresse de retour de
// sub_87e880 : 0x00495795 = chemin A (type==0xb, ne libere RIEN) et 0x004957be
// = chemin B (libere). Contre-temoin interne qui valide l'offset : a 0x87e8a8 le
// code ecrit [esp+0x2c] et [esp+0x30] avec esp = E-52, soit E-8 et E-4, pile
// dans les 16 octets reserves par le `sub esp,0x10` d'entree.
//
// ⚠️ ON IMPRIME LES VALEURS BRUTES, pas deux compteurs nommes : un offset de
// pile calcule a la main est exactement l'erreur que ce depot a deja payee trois
// fois, et elle se voit d'un coup d'oeil si la valeur n'est pas une adresse de
// .text plausible. Cout : une lecture memoire sur un chemin deja hooke.
uint32_t g_e880_ret[8]; uint64_t g_e880_ret_n[8], g_e880_ret_lost;

// 🎯 P592 — NOMMER l'enfant immortel et son parent.
//
// P591.1 a etabli QUELLE branche boucle ; il reste QUI ne meurt pas. Le crochet
// vit dans FindVariable appele par sub_87e880, donc toute la pile de
// Scr_KillThread est a portee. Le seul point d'ancrage valide est sp+0x60, qui
// porte l'adresse de retour de sub_87e880 — verifie par la mesure : les deux
// seules valeurs lues y sont 0x495795 et 0x4957be, dont la somme vaut
// EXACTEMENT le nombre d'appels. L'adresse INVITEE (sp+0x60) vaut donc E-32 en
// chemin A et E-24 en chemin B, ou E est l'entree de Scr_KillThread :
//
//   chemin A : 0x495784 push ebx ; 0x495785 push esi ; call 0x4f9770
//              0x49578d push edi ; 0x495790 call 0x87e880      -> E-32
//   chemin B : 0x4957b6 push edi ; 0x4957b9 call 0x87e880      -> E-24
//
// d'ou, avec arg2 de Scr_KillThread en E+8 :
//   index de pool de l'enfant : sp+0x64 (les deux chemins)
//   enregistrement de valeur  : sp+0x6c (chemin A seul ; en registre en B)
//   OBJET PARENT              : sp+0x88 (A)  /  sp+0x80 (B)
//
// 🔴 PANNE D'INSTRUMENT CORRIGEE 2026-09-20 apres `runs/a1`, ET C'EST LA FAUTE
// QUE MA PROPRE MEMOIRE `probe-design-rules` DECRIT MOT POUR MOT (« 5e compteur
// ecrete lu comme un total »).
//
// Premiere version : table de 8, remplie par les 8 PREMIERS triplets
// rencontres, tout le reste dans `g_p592_autres`. Sur `runs/a1` — le premier
// gel du depot reproduit avec la sonde armee — elle a imprime :
//
//     [P592]   23396581 passage(s) au-dela des 8 premiers triplets
//     [P592]   <<< SAIN : 8 triplets, le plus repete ne l'est que 1 fois
//
// Les deux lignes se contredisent, et la seconde est fausse. Le demontage
// commence par des dizaines d'enfants SAINS, tues une fois chacun ; ils
// remplissent les 8 places ; l'enfant IMMORTEL arrive 9e et tombe integralement
// dans le debordement. Une table « les N premiers » ne peut STRUCTURELLEMENT
// pas attraper un evenement tardif, aussi enorme soit-il.
//
// Corrige par une politique d'EVICTION : table de 64, et quand elle est pleine
// on chasse l'entree de plus petit compteur — mais seulement si elle vaut 1,
// c'est-a-dire une mort unique, exactement ce qui ne nous interesse pas. Un
// triplet repete des millions de fois entre donc toujours, et ne ressort
// jamais. La voie rapide `g_p592_last` evite de rebalayer 64 entrees 23 M de
// fois : un gel REPETE le meme triplet, donc le cache a une entree suffit.
static const uint32_t kP592Max = 64u;
struct P592Ent { uint32_t par, rec, arg, typ, cle, tagp, tage; uint64_t n; };
P592Ent g_p592[kP592Max]; uint32_t g_p592_n;
uint64_t g_p592_autres, g_p592_evince;
uint32_t g_p592_last = 0xffffffffu;
// 🎯 P550 — LA PREMIERE recherche de `sub_87e880`, celle dont tout depend.
// `sub_61c720` reecrit [esp+0xc] += 0x10000 puis SAUTE vers sub_479b90
// (0x61c720..0x61c72d), donc au retour 0x0087e8b5 la pile porte encore
// [esp+4]=inst, [esp+8]=tete (le registre 0x2f3b818), [esp+0xc]=A|0x10000
// avec A = word[pool + X*8 + 2]. Les trois sondes existantes mesuraient un cran
// trop bas (0x0087e8e8 = la TROISIEME recherche, l'objet vaut deja 0).
// Lecture seule, aucune garde.
uint64_t g_reg_calls[2], g_reg_mort[2], g_reg_viv[2], g_reg_viv_absent[2];
static uint32_t g_reg_vus[2][8][2];   // les 8 premiers couples (tete, A) distincts
static uint32_t g_reg_nvus[2];
extern "C" void* sub_479b90_impl(State*, uint32_t, void*);
extern "C" __attribute__((used)) void* bo2_gsc_resolve(State* s, uint32_t pc, void* mem) {
    // ── 🎯 BO2_KILLTHREAD_CAP=<n> — BREAK THE LOOP THAT ACTUALLY HANGS ────────
    //
    // Measured, after the GSC storm was killed and stopped hiding it:
    //     [DRAIN-TAG] callers of Scr_KillThread: 0x5efdbf x712, 0x559451 x5,
    //                 0x47748e x2   -> 719 calls in the whole run
    //     [FREEVARS]  sub_87e600 entered 1,490,247 times, ALL from 0x004957a0
    //                 (inside Scr_KillThread), and 1,490,062 of those walk ZERO
    //                 entries
    // 719 calls, 1.49M iterations: the hot loop is INSIDE Scr_KillThread, about
    // 2,073 laps per call, and its body does nothing.
    //
    // The loop is 0x495730..0x495822 and its only exit is this function:
    //     0x495818  call 0x479b90        ; FindVariable(inst, obj, key)
    //     0x495820  test eax, eax
    //     0x495822  jne 0x495730         ; go round again while it still FINDS
    // so it spins while the lookup keeps succeeding on something the body cannot
    // remove. That is the August diagnosis — "Scr_KillThread does nothing, for
    // ever" — located to the instruction at last.
    //
    // Returning 0 from THIS call site after n laps makes the loop exit. The
    // object keeps whatever the body failed to remove, which leaks; the engine
    // stops burning a million laps on it. Gated on the exact return address
    // 0x49581d so no other resolve is touched, and off by default.
    // ── 🎯 [LOOP-OBJ] — WHAT DOES THE LOOP KEEP FINDING? (always on, own cap) ──
    //
    // Answers, without BO2_ITER (which the notes above record as perturbing five
    // runs in a row) and without a new interpose: this function IS the loop's
    // exit test, at return addresses 0x495715 and 0x49581d.
    //
    // The August note reached the same loop from the other end and named its
    // object: 0x0003, key 0x16000, variable 0x0075. Tonight [THREAD-WATCH] read
    // the storming thread's self at creation as 0x0003 — the SAME object. If the
    // tally below agrees, the two blockers are one removal failure seen from two
    // ends, which is what the counters have been hinting at all night.
    //
    // It also prints the GATE. A comment beside [DRAIN-RC] records that
    // sub_87e160 SKIPS its unlink when word[var*8+2] is non-zero (0x87e185,
    // 0x87e19f) — and that is the very word bo2_selfnull measures as the "self".
    // So a non-zero gate here and a zero self there are the same field failing
    // in opposite directions.
    {
        // ⚠️ CAP BY RELEVANCE, NOT ARRIVAL — the first version printed the first
        // 24 hits and spent every one of them at BOOT on site 0x495715 sweeping
        // objects 0x006c downwards. The loop's exit test is 0x49581d, and what
        // matters is which (obj,key) it keeps coming back to, so: tally, do not
        // print, and report at exit.
    // ── 🎯 P536 — POURQUOI `sub_87e160` RECOIT-IL L'OBJET NUL ? ────────────────
    //
    // Mesure runs/p535 : `[RMVAR-0] ... obj=0x00000000 ... appelant2=0x0087e179`
    // dit que `edi` vaut 0 a l'entree de `sub_87e160`. Sa porte fait alors
    // `0x664550(inst, 0)` = `word[pool + 0*8 + 2]` = LA TETE DE LA LISTE LIBRE,
    // non nulle tant qu'un enregistrement est libre ⇒ `0x87e185 jne` part en
    // retour anticipe a chaque tour et les deux `RemoveVariable` (0x48a750) ne
    // s'executent JAMAIS. C'est la cause du tour sans fin de Scr_KillThread.
    //
    // `edi` est pose deux instructions avant l'appel :
    //     0x87e90b  call 0x479b90        ; FindVariable -> eax     (retour 0x87e910)
    //     0x87e912  call 0x62bb70        ; dword[[inst<<9+0x2f3b580] + eax*16]
    //     0x87e923  mov edi, eax
    // Deux causes possibles, et une seule mesure les separe : la recherche rend
    // 0 (nom absent), ou elle rend un index et c'est la TABLE DE VALEURS qui
    // porte 0. On lit les deux ici, au retour de 0x479b90.
    //
    // ⚠️ AUCUNE GARDE. Forcer la porte ouverte ferait tourner `RemoveVariable`
    // sur l'objet nul, c'est-a-dire sur la liste libre elle-meme.
    // 🔴 ET LE SITE AMONT, AJOUTE APRES LA PREMIERE MESURE. runs/p536 a rendu
    // `FindVariable(inst=0, obj=0x0000, cle=0x059ca) ABSENT` 96 800 346 fois :
    // l'objet valait DEJA 0 en entrant. Il vient de la PREMIERE recherche de
    // `sub_87e880` (0x87e8e3, retour 0x87e8e8), dont le resultat passe par
    // 0x62bb70 puis sert d'objet a la seconde. Mesurer la seconde ne pouvait
    // donc que constater un zero deja pose — troisieme fois cette session que je
    // mesure un cran trop bas.
    // 🎯 P550 — le retour de la PREMIERE recherche de sub_87e880 (via le saut
    // de queue de sub_61c720). On separe registre VIVANT / registre MORT : le
    // demontage annule `tete` a 0x0047751c, une instruction avant le balayage,
    // donc tout appel a tete==0 est structurellement condamne, sur Windows
    // comme chez nous. Seuls les appels a tete!=0 disent quelque chose.
    if (__builtin_expect(win32_mem_read32(s->gpr.rsp.dword) == 0x0087e8b5u, 0)) {
        const uint32_t sp = s->gpr.rsp.dword;
        const uint32_t ns = win32_mem_read32(sp + 4u) & 1u;
        const uint32_t te = win32_mem_read32(sp + 8u) & 0xffffu;
        const uint32_t ky = win32_mem_read32(sp + 0xcu);
        void* r = sub_479b90_impl(s, pc, mem);
        const uint32_t res = s->gpr.rax.dword & 0xffffu;
        ++g_reg_calls[ns];
        if (!te) ++g_reg_mort[ns];
        else {
            ++g_reg_viv[ns];
            if (!res) ++g_reg_viv_absent[ns];
            const uint32_t A = ky & 0xffffu;   // A = word[pool + X*8 + 2]
            uint32_t k = 0;
            for (; k < g_reg_nvus[ns]; ++k)
                if (g_reg_vus[ns][k][0] == te && g_reg_vus[ns][k][1] == A) break;
            if (k == g_reg_nvus[ns] && g_reg_nvus[ns] < 8u) {
                g_reg_vus[ns][k][0] = te; g_reg_vus[ns][k][1] = A;
                ++g_reg_nvus[ns];
                fprintf(stderr, "🎯 [REG-VIVANT] inst=%u tete=0x%04x A=word[rec+2]=0x%04x "
                        "cle=0x%05x -> %s(0x%04x)\n",
                        ns, te, A, ky & 0xfffffu, res ? "TROUVE" : "ABSENT", res);
            }
        }
        return r;
    }
    if (__builtin_expect(win32_mem_read32(s->gpr.rsp.dword) == 0x0087e8e8u, 0)) {
        const uint32_t sp = s->gpr.rsp.dword;
        const uint32_t ns = win32_mem_read32(sp + 4u);
        const uint32_t ob = win32_mem_read32(sp + 8u) & 0xffffu;
        const uint32_t ky = win32_mem_read32(sp + 0xcu) & 0xfffffu;
        void* r = sub_479b90_impl(s, pc, mem);
        const uint32_t res = s->gpr.rax.dword & 0xffffu;
        ++g_e880_calls;
        if (!res) ++g_e880_notfound;
        if (!ob)  ++g_e880_obj0;
        {
            const uint32_t rt = win32_mem_read32(sp + 0x60u);
            uint32_t k = 0;
            for (; k < 8u && g_e880_ret_n[k]; ++k)
                if (g_e880_ret[k] == rt) break;
            if (k < 8u) { g_e880_ret[k] = rt; ++g_e880_ret_n[k]; }
            else ++g_e880_ret_lost;

            // P592 : qui est l'enfant qui ne meurt pas, et de qui est-il l'enfant ?
            if (rt == 0x00495795u || rt == 0x004957beu) {
                const bool  a   = (rt == 0x00495795u);
                const uint32_t par = win32_mem_read32(sp + (a ? 0x88u : 0x80u)) & 0xffffu;
                const uint32_t arg = win32_mem_read32(sp + 0x64u) & 0xffffu;
                const uint32_t rec = a ? (win32_mem_read32(sp + 0x6cu) & 0xffffu) : 0u;
                // voie rapide : un gel repete le MEME triplet des millions de
                // fois de suite, on ne rebalaye pas la table a chaque tour
                if (g_p592_last < g_p592_n && g_p592[g_p592_last].par == par
                    && g_p592[g_p592_last].rec == rec && g_p592[g_p592_last].arg == arg) {
                    ++g_p592[g_p592_last].n;
                } else {
                    uint32_t j = 0;
                    for (; j < g_p592_n; ++j)
                        if (g_p592[j].par == par && g_p592[j].rec == rec && g_p592[j].arg == arg) break;
                    if (j < g_p592_n) { ++g_p592[j].n; g_p592_last = j; }
                    else {
                        uint32_t slot = 0xffffffffu;
                        if (g_p592_n < kP592Max) {
                            slot = g_p592_n++;
                        } else {
                            // table pleine : chasser le plus petit compteur, et
                            // SEULEMENT s'il vaut 1 (une mort unique, donc saine).
                            // Une entree deja repetee n'est jamais evincee.
                            uint32_t mn = 0;
                            for (uint32_t k = 1; k < kP592Max; ++k)
                                if (g_p592[k].n < g_p592[mn].n) mn = k;
                            if (g_p592[mn].n <= 1ull) { slot = mn; ++g_p592_evince; }
                        }
                        if (slot == 0xffffffffu) { ++g_p592_autres; }
                        else {
                            const uint32_t t580 = win32_mem_read32(0x2f3b580u + ((ns & 1u) << 9));
                            const uint32_t pool = win32_mem_read32(0x2f3b400u + ((ns & 1u) << 9));
                            P592Ent& e = g_p592[slot];
                            e.par = par; e.rec = rec; e.arg = arg; e.n = 1;
                            e.typ = (rec && t580) ? win32_mem_read8(t580 + rec * 16u + 6u) : 0xffu;
                            e.cle = (rec && t580) ? win32_mem_read32(t580 + rec * 16u + 8u) : 0u;
                            e.tagp = pool ? (win32_mem_read32(pool + par * 8u + 4u) & 0x7fu) : 0xffu;
                            e.tage = pool ? (win32_mem_read32(pool + arg * 8u + 4u) & 0x7fu) : 0xffu;
                            g_p592_last = slot;
                        }
                    }
                }
            }
        }
        if (g_e880_calls <= 6ull || (g_e880_calls & (g_e880_calls - 1ull)) == 0ull) {
            char b[96]; const char* nm = sl_key_label_inst(ky, ns, b, sizeof b);
            fprintf(stderr, "🎯 [E880-AMONT] #%llu inst=%u obj=0x%04x cle=0x%05x \"%s\" -> %s(0x%04x)\n",
                    (unsigned long long)g_e880_calls, ns, ob, ky, nm ? nm : "?",
                    res ? "TROUVE" : "ABSENT", res);
        }
        return r;
    }
    if (__builtin_expect(win32_mem_read32(s->gpr.rsp.dword) == 0x0087e910u, 0)) {
        const uint32_t sp = s->gpr.rsp.dword;
        const uint32_t ns = win32_mem_read32(sp + 4u);
        const uint32_t ob = win32_mem_read32(sp + 8u) & 0xffffu;
        const uint32_t ky = win32_mem_read32(sp + 0xcu) & 0xfffffu;
        void* r = sub_479b90_impl(s, pc, mem);
        const uint32_t res = s->gpr.rax.dword & 0xffffu;
        uint32_t t580 = 0, val = 0;
        if (ns < 2u) {
            t580 = win32_mem_read32(0x2f3b580u + (ns << 9));
            if (t580 && res) val = win32_mem_read32(t580 + res * 16u);
        }
        ++g_e160_calls;
        if (!res)      ++g_e160_notfound;      // P536.a
        else if (!val) ++g_e160_nullval;       // P536.b
        if (g_e160_calls <= 6ull || (g_e160_calls & (g_e160_calls - 1ull)) == 0ull) {
            char b[96]; const char* nm = sl_key_label_inst(ky, ns, b, sizeof b);
            fprintf(stderr, "🎯 [E160-OBJ] #%llu inst=%u obj=0x%04x cle=0x%05x \"%s\" -> "
                    "FindVariable=%s(0x%04x)  table[0x%08x + 0x%04x*16]=0x%08x  => edi=%s\n",
                    (unsigned long long)g_e160_calls, ns, ob, ky, nm ? nm : "?",
                    res ? "TROUVE" : "ABSENT", res, t580, res, val,
                    val ? "non nul" : "0 (la porte se fermera)");
        }
        return r;
    }
        {
            const uint32_t r0 = win32_mem_read32(s->gpr.rsp.dword);
            if (__builtin_expect(r0 == 0x0049581du, 0)) {
                const uint32_t o = win32_mem_read32(s->gpr.rsp.dword + 8u) & 0xffffu;
                // ⚠️ do NOT mask the key to 16 bits: the August note records it
                // as 0x16000 and a 16-bit mask prints 0x6000, which reads like a
                // different key. Keep the low 20 bits.
                const uint32_t k = win32_mem_read32(s->gpr.rsp.dword + 0xcu) & 0xfffffu;
                const uint32_t ins = win32_mem_read32(s->gpr.rsp.dword + 4u);
                int i = 0;
                for (; i < 12 && g_lo_n[i]; i++)
                    if (g_lo_obj[i] == o && g_lo_k[i] == k && g_lo_inst[i] == ins) { ++g_lo_n[i]; break; }
                if (i < 12 && !g_lo_n[i]) { g_lo_obj[i] = o; g_lo_k[i] = k; g_lo_inst[i] = ins; g_lo_n[i] = 1; }
                else if (i == 12) ++g_lo_lost;
                // 🎯 BIT 7 OF THE TAG gates whether the clear ever runs:
                //   sub_5efd70  shr ecx,7 ; test cl,1 ; je  -> bit CLEAR skips
                //               the call to sub_87cf60 that empties the child list
                //   sub_578b10  shr edx,7 ; test dl,1 ; jne -> bit SET skips the destroy
                // Opposite polarities on one flag. If the looping variable has
                // bit 7 CLEAR its list is never emptied, FindVariable keeps
                // finding it, and the loop cannot exit.
                // The resolver returns a RECORD index; the variable is
                // dword[[0x2f3b580] + rec*16], the tag dword[pool + var*8 + 4].
                if (i < 12 && g_lo_n[i] == 1) {
                    void* rr = sub_479b90_impl(s, pc, mem);
                    const uint32_t rec  = s->gpr.rax.dword & 0xffffu;
                    // 🔴 indexer par l'instance : ces deux globales sont des
                    // TABLEAUX de 0x200 octets par instance (`shl eax,9` dans
                    // sub_664550). Les lire en dur ne donnait que l'instance 0.
                    const uint32_t t580 = (ins < 2u) ? win32_mem_read32(0x2f3b580u + (ins << 9)) : 0u;
                    const uint32_t pool = (ins < 2u) ? win32_mem_read32(0x2f3b400u + (ins << 9)) : 0u;
                    uint32_t var = 0, tag = 0;
                    if (t580 && rec) var = win32_mem_read32(t580 + rec * 16u) & 0xffffu;
                    if (pool && var) tag = win32_mem_read32(pool + var * 8u + 4u);
                    g_lo_var[i] = (uint16_t)var; g_lo_tag[i] = tag;
                    return rr;
                }
            }
        }
        static uint64_t nlo = 0;
        if (false) {
            const uint32_t r0 = win32_mem_read32(s->gpr.rsp.dword);
            if (r0 == 0x00495715u || r0 == 0x0049581du) {
                ++nlo;
                // sub_479b90 reads arg0=[esp+4] as the instance, arg1=[esp+8]
                // as the OBJECT and arg2=[esp+0xc] as the KEY — its own first
                // instructions do `esi = arg1 * 0x65 + arg2`, the hash the
                // August note recorded.
                fprintf(stderr, "[LOOP-OBJ] #%llu site=0x%06x inst=%u obj=0x%04x key=0x%04x\n",
                        (unsigned long long)nlo, r0,
                        win32_mem_read32(s->gpr.rsp.dword + 4u),
                        win32_mem_read32(s->gpr.rsp.dword + 8u) & 0xffffu,
                        win32_mem_read32(s->gpr.rsp.dword + 0xcu) & 0xffffu);
            }
        }
    }
    {
        static const long cap = [] {
            const char* e = bo2_getenv("BO2_KILLTHREAD_CAP");
            return e ? atol(e) : 0L;
        }();
        if (__builtin_expect(cap > 0, 0)
            && win32_mem_read32(s->gpr.rsp.dword) == 0x0049581du) {
            static uint64_t laps = 0;
            if ((long)(++laps) > cap) {
                if (++g_ktc_cut <= 4)
                    fprintf(stderr, "\n🎯 [KILLTHREAD-CAP] the loop at 0x495730 has run %llu laps; "
                            "returning 0 from FindVariable so Scr_KillThread can leave. Whatever "
                            "its body could not remove now leaks.\n", (unsigned long long)laps);
                s->gpr.rax.dword = 0;
                s->gpr.rsp.dword += 4;      /* cdecl: pop the return address, args left to caller */
                return mem;
            }
        }
    }
    uint32_t esp = s->gpr.rsp.dword;
    uint32_t ns = win32_mem_read32(esp + 4), hi = win32_mem_read32(esp + 8), lo = win32_mem_read32(esp + 0xc);
    uint32_t ret = win32_mem_read32(esp);
    // 🎯 DOES THIS PRESERVE ESI? 0x883790 keeps the GSC VM instance in esi across
    // 🎯 ONE KEY, ONE COMPARE. This path runs 184M times a run, so the filter is a
    // single equality on the key and everything else stays behind it. It answers
    // the question the record scan could not: the resolver stores only key>>8, so
    // 170 records "matched" a key that only shares its high byte. Here the FULL
    // key is an argument, and the object comes with it.
    // 🎯 WHICH OBJECTS DOES THE SCRIPT WORLD ACTUALLY USE? The freeze is a field
    // written on object 0x0003 (65 fields) and read on 0x002f (2007 fields), so
    // the question is what those two ARE. A histogram of object ids across the
    // resolver names them by weight: `level` cannot help but dominate. One
    // increment into a 64-entry array per call, no branch on the hot path beyond
    // a bounds check.
    {
        extern uint64_t g_obj_hist[64];
        if (hi < 64u) ++g_obj_hist[hi];
    }
    // 🎯 THE BIRTH OF AN OBJECT. BO2_OBJ_FIRST=<hex> prints the guest call chain the
    // FIRST time an object id is seen by the resolver — which is as close to its
    // creation as this path gets. Suggested by Gemini and worth doing: I had been
    // chasing the missing assignment and not the object's origin.
    // ⚠️ Its rationale does not survive measurement, though: object 0x002f owns
    // 2007 fields, so it is a long-lived table, not a freshly spawned entity that
    // forgot to link an anim table.
    {
        static const uint32_t want_obj = [] {
            const char* e = bo2_getenv("BO2_OBJ_FIRST");
            return e ? (uint32_t)strtoul(e, nullptr, 16) : 0u;
        }();
        if (__builtin_expect(want_obj != 0u && hi == want_obj, 0)) {
            static bool said_o = false;
            if (!said_o) {
                said_o = true;
                fprintf(stderr, "\n🎯 [OBJ-FIRST] object 0x%04x first seen by the resolver "
                        "(ns=%u key=0x%04x) — guest return chain:", hi, ns, lo);
                const uint32_t sp = s->gpr.rsp.dword;
                int shown = 0;
                for (uint32_t q = sp; q < sp + 0x600u && shown < 14; q += 4u) {
                    const uint32_t rv = win32_mem_read32(q);
                    if (rv >= 0x401000u && rv < 0xa31000u) { fprintf(stderr, " %08x", rv); ++shown; }
                }
                fprintf(stderr, "\n\n");
            }
        }
    }
    {
        static const uint32_t want = [] {
            const char* e = bo2_getenv("BO2_RESOLVE_KEY");
            return e ? (uint32_t)strtoul(e, nullptr, 16) : 0u;
        }();
        // 🎯 BO2_FIELD_ALIAS=1 — TEST THE DIAGNOSIS BY ITS CONSEQUENCE.
        //
        // The field exists on object 0x0003 and the freezing loop reads it on
        // 0x002f. If that identity mismatch is really the cause, then retrying the
        // failed lookup against 0x0003 must clear the freeze — and if it does not,
        // the diagnosis is wrong however well it fits. This is an EXPERIMENT, not a
        // repair: aliasing one object's fields onto another is not something to
        // ship, it is the cheapest way to find out whether the whole chain holds.
        // 🎯 BO2_FIELD_ALIAS=1 — FORWARD THE FIELD, WITHOUT RE-RESOLVING.
        //
        // First attempt retried the lookup against object 0x0003, which meant
        // calling sub_479b90 TWICE; that resolver is not idempotent and angola
        // stopped loading (gscRun=0, draws=4). The obstacle was the retry, not the
        // idea — and the retry is avoidable: a successful resolve on 0x0003 RETURNS
        // the record index, so remember it and substitute that value when the same
        // key misses on another object. One call, no second pass, no state advanced
        // twice.
        //
        // This is a SEMANTIC PATCH, not a repair: the script's assignment still
        // never happens on 0x002f. It answers whether the identity mismatch is the
        // whole story — if the loop ends and angola plays on, it is.
        static const bool alias = bo2_getenv("BO2_FIELD_ALIAS") != nullptr;
        // Remember the record the key resolves to on the object that HAS it.
        static uint32_t cached_rec = 0;
        extern uint32_t g_seed_src_rec;
        if (__builtin_expect(alias && want != 0u && lo == want, 0)) {
            void* r0 = sub_479b90_impl(s, pc, mem);
            const uint32_t got = s->gpr.rax.dword;
            if (got && hi == 0x0003u) { cached_rec = got; g_seed_src_rec = got; }
            if (!got && hi != 0x0003u && cached_rec) {
                s->gpr.rax.dword = cached_rec;                  // forward it
                static uint32_t na2 = 0;
                if (na2++ < 4)
                    fprintf(stderr, "🎯 [FIELD-ALIAS] key=0x%04x missed on obj=0x%04x — "
                            "forwarded record 0x%04x from obj 0x0003 (no re-resolve)\n",
                            lo, hi, cached_rec);
            }
            return r0;
        }
        if (0) {
            void* r0 = sub_479b90_impl(s, pc, mem);
            if (s->gpr.rax.dword == 0u) {
                // ⚠️ RESTORE THE CALLER'S STACK. The first version wrote the object
                // id into [esp+8] and left it there — the caller still uses that
                // slot, and the level stopped loading entirely (gscRun=0, draws=4:
                // the frontend). A probe that rewrites guest memory must put it back.
                const uint32_t sp0 = s->gpr.rsp.dword;
                const uint32_t saved = win32_mem_read32(sp0 + 8u);
                win32_mem_write32(sp0 + 8u, 0x0003u);   // retry on 0x0003
                r0 = sub_479b90_impl(s, pc, mem);
                win32_mem_write32(sp0 + 8u, saved);
                static uint32_t na = 0;
                if (na++ < 4)
                    fprintf(stderr, "🎯 [FIELD-ALIAS] key=0x%04x missed on obj=0x%04x, "
                            "retried on 0x0003 -> 0x%08x\n", lo, hi, s->gpr.rax.dword);
            }
            return r0;
        }
        // 🎯 ARM THE STORE WATCH ON THE HASH BUCKET THAT WILL HOLD THIS FIELD.
        //
        // Neither create-or-find entry in the family (bo2_gsc_newvar,
        // bo2_gsc_childvar) ever fires for this key, so the record is created
        // inside sub_479b90 itself and no interpose can see it. But the resolver
        // hashes (obj*0x65 + key) & 0x7fff into the bucket table at
        // [inst<<9 + 0x2f3b500], so the creation MUST write there — and a store
        // watch names its writer with a host backtrace.
        //
        // Armed on the first miss, which is exactly the moment before creation, so
        // the watch exists only in the window that matters (the same trick that
        // caught the sound-canary writer earlier today).
        if (__builtin_expect(want != 0u && lo == want && bo2_getenv("BO2_BUCKET_WATCH") != nullptr, 0)) {
            static bool armed_b = false;
            if (!armed_b) {
                armed_b = true;
                const uint32_t t500 = 0x2f3b500u + (ns << 9);
                const uint32_t bucket = ((hi * 0x65u) + lo) & 0x7fffu;
                const uint32_t addr = win32_mem_read32(t500) + bucket * 4u;
                if (g_wwn < 0) ww_parse();
                if (g_wwn < kWwMax) {
                    g_ww[g_wwn++] = addr;
                    fprintf(stderr, "\n🎯 [BUCKET-WATCH] key=0x%04x obj=0x%04x hashes to bucket "
                            "%u at 0x%08x — the store watch is armed there NOW, so whatever "
                            "creates this field is named with its call chain.\n\n",
                            lo, hi, bucket, addr);
                }
            }
        }
        if (__builtin_expect(want != 0u && lo == want, 0)) {
            static uint32_t n2 = 0, found = 0, miss = 0;
            void* r2 = sub_479b90_impl(s, pc, mem);
            const uint32_t res = s->gpr.rax.dword;
            // Publish the source record here, not only under the abandoned alias
            // path — the seed hook needs it and my first wiring left it at zero, so
            // the seed could never fire whatever the key.
            { extern uint32_t g_seed_src_rec;
              if (res && hi == 0x0003u) g_seed_src_rec = res; }
            if (res) ++found; else ++miss;
            if (n2++ < 8)
                fprintf(stderr, "🎯 [RESOLVE-KEY] ns=%u obj=0x%04x key=0x%04x ret=0x%08x -> %s (0x%08x)\n",
                        ns, hi, lo, ret, res ? "FOUND" : "NOT FOUND", res);
            // Watch the record's VALUE word on the object that ends up holding a real
            // value. The reader creates the slot undefined (0x87a352 `mov [ebx],0`),
            // so whatever writes a non-zero type into it afterwards is the assignment
            // — the thing that never happens on object 0x002f. Armed once, on the
            // first successful resolve, which is the moment the record exists.
            // ⚠️ ARM LATE. A store watch armed early costs the level its load — the
            // first attempt here never got past the frontend, so its one [WW] hit
            // was frontend traffic and told us nothing about the campaign.
            // BO2_VALUE_WATCH=<N> waits for the Nth successful resolve.
            if (res && bo2_getenv("BO2_VALUE_WATCH")) {
                static const long arm_at = [] {
                    const char* e = bo2_getenv("BO2_VALUE_WATCH");
                    const long v = e ? atol(e) : 1L;
                    return v > 0 ? v : 1L;
                }();
                static long seen_ok = 0;
                static bool armed_v = false;
                if (!armed_v && ++seen_ok >= arm_at) {
                    armed_v = true;
                    const uint32_t t580 = win32_mem_read32(0x2f3b580u + (ns << 9));
                    const uint32_t addr = t580 + res * 16u;
                    if (g_wwn < 0) ww_parse();
                    if (g_wwn < kWwMax) {
                        g_ww[g_wwn++] = addr;
                        fprintf(stderr, "\n[VALUE-WATCH] record 0x%04x for key 0x%04x on obj 0x%04x "
                                "lives at 0x%08x — watching its value word for the assignment\n\n",
                                res, lo, hi, addr);
                    }
                }
            }
            // 🎯 WHAT DOES THE FAILING OBJECT ACTUALLY HOLD? An object carrying
            // dozens of sibling anim keys but not this one is an INCOMPLETE animset;
            // a nearly empty one is a wrongly-built object. The two need opposite
            // fixes, and one scan of the record table separates them. Once, on the
            // first miss only.
            // ⚠️ Profile the object that actually FAILS, not the first miss. The
            // first miss is object 0x0003 immediately before the field is created
            // there — profiling it answered a question nobody asked.
            static bool profiled = false;
            if (!res && !profiled && hi != 0x0003u) {
                profiled = true;
                const uint32_t t580 = win32_mem_read32(0x2f3b580u + (ns << 9));
                uint32_t mine = 0, other = 0;
                if (t580) {
                    for (uint32_t r = 1; r < 0x8000u; ++r) {
                        const uint32_t tag = win32_mem_read32(t580 + r * 16u + 8u);
                        if (!tag) continue;
                        if ((tag >> 16) == hi) ++mine; else ++other;
                    }
                }
                fprintf(stderr, "[RESOLVE-KEY]   object 0x%04x owns %u field(s); "
                        "%u belong to other objects%s\n", hi, mine, other,
                        mine ? "" : "  <== this object has NO fields at all");
            }
            if ((n2 % 4000u) == 0)
                fprintf(stderr, "[RESOLVE-KEY] so far: %u found, %u NOT found\n", found, miss);
            return r2;
        }
    }
    // `call 0x479b90` (0x8837ac) and `call 0x62bb70` (0x8837ba) and then calls
    // 0x8833e0 at 0x8837c0 — where esi IS the instance, since 0x8833e0 takes only
    // ONE stack argument (eax) and reads esi as a register argument. esi is
    // callee-saved in cdecl, so either of those two failing to restore it puts a
    // foreign value into the VM. The six callees INSIDE 0x8833e0 were checked
    // (386,306 calls, 0 violations); these two never were.
    const uint32_t esi_in = s->gpr.rsi.dword;
    void* r = sub_479b90_impl(s, pc, mem);
    if (__builtin_expect(s->gpr.rax.dword == 0u, 0)) resolve_miss_note(hi, lo);   // uncapped miss histogram
    {   extern uint64_t g_r90_n, g_r90_bad; extern uint32_t g_r90_i, g_r90_o;
        ++g_r90_n;
        if (__builtin_expect(s->gpr.rsi.dword != esi_in, 0)) {
            ++g_r90_bad; g_r90_i = esi_in; g_r90_o = s->gpr.rsi.dword;
        }
    }
    // Arm BO2_WATCH_VAR as soon as the GSC tables map. Rate-limited: this rides a
    // 184M-call path, so it retries only every 4096 calls until it succeeds, and
    // costs one predictable branch after that.
    {
        static bool armed = false;
        static uint32_t tick = 0;
        if (!armed && ((tick++ & 0xfffu) == 0)) {
            const bool a1 = ww_arm_var_slot(ns);
            const bool a2 = ww_arm_rc_slot(ns);
            (void)ww_arm_sl_slot();
            armed = a1 || a2;
        }
    }
    // ── [REG-TRACE] does the shutdown registry EVER shrink? ──────────────────
    //
    // The teardown hangs on an entry naming an object that was legitimately
    // freed. That leaves exactly two possibilities: the entry should have been
    // removed earlier by the normal notify/thread-end flow and we are not doing
    // it, or the object should never have reached its last release. A time
    // series of the registry's DEPTH separates them in one run: monotonically
    // rising means nothing ever removes an entry; rising and falling means
    // removal works and one particular entry is the problem.
    //
    // The existing report only runs once the freeze is already happening, which
    // is far too late to see the shape.
    if (bo2_getenv("BO2_REG_TRACE")) {
        static uint64_t rt = 0;
        if ((rt++ % 2000000u) == 0) {
            for (uint32_t inst = 0; inst < 2; inst++) {
                const uint32_t idxt = win32_mem_read32(0x2f3b480u + (inst << 9));
                const uint32_t t580 = win32_mem_read32(0x2f3b580u + (inst << 9));
                const uint32_t head = win32_mem_read32(0x2f3b818u + inst * 0x54u);
                if (!idxt || !t580) continue;
                auto rd = [](uint32_t a3) {
                    return (uint32_t)win32_mem_read8(a3) |
                           ((uint32_t)win32_mem_read8(a3 + 1) << 8);
                };
                uint32_t depth = 0, c = head ? rd(idxt + head * 4u) : 0;
                bool cut = false;
                while (c) { c = rd(t580 + c * 16u + 0xcu); if (++depth > 100000u) { cut = true; break; } }
                static uint32_t peak[2] = {0, 0}, prev[2] = {0, 0};
                if (depth > peak[inst]) peak[inst] = depth;
                const int32_t d = (int32_t)depth - (int32_t)prev[inst];
                prev[inst] = depth;
                fprintf(stderr, "[REG-TRACE] inst=%u head=0x%04x depth=%u (%+d) peak=%u%s%s\n",
                        inst, head, depth, d, peak[inst],
                        d < 0 ? "  🎯 IT SHRANK — removal works" : "",
                        cut ? "  ⚠️ walk hit its 100000 cap, depth is a LOWER BOUND" : "");
            }
        }
    }
    // 🎯 P529 — ce que la queue de la boucle rend, tour apres tour. Ici et pas en
    // haut de l'enveloppe : le retour anticipe du haut ne servait que 12 fois, a
    // 46,5 M de tours il volerait leurs echantillons a g_obj_hist et aux sondes
    // qui suivent. Filtre = une egalite sur l'adresse de retour ; le balayage de
    // 12 entrees ne s'execute que derriere elle. Aucune garde, aucune ecriture.
    if (__builtin_expect(ret == 0x0049581du, 0)) {
        const uint32_t lo_o = hi & 0xffffu, lo_k = lo & 0xfffffu;
        // `esi` porte l'instance tout au long de la boucle (cdecl la preserve) ;
        // c'est la meme lecture que `i2` plus bas.
        const uint32_t lo_i = s->gpr.rsi.dword;
        const uint32_t rec = s->gpr.rax.dword & 0xffffu;
        ++g_lo_laps;
        if (rec == g_lo_prev) {
            ++g_lo_run;
        } else {
            if (g_lo_run > g_lo_smax) {
                g_lo_smax = g_lo_run;
                g_lo_sobj = g_lo_pobj; g_lo_skey = g_lo_pkey; g_lo_srec = g_lo_prev;
                g_lo_sinst = g_lo_pinst;
            }
            g_lo_run = 1; g_lo_prev = rec; ++g_lo_chgall;
            // 🎯 P542 — L'ETAT AU PREMIER TOUR DE LA SERIE, pas au 4096e.
            //
            // P541 a montre que l'enfant du corps pointe sur un enregistrement
            // LIBRE, mais au 4096e tour — or la boucle libere ce meme index a
            // chaque tour, donc le constat au 4096e ne dit pas s'il l'etait deja
            // au premier. Ici on fige l'etat au moment ou la serie COMMENCE :
            // si le pendouillant est deja tagge 0x17 a ce moment-la, le
            // use-after-free preexiste la boucle et sa cause est ailleurs.
            // Cout : quelques lectures par CHANGEMENT de serie (g_lo_chgall),
            // pas par tour. Aucune borne, aucune garde, aucune ecriture invitee.
            {
                const uint32_t i2 = s->gpr.rsi.dword;
                const uint32_t e2 = s->gpr.rdi.dword & 0xffffu;
                const uint32_t p2 = (i2 < 2u) ? win32_mem_read32((i2 << 9) + 0x2f3b400u) : 0u;
                g_lo_s0_lap  = g_lo_laps;
                g_lo_s0_obj  = hi & 0xffffu;
                g_lo_s0_edi  = e2;
                g_lo_s0_pend = (p2 && e2) ? (win32_mem_read32(p2 + e2 * 8u + 2u) & 0xffffu) : 0u;
                g_lo_s0_etag = (p2 && e2) ? (win32_mem_read32(p2 + e2 * 8u + 4u) & 0x1fu) : 0xffu;
                g_lo_s0_ptag = (p2 && g_lo_s0_pend)
                                 ? (win32_mem_read32(p2 + g_lo_s0_pend * 8u + 4u) & 0x1fu) : 0xffu;
            }
        }
        g_lo_pobj = lo_o; g_lo_pkey = lo_k; g_lo_pinst = lo_i;
        // 🎯 [LOOP-STUCK] — LE CLICHE DE L'ETAT BLOQUE, une fois par serie de 2 M.
        //
        // Mesure P530 : 154 213 861 tours sur 154 214 167 portent le MEME
        // enregistrement. Le corps appelle `sub_87e880` a chaque tour (0x4957b9),
        // qui appelle `sub_87e160` (0x87e925), dont les DEUX `RemoveVariable`
        // sont sautes si `word[rec*8+2] != 0` (0x87e185, 0x87e19f). C'est le seul
        // retrait sur le chemin, donc c'est ce mot qui decide de la sortie.
        //
        // Pas besoin d'interposer quoi que ce soit : au test de sortie, `edi`,
        // `ebx` et `ebp` sont encore ceux de la boucle (cdecl les preserve), et
        // `esi` porte l'instance. Lecture pure, declenchee seulement quand le
        // gel est deja prouve par le compteur de serie.
        // ⚠️ LE SEUIL FIXE ETAIT UN PARI, ET IL A RATE. Premier tir a 2 000 000 :
        // runs/p529b faisait 154 213 861 tours, mais runs/p531 s'est arrete a
        // 65 537 (= 0x10001, la signature d'un debordement de mot 16 bits) et le
        // cliche ne s'est jamais imprime. Declenchement geometrique : toutes les
        // puissances de deux a partir de 4096. Au pire 13 clichés sur une serie
        // de 154 M, et l'evolution de l'etat au fil de la serie vient gratuitement.
        if (__builtin_expect(g_lo_run >= 4096ull && (g_lo_run & (g_lo_run - 1ull)) == 0ull, 0)) {
            const uint32_t inst = s->gpr.rsi.dword;
            const uint32_t gedi = s->gpr.rdi.dword & 0xffffu;
            const uint32_t gebx = s->gpr.rbx.dword & 0xffffu;
            const uint32_t pool = win32_mem_read32((inst << 9) + 0x2f3b400u);
            const uint32_t t480 = win32_mem_read32((inst << 9) + 0x2f3b480u);
            const uint32_t head = win32_mem_read32(inst * 0x54u + 0x2f3b818u);
            // 🎯 P563 — l'ENREGISTREMENT 0 N'EST PAS « NUL », C'EST LE SENTINELLE.
            // Son champ +2 est le « next » du sentinelle, donc LA TETE DE LA LISTE
            // LIBRE (win32_runtime.cpp:6962 le dit deja). Or la PORTE #1 de
            // sub_87e160 est `sub_664550(inst, edi) = word[pool + edi*8 + 2]` :
            // si `edi` arrive a 0, cette porte ne lit pas l'enfant d'une variable,
            // elle lit la tete de la liste libre — et une liste libre non vide
            // ferme la porte, donc saute les DEUX retraits, donc soude.
            // L'ancienne version refusait idx==0 et imprimait « pool ou idx nul » :
            // elle excluait exactement l'enregistrement qui decide.
            auto rec = [&](const char* nom, uint32_t i) {
                if (!pool) { fprintf(stderr, "[LOOP-STUCK]   %-10s idx=0x%04x  (pool nul)\n", nom, i); return; }
                if (!i) {
                    const uint32_t tete_libre = win32_mem_read32(pool + 2u) & 0xffffu;
                    fprintf(stderr, "[LOOP-STUCK]   %-10s idx=0x0000  SENTINELLE  "
                            "tete_liste_libre=0x%04x  tag=0x%08x   %s\n", nom, tete_libre,
                            win32_mem_read32(pool + 4u),
                            tete_libre
                              ? "🎯 <<< P563.a VRAI : liste libre NON VIDE, donc tout edi=0 "
                                "ferme la PORTE #1 (0x87e185) et saute les deux retraits"
                              : "<<< P563.a FAUX : liste libre VIDE — la porte #1 ne se ferme "
                                "pas par ce chemin, le raisonnement P563 tombe");
                    return;
                }
                fprintf(stderr, "[LOOP-STUCK]   %-10s idx=0x%04x  rc=%u  enfant[+2]=0x%04x  tag=0x%08x "
                        "type=0x%02x%s\n", nom, i,
                        win32_mem_read32(pool + i * 8u) & 0xffffu,
                        win32_mem_read32(pool + i * 8u + 2u) & 0xffffu,
                        win32_mem_read32(pool + i * 8u + 4u),
                        win32_mem_read32(pool + i * 8u + 4u) & 0x1fu,
                        (win32_mem_read32(pool + i * 8u + 2u) & 0xffffu)
                            ? "   <<< enfant NON NUL : 0x87e185 saute RemoveVariable" : "");
            };
            const uint32_t v0 = s->gpr.rax.dword & 0xffffu;
            fprintf(stderr, "\n[LOOP-STUCK] 🎯 %llu tours consecutifs sur le meme enfant — "
                    "cliche de l'etat bloque\n"
                    "[LOOP-STUCK]   inst=%u obj=0x%04x cle=0x%05x  pool=0x%08x t480=0x%08x "
                    "tete_registre=0x%04x\n",
                    (unsigned long long)g_lo_run, inst, hi & 0xffffu, lo & 0xfffffu, pool, t480, head);
            rec("sentinelle", 0u);          // P563 : la tete de la liste libre
            rec("v0(rendu)", v0);
            rec("edi(corps)", gedi);
            rec("ebx(objet)", gebx);
            if (pool && gedi) rec("enfant(edi)", win32_mem_read32(pool + gedi * 8u + 2u) & 0xffffu);
            if (pool && v0)   rec("enfant(v0)",  win32_mem_read32(pool + v0   * 8u + 2u) & 0xffffu);
            // 🎯 P541 — l'histoire de liberation des trois index qui comptent.
            if (pool) {
                const uint32_t pend = win32_mem_read32(pool + gedi * 8u + 2u) & 0xffffu;
                lf_say("obj", inst, hi & 0xffffu);
                lf_say("edi(corps)", inst, gedi);
                lf_say("pendouillant", inst, pend);
                fprintf(stderr, "[LAP1]   au PREMIER tour de cette serie (tour %llu) : "
                        "obj=0x%04x edi=0x%04x tag(edi)=0x%02x pendouillant=0x%04x "
                        "tag(pend)=0x%02x  => %s\n",
                        (unsigned long long)g_lo_s0_lap, g_lo_s0_obj, g_lo_s0_edi,
                        g_lo_s0_etag, g_lo_s0_pend, g_lo_s0_ptag,
                        g_lo_s0_ptag == 0x17u
                          ? "🎯 LE PENDOUILLANT ETAIT DEJA LIBRE AU PREMIER TOUR — "
                            "l'use-after-free PRECEDE la boucle (P542.a)"
                          : (g_lo_s0_pend == 0u
                               ? "pendouillant NUL au premier tour (P542.c)"
                               : "pendouillant VIVANT au premier tour — c'est la boucle qui le "
                                 "libere ensuite (P542.b)"));
            }
            fprintf(stderr, "[LOOP-STUCK] ==== fin ====\n\n");
        }
        for (int i = 0; i < 12 && g_lo_n[i]; i++) {
            if (g_lo_obj[i] != lo_o || g_lo_k[i] != lo_k || g_lo_inst[i] != lo_i) continue;
            if (rec != g_lo_last[i]) { ++g_lo_chg[i]; g_lo_last[i] = rec; }
            if (rec) {
                if (!g_lo_rmin[i] || rec < g_lo_rmin[i]) g_lo_rmin[i] = (uint16_t)rec;
                if (rec > g_lo_rmax[i]) g_lo_rmax[i] = (uint16_t)rec;
            }
            break;
        }
    }
    if (ret == 0x495715u) gsc_killthread_probe(esp, ns, hi, lo, s->gpr.rax.dword);
    gsc_resolve_drain_watch(ret, ns, hi, lo, s->gpr.rax.dword);
    static const bool resolve_log = bo2_getenv("BO2_GSC_RESOLVE_LOG") != nullptr;
    if (resolve_log && s->gpr.rax.dword == 0) {
        static int fails = 0;
        if (fails++ < 300) {
            uint32_t nsptr = win32_mem_read32(0x2f3b500u + (ns & 0xffffu) * 512u);
            fprintf(stderr, "[GSC-RESOLVE-FAIL #%d] ns=%u hi=0x%x lo=0x%x nsTable=0x%08x caller=0x%08x\n",
                    fails, ns, hi, lo, nsptr, ret);
        } else if (fails == 301) {
            // ⚠️ SAY IT WHEN YOU STOP LOOKING. This cap was hit 60 s into a run
            // whose interesting window began at 140 s, so the probe went silent
            // long before the event it was enabled for — and silence from a
            // capped probe reads exactly like "no failures happened". That is
            // this project's most repeated mistake (guide §"never read an
            // absence off a capped probe"); a probe that caps MUST announce it.
            fprintf(stderr, "[GSC-RESOLVE-FAIL] ⚠️  CAP REACHED at 300 — everything after "
                            "this point is UNOBSERVED, not absent. Raise the cap before "
                            "concluding anything from the silence below.\n");
        }
    }
    return r;
}

// --- 2D/UI draw-chain probes (why does LUI never submit geometry?).
// SCR_UpdateScreen = FUN_00776620 (sole caller of the field draw, @+0x27f);
// SCR_DrawScreenField = FUN_00776340 (clcState switch, "bad clcState" error);
// FUN_007760b0 = the per-state UI draw helper called from most states.
// Count entries + a few samples each: distinguishes "UpdateScreen never runs" /
// "runs but gate blocks the field draw" / "field draw runs but its state draws
// nothing". Always-on (a handful of log lines), cheap counters otherwise.
extern "C" void* sub_776620_impl(State*, uint32_t, void*);
extern "C" void* sub_776340_impl(State*, uint32_t, void*);
extern "C" void* sub_7760b0_impl(State*, uint32_t, void*);
static uint32_t g_scr_update_n = 0, g_scr_field_n = 0, g_scr_uidraw_n = 0;
extern "C" __attribute__((used)) void* bo2_scr_update(State* s, uint32_t pc, void* mem) {
    uint32_t n = ++g_scr_update_n;
    if (n <= 4 || n % 1000 == 0)
        // rendererUp byte[0x33cbc81] gates the whole R_BeginFrame path
        // (FUN_00697510+2); rbReady [0x3823910] gates the scene+2D pass in
        // RB_Exec (0x6ca3c5); initEvt [0x2925574] is the event the backend polls
        // (FUN_004438a0) to run its one-time init FUN_006bd170 that sets rbReady.
        // clcState [0xf6b444] (per-client, stride 0x18): the UI-scene render
        // FUN_00775f20 requires EXACTLY 0xa ("frontend active"); any other value
        // → no viewInfo → the backend draws only the fallback bg quad. This is
        // the last gate found on the no-menu path.
        // uiStarted [0xf6b68c] is the branch in SCR_DrawScreenField that decides
        // whether the UI draw runs at all; when it goes 1 -> 0 the frontend
        // stops drawing while everything else keeps ticking, which is exactly
        // the black screen after the title. Free to report: this line already
        // prints, and "uidraw frozen while field climbs" is what named it.
        fprintf(stderr, "[SCR-UPDATE #%u] tid=%d (field=%u uidraw=%u) rendererUp=%u rbReady=%u initEvt=0x%x clcState=%u uiStarted=%u\n",
                n, win32_current_tid(), g_scr_field_n, g_scr_uidraw_n,
                (unsigned)win32_mem_read8(0x33cbc81u), win32_mem_read32(0x3823910u),
                win32_mem_read32(0x2925574u), win32_mem_read32(0xf6b444u),
                win32_mem_read32(0xf6b68cu));
    return sub_776620_impl(s, pc, mem);
}
extern "C" __attribute__((used)) void* bo2_scr_field(State* s, uint32_t pc, void* mem) {
    uint32_t esp = s->gpr.rsp.dword;
    uint32_t n = ++g_scr_field_n;
    if (n <= 6 || n % 1000 == 0)
        fprintf(stderr, "[SCR-FIELD #%u] tid=%d a1=0x%x a2=0x%x\n",
                n, win32_current_tid(), win32_mem_read32(esp + 4), win32_mem_read32(esp + 8));
    return sub_776340_impl(s, pc, mem);
}
extern "C" __attribute__((used)) void* bo2_scr_uidraw(State* s, uint32_t pc, void* mem) {
    uint32_t n = ++g_scr_uidraw_n;
    if (n <= 6 || n % 1000 == 0)
        fprintf(stderr, "[SCR-UIDRAW #%u] tid=%d\n", n, win32_current_tid());
    return sub_7760b0_impl(s, pc, mem);
}

// --- Probe the backend 2D/composite pass FUN_006c1cd0(ctx=[esp+4], frame=[esp+8]):
// draws the stream/bg quad (switch on [0x33cba78] → texture → FUN_006c0ca0 →
// FUN_006d3830, the ONLY DrawIndexed we ever see), then loops [0x338f848] items
// calling item->vtbl[+0x20] — the per-layer UI render list. If that count is 0
// every frame, the UI layers are never populated (frontend-side gap); if
// nonzero, the layer vfn bails (technique/material gap).
